/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20120606-17","meetingId":"h24-cm06","date":"2012年6月6日","dateIso":"2012-06-06","committee":"震災対策特別委員会","time":"午後１時００分～午後２時３１分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"武内委員","kind":"確認","question":"今、委員長の震災対策は、とおっしゃったんですね。そこをもう１回確認で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"その部分が一番の柱という思いでいたものですから、もう１回ちょっと教えていただきたいのと、常任委員会とのやりとりをもうちょっと教えていただけないかなと思うんですけれども。","respondent":"南委員長","answer":"非常に残念だとおっしゃったわけですけれども、そこは私も副委員長も共通する認識だったんですね。それをしっかり説明を受けて、大事な耐震部分については、触れざるを得ない部分というのも当然出てくると思うんですね。","id":"exchange-002"},{"speaker":"武内委員","kind":"意見","question":"どうしても地域防災計画見直しの中で、火災の部分とか、耐震の部分とかも多少触れざるを得ないところが出てくるかと思うんですね。そういった面ではぜひその辺は柔軟にお願いしたいなと、今、おっしゃっていただいたので、改めてお願いしておきますとの意見を述べました。","respondent":"高山防災計画担当課長、鈴木防災課長","answer":"本日はこの平成１９年度現行計画の品川区地域防災計画の概要と、そして、最後に今年度予定しております改訂スケジュールにつきましてご説明をします。そして品川区防災計画につきましても… スケジュールのほうは、ご覧いただけますように、４月から９月までの約半年間で資料収集および内容の検討を予定しております。９月までの検討の時点で、それを受けまして、１０月以降に具体的な原稿作成作業を始めたいと考えております。","id":"exchange-003"},{"speaker":"武内委員","kind":"質問・要望","question":"ご説明ありがとうございました。随時お知らせいただきたいと思うんですけれども、その辺は可能かどうか、その辺のところを教えてほしいと求めました。","respondent":"高山防災計画担当課長","answer":"確定というものではないにせよ、途中途中で、例えば目次であるとか考え方のようなものをお示ししていければと考えています。意見といったものもしっかりと踏まえて、改訂作業のほうには着手してまいりたいと考えております。","id":"exchange-004"},{"speaker":"武内委員","kind":"質問","question":"通常は大体３月、４月ぐらいにまとめて議長にという形になっているんですけれども、この地域防災計画自体が２月のところですかね。こことか１１月に素案とかというスケジュールになっているので、当然そういうこともあるかなと思うんですけれども、その辺はいかがか尋ねました。","respondent":"南委員長","answer":"少なくとも東京都の防災計画の素案が９月に示され、１１月にまとめ、それを受けて品川区が素案の検討に入っていくわけですね。まとめをその時期にするかどうかは検討してきませんでしたけれども、そういうことが適切である、それはそのように運営したいと考えています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どこまで来ているかというような、そういう検証というんですか、そういうのは区としてはどのようにされているのかをお聞かせほしいと求めました。それをまずお願いします。","respondent":"高山防災計画担当課長","answer":"実は東京都のほうが上位で主にこの３つの目標につきまして、まずは都において、そういった新たな目標を立ててくるかと思います。そういったものを踏まえて、区に落とし込む形で施策などにも実現してつなげてまいりたいと考えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひまとめていただきたいなというのと、５年間、ちょうど半分たちましたのでね。それに対してどう目標を立てて、どう対策をさらに強化をしていくかという、そこら辺のところでの考え方についてもお聞かせほしいと求めました。","respondent":"高山防災計画担当課長","answer":"総合実施計画のローリングでありますとか、この中で数値化できるもの、達成度が図れるものについては集約してまいりたいと考えております。避難者の発生を防ぐ、そういったことも減災目標の柱になっていくのではないかと、そんなふうに考えております。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３２％が焼失するという想定が、こういう対策を強化していきたいとかというところで、今の時点でもしもあればお聞かせほしいと求めました。１１月のときに素案が出されて、きめ細やかな説明会をぜひ開いていただきたいと思うんですが、いかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"スケジュールの中で議会に対する説明ということでに加えて、区民への説明会などの場はどうかですが、これはいろいろ手法はあろうかと思います。そういったことも予定していますので、区民の方々の思いなどを吸い上げていければ、そのように考えております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一般区民向けのそういう説明会というのをぜひ検討していただきたい、やっていただくように要望したいと思います。例えば私は、街頭消火器がどこにあるかという位置をみんなで確認するような取り組みをするだとか、そういう災害をいかに少なくするか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"具体的にはどういうことを考えていらっしゃるのか、この部分についての改訂のイメージというか、どんなことを考えているのか説明を求めました。","respondent":"高山防災計画担当課長","answer":"先だってそういう会議を設けまして、継続的にそういった場を設けましょうということでご了解をいただいているところです。実際に計画には盛り込まれておりますが、検討課題として上がっておりますので、そういったものを一つ一つ丁寧につぶしていきたいと考えております。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"前回のそういった意見が反映されていただいたことはよかったと思いますので、そこら辺を中心に頑張ってほしいと求めました。前回、どういうことが読みやすい形態になるのかということを知る必要があると思いますが、それがこの中にどういうふうに計画されているんか尋ねました。","respondent":"鈴木防災課長","answer":"現時点では、実際にお使いになる区民の方の意見なり要望なりというのは、参考にさせていただきたいと考えております。は内部でも検討のチームを作成いたしまして、そういうところについての全面改訂ぐらいのつもりで検討していきたいということを考えておりますので。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問・要望","question":"ただ助成がありますということでは、はあ、そうですかみたいなところがあるので、情報を、百ではなくても、今だと半分ぐらいだと思うんですね。これはまだちょっと時間がありますので、ぜひ検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"武内委員","kind":"意見","question":"それが平成２５年度に予定だと。前回平成２０年度だったので、平成２５年度にあると思うんですけれども、その辺は何かつかんでいらっしゃるところはありますかとの意見を述べました。","respondent":"高山防災計画担当課長","answer":"東京都のほうが出しますのが平成２４年度末になろうかと考えているんですが、計画そのものに練り込むというのはちょっと難しいかとは思います。続けて平成２５年度についても見直しを行うとか、そういった地域危険度などの最新の情報は反映させてまいりたいと考えております。","id":"exchange-013"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"井上委員","kind":"確認","question":"２点お伺いしたいんですけれども、まず、震災対策特別委員会は今年で２年目という性格があります。もう一つは、こういったところを追加してほしい、そういうことがこの委員会でできるものなのかというところの確認をお願いいたします。","respondent":"南委員長","answer":"あまり細かいところの検討までは委員会の性格ではないので、そういうところなのかなと考えていますけれども、別に制限するつもりはありません。","id":"exchange-014"},{"speaker":"武内委員","kind":"意見","question":"ちょうど１１月と１月と２カ月間があいてしまうので、もし可能ならば、こちらでしっかりやっていったほうがいいんじゃないかと思いますね。それを入れ込んでいただいたほうがいいかなと思いましたとの意見を述べました。","respondent":"南委員長","answer":"９月の下旬なのか、しっかりと当委員会の質疑、検討事項として入れ込んでいきたいと思っています。タイムラグとしては２カ月間、予定をしなくてはいけない、その際は皆さんにもお諮りをしていきたいと思っています。","id":"exchange-015"},{"speaker":"大沢委員","kind":"意見","question":"今の素案の今後の作成をするタイムスケジュール、流れの中で、７月に修正作業、区市町村への意見照会という部分がありますよね。あるいは我々も何らかの関わりを持ちながら、意見照会の部分に参加をできるのかというのはどういうふうにとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"この年間スケジュールが、先ほど示していただきました委員会の特定事件調査日程というのがありまして、この意見照会は７月になりますよね。６月２８日あるいは７月の、ここの２コマの中で、そこのところはお考えいただきながら進めていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回の新しい被害想定の中の死者数が４.何倍に増えているわけですけれども、その多くが火災による死者が５倍に増えているわけですね。火災をどう防ぎ、火を出さないためにどうしたらいいかとか、そういうところをつくっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/167861?Template=document&Id=6410#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":27546,"voices":89}},{"id":"h24-20120625-6","meetingId":"h24-cm06","date":"2012年6月25日","dateIso":"2012-06-25","committee":"区民委員会","time":"午前１０時００分～午後０時４８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"の第５０号議案 品川区暴力団排除条例","agenda":"の第５０号議案 品川区暴力団排除条例","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"個人と組織との違いはあると思うんですけれども、少し何かこんなケースがあるとか、もしあったら教えていただきたい。","respondent":"川崎生活安全担当課長","answer":"ただし、身内だけで実施してくださいと臨海斎場から各葬祭事業者あてに文書を発送しまして、本年１月１日から運用しているところであります。なお、都条例制定後、暴力団関係者の使用実績はございません。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"もう１点聞きたいのは、排除活動の措置が講じられたときの取り扱いはどうなるのでしょうか。その辺の取り扱いについて。","respondent":"川崎生活安全担当課長","answer":"措置を講じた後に公にするのか否かですが、これは区条例では設定してございません。都条例のほうで対応して、都条例に基づいて警察と協議し、公示する、しないを決定するとなっております。","id":"exchange-002"},{"speaker":"武内委員","kind":"意見","question":"今、組の事務所などは例えば不動産契約をとるのに不動産の方があきらかに組の事務所として借りているのがわかったときに、こういうのはどういう対応をしなければいけないのかということについてとの意見を述べました。","respondent":"川崎生活安全担当課長","answer":"会合をするという場合は、組織としての活動に当たりますので、これについてはお店のほうでお断りしていただくというふうに指導を徹底してまいります。","id":"exchange-003"},{"speaker":"武内委員","kind":"質問","question":"暴力団に限らずなかなか断りづらいというのがあるのが１つと、なおかつ、貸してくれよと言われてなかなか断るのに勇気が要ると思うんです。個人ですから、この条例ができたことによる効果というんでしょうか、その辺についてどう考えていらっしゃいますか。","respondent":"川崎生活安全担当課長","answer":"この条例ができたことによって、「条例ができましたので」ということで、それを理由にお断りしていただくように指導していきたいと考えております。","id":"exchange-004"},{"speaker":"藤原委員","kind":"意見","question":"改めてなのですけれども、第５条で「区民の責務」という形で出ているのですけれども、責務の定義、「責務」というのは言葉で出ていますけれども、その辺、「責務」とはどのぐらいの重さで考えていらっしゃるのかとの意見を述べました。","respondent":"川崎生活安全担当課長","answer":"やはり実際に前面に出ていただくのは、警察官でないとできないと考えております。あまりかちかちの義務を課すものではなく、努力義務、知っておいてくださいというレベルのものというふうに考えております。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"その辺についていかがですかということと、一般の区民の方が、その方が暴力団だとは思わなかったという例があるかもしれないじゃないですか。個人情報のこともあるかもしれないんですけれども、品川区内における暴力団関係者の情報は、ある程度出すつもりはあるのか尋ねました。","respondent":"川崎生活安全担当課長","answer":"あわせて警察と連携しながら、絶対に区民には指１本触れさせないという気概を持って取り組んでいくようにお願いしていく予定です。この組織として行うことを規制してまいりますので、個人の住所、顔写真については対象外と考えております。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"要望してしまうのですけれども、１０月１日からですよね、殺されてしまっていますよね。現実にそういう事件もあるわけですから、大変なことですから、もう１回だけ答弁を。","respondent":"川崎生活安全担当課長","answer":"でありますので、所轄警察署、そして、警察本部ともいろいろ連携し合いながら、万全の体制を整えていきたいと考えております。都民には指１本触れさせないと公言しておりますので、都民・区民の方に絶対に指を触れさせないという気持ちを持って全力で取り組んでいく覚悟です。","id":"exchange-007"},{"speaker":"山内委員","kind":"確認","question":"確認させてください。この区条例は品川区だけなのか、２３区一斉にやっていくということなのかということをまず確認させてください。","respondent":"川崎生活安全担当課長","answer":"本条例は品川区の暴力団排除条例ですので、品川区だけです。ほかの区ではまだ制定されていない区もあります。","id":"exchange-008"},{"speaker":"山内委員","kind":"質問","question":"都条例ができました、では暴力団の組員は減っているかというと、そうではないという報道があります。衰退化しているのではなく、まず今、暴力団の組織的なものはどうなっているかということを改めて伺いたい。","respondent":"川崎生活安全担当課長","answer":"その前に「暴力団員による不当な行為の防止等に関する法律」が平成３年にできたときに、いわゆる暴力団員のような身なりの方が減っているのです。","id":"exchange-009"},{"speaker":"山内委員","kind":"確認","question":"例えば窓口、電話、インターネット、さまざまな方法がありますけれども、その辺でどういった体制で区が取り組んでいくのか。品川区には４つの署がありますけれども、その仲介役は課長ではないかと思っていますが、そのあたりをもう一度確認させてください。","respondent":"川崎生活安全担当課長","answer":"警察の専門家のほうで暴力団対策係が各署にありますので、その暴力団対応の専門家にそれぞれ相談は対応していただく方法が一番いいと考えております。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"どうかなというのをお聞きしたいのと、ふだんの中で暴力団がどういうことをする組織なのか、どうなのかということを説明を求めました。","respondent":"川崎生活安全担当課長、中川原地域振興事業部長","answer":"１点目の事件が起きてから調査するのかですが、我々は区の職員ですので、調査はしません。それが新聞報道に載りますと、そうすると区民の方もそういうことをするのが暴力団なんだなという理解をしていただくと期待しております。 そういうことまで品川区の条例で言っているわけではありませんので、人間ですから、そこまではやらない。そこと強く連携して、そういう事情ですので、ご理解のほどをよろしくお願いします。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"急遽そういうトラブルに巻き込まれましたとなったときは、そういうときは、連絡先は警察でいいのですか。そういうときは区に報告すれば、何か対処はしてくれるのか尋ねました。","respondent":"川崎生活安全担当課長","answer":"警察にやってもらわないと、暴力団への対応は区の職員では無理だと考えております。ですので、すべ１１０番対応ということになっております。","id":"exchange-012"},{"speaker":"武内委員","kind":"意見","question":"合法なのかということもあるのでしょうけれども、どう見ても何か我々から見ると、区内に何かそういう報告はありますか。渋谷区とかは出ているらしいのだけれども、品川区ではとの意見を述べました。","respondent":"川崎生活安全担当課長","answer":"脱法ハーブに関する質問ですが、私の知るところ、区内でそういう話があるということは聞こえてきておりません。でありますので、ないのかなと認識しているところです。","id":"exchange-013"},{"speaker":"井上副委員長","kind":"質問・要望","question":"大変区に求めているものが多いような、すごく求められているという印象で読み込んでしまうので、区は区民からいうと。そこはきちんと制度設計をしていただきたいと思うのですのが、いかがか尋ねました。","respondent":"川崎生活安全担当課長","answer":"相談の窓口の設置の件ですが、これは条例の施行が１０月１日でありますので、私のところに情報が集まるように職員に周知させていきたいと考えます。それについても細心の注意を払いながら広報していきたいと考えております。","id":"exchange-014"},{"speaker":"井上副委員長","kind":"意見","question":"第５条のところで、区はできないし、警察もできないことですよね。そういうことについて知りたいと言ったときに、そういう説明もちゃんとしていかないといけないと思うのですが、その辺のお考えはとの意見を述べました。","respondent":"川崎生活安全担当課長","answer":"そして、たまたまそこに路上駐車していたということであるならば、ここで考えられるのは駐車違反だけなのです。その辺のところは区民の方に誤解のないように警察のほうによく申し上げて情報を徹底していただくようにしていきたいと考えております。","id":"exchange-015"},{"speaker":"井上副委員長","kind":"質問","question":"第８条なのですけれども、キャンセル料とか、逆にどういう関係になるのか。ほかのきゅりあんとかといっても指定管理者なのか、訴訟費用はどういうふうにするのかとか、その辺はこれからどういうふうに考えていくのか尋ねました。","respondent":"川崎生活安全担当課長、中川原地域振興事業部長","answer":"やはり結論から申し上げますと、キャンセル料はいただきます。そして、これについては区がしっかり前面に立って話をしてまいります。 こちらが暴力団だとわかった時点で契約はそこで切れてしまいますので、それについてこちらから何も損害賠償とかそういうような義務は発生しません。そのための条例なのです。","id":"exchange-016"},{"speaker":"井上副委員長","kind":"質問","question":"そういったちょっと違った部分での指定管理者で使っているそういう場所について、どのぐらいそれは区が引き取って判断していけるものなのか、その辺はこの条例ではどういうふうに位置づいているのか尋ねました。","respondent":"中川原地域振興事業部長","answer":"ここの第８条には指定管理者も含まれますので、例えばきゅりあんとか指定管理者に区が任せているものもこの条例で規定されております。同じ扱いになります。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはり区内に約３２０人いるということで、排除していける、そういったところを区からも責任を持ってやって区民の安全を守るというところで積極的にやっていくと意見を述べまして賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"}]},{"id":"topic-02","title":"の第５１号議案 品川区立荏原平塚総合区民会館条例","agenda":"の第５１号議案 品川区立荏原平塚総合区民会館条例","exchanges":[{"speaker":"本多委員","kind":"確認","question":"きゅりあんと同等ということで、確認したかったことを教えていただきましてわかりました。事務室等、指定管理者を決める選定委員会はこれから指定をしていく作業だと思うのですけれども、管理についてお聞かせいただけますか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"ご説明いたしましたけれども、喫茶室については、これから喫茶室について運営の方法を考えています。これについては、行政財産の使用許可を考えております。","id":"exchange-019"},{"speaker":"本多委員","kind":"質問・要望","question":"そういった建築材料とかの話になってしまうかもしれないのですけれども、改めて今、これからできることを再確認していただきたい。それは要望です。","respondent":"安藤文化スポーツ振興課長","answer":"２点目の五反田文化センターの音楽ホールの床材については、私どもも認識しています。これは既にやろうとしています。","id":"exchange-020"},{"speaker":"山内委員","kind":"質問・要望","question":"これはちょっと外れてしまうかもしれないけれども教えてほしいのだけれども、その辺の確認をさせていただきたいことと、規模１,０７０席かな。そういったところでバランス的に僕はどうなのかというのがあるので、その辺をお伺いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、品川区も立地と申しましょうか、土地の確保は非常に難しいところです。それよりも１００席多く３６２という席は、１００席オーバーということで適度な地域の発表の場ではないかというふうな感覚はあります。","id":"exchange-021"},{"speaker":"山内委員","kind":"意見","question":"僕が聞いたのでご答弁いただきましたけれども、荏原文化センターのほうが３０％だということ、その辺はどう考えますか。これを品川区としてはどういうふうに考えていくかということまで考えていかないと、これはだめではないかと思うのですが、その辺はどうでしょうとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"荏原文化センター独自に持っているカラーというのですか、雰囲気というのですか、そういうものもまたあると思います。それは若干初めのところは流動性の問題で人が動くと思いますが、今後の文化芸術の発展によっては活発に利用されるのではないかと思っています。","id":"exchange-022"},{"speaker":"山内委員","kind":"質問","question":"そういったときに、荏原文化センターのその使用率が下がりますよと。下がったときに、ではどうするのではなくて、今からどういったことを考えているのですかということを私は聞いているのです。","respondent":"安藤文化スポーツ振興課長","answer":"それからまた、今、区民文化芸術祭などで非常に区民参加型のイベントが好評を得ています。そんな中で分散をするなり、また趣向を変えて利用率を高めていきたいと考えています。","id":"exchange-023"},{"speaker":"山内委員","kind":"質問","question":"今、課長がおっしゃっているのは、地域の文化、地域の文化ということをおっしゃいますけれども、同じ地域ではないですか。地域的なものを考えて、どうやって考えていくのですかということを今からちゃんと事業部で考えていかなければいけないのではないですかという話。","respondent":"安藤文化スポーツ振興課長","answer":"現在、今、荏原平塚総合区民会館の建設を集中して行っています。では荏原文化センターのものについて具体的にということについては、今後、地域振興事業部内でまた検討させていただきたいと思います。","id":"exchange-024"},{"speaker":"武内委員","kind":"質問・要望","question":"先ほど出た避難所としての位置づけが、そこは違うかもしれないので、もしわかれば教えてほしいと求めました。非構造部材で天井の関係は大丈夫でしょうねという確認と、その辺の検討はされているかどうか、その４つを教えていただきたい。","respondent":"安藤文化スポーツ振興課長","answer":"２点目の避難所のことについては、従来どおり平塚小学校の旧来からやっていました避難所としての機能をそのまま継続していく予定でいきます。既に体育館についてもやっていますし、ほかのところについても、その配備を視野に入れてやる予定です。","id":"exchange-025"},{"speaker":"武内委員","kind":"確認","question":"最後のことでホールというのは、イベントホールですか。しっかりやりますよということなのかということの確認と、課長のお話だと、それはそういう方向なのかということですね。","respondent":"安藤文化スポーツ振興課長","answer":"それと、駐車場の先ほどのことについては、今、そういう予定で現在、計画して進めているところです。それから、その中のホールの部分についても４０件弱が、今、来ているところです。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"荏原のきゅりあんということですけれども、大井のきゅりあんと一番違うのは、幼保一体の施設が入っていますよね。で、いわゆる区民体育館とその幼保一体のあの施設も含めた形で運営していくという意味で指定管理者を決めていくということか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"この複合施設の建物ですけれども、我々、文化スポーツの施設については、本条例の施設については指定管理者を導入していく予定です。しかし、幼保一体施設については、直営で職員が出向いて運営すると聞いてあります。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"文化スポーツの施設ができるということで地域の皆さんに話題になっていたんですけれども、なので文化センターみたいなものができるのかなと思っていたのですけれども、文化センターと総合区民会館の法的な位置づけの違いはあるのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"文化センターとこの総合区民会館の法的な位置づけは、全く違わないと思います。地方自治法第２４４条に基づく公の施設です。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、料金設定の話もされたのですけれども、きゅりあんを基本に、いろいろな駅から１０分の場合の同じ条件のところを８施設、１０施設見たと言うんですけれども、これは具体的にどこかは教えていただけますか。","respondent":"安藤文化スポーツ振興課長","answer":"それとイベントホールの１０区ですけれども、似たような施設、ことに大田区は大田区民ホール・アプリコです。中央区ではアートはるみ、墨田区のみどりコミュニティセンター、豊島区では巣鴨地域文化創造館です。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり区民サイドで見ると、ちょっと高額かなというのは感じますし、言われました。第５条の５に「使用料を減額し、これは団体登録ではなく、何のことを言っているのかということをお聞きしたいのですが。","respondent":"安藤文化スポーツ振興課長","answer":"今、お話しされたのは、第５条のところでよろしいでしょうか。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"いわゆる文化センターとかというものをやっている団体登録での減額ではないということか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"この施設は、やはりきゅりあんに似た荏原平塚総合区民会館というような形で考えています。そんな中で、文化センターのような登録団体に減額ということについては、今の段階では考えてはございません。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"指定管理者のところ、これは公募でやっていくのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"まさに今、そこら辺を内部で調整していますけれども、これも特命にしていくのか、公募にしていくのか、今、最終的に考えている最中です。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"指定管理者のところで、やはりまだ考えているということですけれども、公募になれば株式会社やらが中に入ってくるところにも使用料のところがそこの利益になっていくということも考えて、使用料は要するに管理・運営する側の収益になっていくと考えていいのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"そのとおり、指定管理者については利用料金制度を採用いたしまして、指定管理者が収受いたします。ですから、指定管理者の収入となるということになってあります。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはり料金設定で、区が責任を持ってやっていくとなればここまで高くならなくて済むのだと思うのです。文化センターとは法的には違わないのに、何でちょっとグレードがアップして文化センター並みではないのかというのは疑問なのですけれどもとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"きゅりあんに準じたというと文化活動もできるし、また、地域の活動もできます。芸術の活動がさまざまできますようなところできゅりあんに準じた荏原平塚総合区民会館という位置づけです。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"そこが地域の皆さんの話ですと、団体登録減免はされるんですけれども、それでも週１回というところで毎週使っていくのが本当に厳しいと。この料金設定では何で高い設定なのか、これでなければだめなのかという思いがあるのですけれども、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"それを比較すると、とてもじゃない、そこに設定はできない。そんな中で、我々も決して高くないという施設と考えています。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"品川区立として建てられるわけですから、指定管理になるから、そこに利益を区民に求めるというのは。区民が本当に使いやすい低額な、そして、減免制度も使えるような会館をつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"井上副委員長","kind":"質問","question":"でも、ホールは別としても、会議室は地域の方たちがお使いになるのかなと想像ができると思うのです。そこで、区内利用者と区外利用者をどのぐらいの割合でイメージをされているのか、ちょっと説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"予定の数ですけれども、区内・区外の比率につきましては、これは文化センター等では圧倒的に区内の利用者が多いわけです。そんな中で、３割ぐらいが区外というような形になろうかとは思いますけれども、そんな状況です。","id":"exchange-037"},{"speaker":"井上副委員長","kind":"質問","question":"基本的にどういう方針を持っていらっしゃるのかということが１点と、こういう施設で言えば文化センターは７割ぐらいのホール利用とおっしゃっていましたけれども、そういう見立てはどのようになっているのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、計画は立てていく予定ではありますが。正確には、今後また研究をして進めていきたいと考えています。","id":"exchange-038"},{"speaker":"井上副委員長","kind":"質問","question":"使用料はそのぐらいだということで、大体の目安でいいんですけれども、この荏原平塚総合区民会館の運営にかかわる施設運営全体のコストはどのぐらいかかると見ればいいのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"文化スポーツ施設については７,７００万円余です。失礼しました。","id":"exchange-039"},{"speaker":"井上副委員長","kind":"質問","question":"利益を還元してほしいと思う一方で、今ここで条例を通したとしても、そういうところは臨機応変に料金をどうしていくのか。品川区の場合は空き施設に順繰りつくっていくというふうに進めているわけですから、検討していく課題になると思うので、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"それで、私どもは文化スポーツ振興課の所管として施設が文化センター５館、体育館も２館、そしてこの施設があります。そんな中で、料金設定の問題については、そういうところへ基本計画ならびにそういう設定を考えていくというふうに私どもは理解をしています。","id":"exchange-040"},{"speaker":"井上副委員長","kind":"質問・要望","question":"稼働率を上げて収入を増やしていくことも一方では必要なことだと思いますので、その認識を持っていただいて進めていただきたいと、これは要望です。１点、区民ニーズを充足していただくのはもちろんなのですが、これについて何かお考えなどありますか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"貴重なご意見をいただいたということでこちらのほうに受けとめさせていただきまして検討させていただきたいと思います。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはり指定管理者ありきでこれだけ利用料が高くなるということで、区民に負担を強いるというこういう条例には賛成できません。そういったところにすらもお金がかかってできないというのは、区としてどうなのかなということを感じますので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118408?Template=document&Id=2638#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":32352,"voices":124}},{"id":"h24-20120625-7","meetingId":"h24-cm06","date":"2012年6月25日","dateIso":"2012-06-25","committee":"厚生委員会","time":"午前１０時００分～午前１１時２１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"担当課長にも出席いただいておりますので、会議の運営上、審査の順番を入れかえ、こちらを先に行いますので、よろしくお願いします。 それでは、予定表(2)…","agenda":"担当課長にも出席いただいておりますので、会議の運営上、審査の順番を入れかえ、こちらを先に行いますので、よろしくお願いします。 それでは、予定表(2)…","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"ふぐのことで、手続上のことで、ちょっと確認させていただきたいんです。新たに扱えるようになった人が届出をするための手数料が必要になると、こういう考え方で、これで事実として正しいのか尋ねました。","respondent":"工藤生活衛生課長","answer":"今、委員がおっしゃったとおりでございまして、現状は、ふぐ調理師の免許を持っている方のみが取り扱えたです。それが、調理師免許を持っていなくても、一定の要件を満たした加工品であれば取り扱うことができるようになったということであります。","id":"exchange-001"},{"speaker":"塚本委員","kind":"質問","question":"ということは、一定の商品であれば、申請さえすれば、だれでも基本的には扱えるということで、よろしいのでしょうか。商品が一定の加工をされていれば、扱う側は、どなたでもいいということか尋ねました。","respondent":"工藤生活衛生課長","answer":"取り扱うことができるものに関しましては、提供の場合には、前提としましては、飲食店の営業の許可等をやっているというのが、まず一つです。当然、魚を売るという魚類等の販売の許可を受けてありますので、それが前提のうえでの届出ということになります。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ、教えてください。施行期日が平成２４年１０月１日となっているんですが、今のお話を伺っていると、なんで１０月１日なのかと。","respondent":"工藤生活衛生課長","answer":"条例自体は３月３０日に改正されたわけですけれども、これは都条例の中に、届出制が設けられております。東京都の都条例の中で、都条例自体の施行期日が１０月１日になっておりまして、それに合わせてということになります。","id":"exchange-003"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"この趣旨と、ここに係わって新たに手数料を設置する経過を、もう少しご説明ほしいと求めました。それからもう１点、どんな意見が挙がったのか、ご説明ほしいと求めました。","respondent":"工藤生活衛生課長","answer":"検討されたわけですけれども、しっかりとした対応をしてほしいと、審議会の中で答申を出しておるところです。有毒部位除去済というステッカーを確実に張って流通させるという対応がとられておりますので、今回、なったわけです。","id":"exchange-004"},{"speaker":"中塚副委員長","kind":"提案","question":"安全性に問題がないのかというところを、改めてどうお考えなのか、伺いたいと思います。問題ではないかと思うんですけれども、改めて、この点を伺いたいと思いますとの意見を述べました。","respondent":"工藤生活衛生課長","answer":"ここ最近の１０年間で、十分に対応できるのではないかという結論を、東京都のほうは出しております。そういった意味では、一定の安全性という部分は保たれていると、東京都は判断を下しておりまして、私どもも、同様です。","id":"exchange-005"},{"speaker":"中塚副委員長","kind":"質問","question":"１０年間で件数が減ったとはいえ、命にもかかわる問題ですから、やはり安全性を脅かしかねない状況については指摘したいと思います。権限の移譲の説明はありましたけども、事務内容に変更はあるのか、そこをちょっと補足していただけますか尋ねました。","respondent":"大串住宅担当課長","answer":"事務内容の変更につきましては、東京都がやっていたときと変わるものではございません。したがいまして、こちらの手数料につきましても、東京都時代と全く変わらない４００円という形で、区のほうでもやらするところです。","id":"exchange-006"},{"speaker":"若林委員","kind":"質問・要望","question":"まず届出をされたときの審査の内容、どういうふうにされるのか、教えていただきたいのが一つ。手数料と再交付手数料の３,０００円と２,４００円の根拠を、３点、お聞かせほしいと求めました。","respondent":"工藤生活衛生課長","answer":"１点目の審査についてですけれども、こちらのほうは、届出される方に対しまして、私ども、条例の趣旨等を説明するというのが、まず１点です。営業者等に関しましては、やはり責任を持って対応、ふぐ加工製品の管理をするという部分をご説明するというのが、一つです。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問","question":"営業するわけで、その方に対して、営業停止処分等を考えていらっしゃるということですね。売った人も、一定の営業停止処分になると、こういう意味か尋ねました。","respondent":"工藤生活衛生課長","answer":"ご質問の一番難しいところは、そちらのほうの責任の所在だと考えています。例えば販売店に関しては、販売店の責任になろうかと思いますので、それはそれで状況の中で責任の所在は変わってくるです。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"こういう手数料条例を施行するわけですので、その状況の中で、というのはもうちょっと明確にしておかないといけないと思うんですが、どうか尋ねました。","respondent":"工藤生活衛生課長","answer":"少し説明がうまくいきませんで、説明しますと、いわゆる食中毒を起こしたという部分に対しての処分となります。そういった意味では、間違いのない対応ができると考えています。","id":"exchange-009"},{"speaker":"向委員","kind":"確認","question":"若林委員の質問を受けて、一つだけ確認なんですが、そのあたりは検討しないといけないとは思っております。そのラベルを確認しましたというところも、ラベルに通し番号があるかどうかだけ、ちょっと最後にお願いします。","respondent":"工藤生活衛生課長","answer":"ラベルに関しては、通し番号までは要求しておりませんけれども、仕入先、仕入年月日の記録を、仕入れた日から１年間保管するという形で条例のほうで定めておりまして、万が一、そのような疑わしい事故が発生した場合には、伝票等でさかのぼりができるという形になっております。","id":"exchange-010"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"例えば、そのラベルを張る、また、そういう体制がある等々、現地の確認というのはされるのか。やはり安全というのは、そういう仕組みからつくられるものだと、私は思うんですけれども、そこはしっかりご説明ほしいと求めました。","respondent":"工藤生活衛生課長","answer":"それから、処理施設の所在地という部分で、住所等も記入するという形になっております。これが、確実に表示されているというのが必要要件になってあります。","id":"exchange-011"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"事務に係る手数料の設置ということで、賛成ですけれども、やはりふぐの取り扱いについては不安が残ります。しっかりと対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"第５２号議案、品川区立高齢者住宅条例の一部を改正する条例","agenda":"第５２号議案、品川区立高齢者住宅条例の一部を改正する条例","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"ただ、そこが条例に載らない別の理由があるのか、その辺がよくわからないので、そこを伺いたいと思います。今回の引き下げと契約期間も含めて、品川区から働きかけたものなのか、その理由や背景についても、あわせて伺いたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"先に変更いたしました、２０年間の契約期間満了に伴いまして、契約更新をしたものです。変更はございません。","id":"exchange-013"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"使用料と契約期間を２０年から１０年にしたということですけれども、その理由は何なのか、伺いたいと思うんです。そこをどう考えていらっしゃるのか、区の基本的な姿勢を伺いたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"周りの近傍家賃に比較しまして、２０年前に設定をいたしました家賃につきましては、そこから比較しますと、やはり若干高めであると判断したものです。昨年変更した使用料ですけれども、今回のメゾンホ琴秋の改定に伴って、あわせて整備をさせていただいたものです。","id":"exchange-014"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ただ、借上型ですから、相手との合意がありますので、そこはそこであると思うんですけれども、近傍家賃の設定を伺いたいと思います。今後も必要だと思いますので、ぜひ進めていただきたいと思うんですけれども、その点についてはいかがか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"２０年前後の建物ですけれども、私のほうの調査した結果では、やはり６万５,０００円前後が平均の家賃だと認識しております。今後の区としての建設予定等につきましては、現在の建設型の３棟、考えていく必要があるのではないかと考えています。","id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区としては６万５,０００円にしたいけれども、ここに至ったと、そういう経過ということなのでしょうか。その辺の内容がよくわからないので、改めて、区の基本的なスタンス、それから、合意に至った経過をご説明ほしいと求めました。","respondent":"白鳥高齢者いきがい課長","answer":"メゾン琴秋のほうですけれども、昨年９月以降、具体的には９月２７日以降なんですけれども、家主と４回ほど協議をしてまいりました。昨年更新をしておりますけれども、そのときにはスムーズな家主との協議の中で、このような結論に達したです。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"切らないで、契約更新を１０年もやったっていうことは、区の考え方が、借上型についても、全部更新をしていくという判断をしたのか、したんでしょう。そこのしたという理由を教えてほしい。","respondent":"白鳥高齢者いきがい課長","answer":"一応２０年間という当初の契約の中身で、妥当な年数だとは、区のほうとしても考えてあります。方針を、そういうようなことも考え合わせまして、妥当な契約期間をこれから結んでいくということには変わりはございません。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問","question":"ここにある７カ所全部、これから再契約をする、その判断がどこにあったんですかと。２０年という約束なんですから、借上型はいっぱいあるわけですから、こういうことになったかということを教えてほしい。","respondent":"原高齢者福祉課長","answer":"区の基本的な考え方の中に、いつまでも継続して住むことができるようにといったところが、さまざまな計画の中で基本的なスタンスとしています。そういう基本的な考え方の中で、今回、継続して借り上げていくといった判断をしたものです。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"確認","question":"そうすると、最後に確認したいのは、この借上型は、すべて再更新するという判断をしておいていいのか。それを説明を求めました。","respondent":"原高齢者福祉課長","answer":"今まで住んでいるところが大きな変化がない限り、そこに継続して住まう形が、その住んでいる方にとっても最善だと考えております。現時点では、そういうふうに判断しています。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"確認","question":"確認をしたいんですけれども、借上型を、高齢者住宅と区民住宅を一緒にやっているところもあるわけです。区民住宅はどうするのか、これは波及しないと思っていていいですかということだけ、確認します。","respondent":"山田副区長","answer":"区民住宅のありようということで、いわゆる今後の課題の部分で、どういうクロスの仕方がされるか。利用勝手も含めて、推移を見ていかないと、明確なお答えは、私は、今の段階ではできないと思っています。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問","question":"６万５,０００円で、それが７万円とかになっているというのも、私はおかしいと思う。次もあるわけですから、もっと短くするということをしてほしいと、これはお願いだけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問","question":"建設型は別にして、借上型で、高齢者住宅について空き室ってあるんか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"現在、空き室は、確かに数戸あります。入居が開始される前には、ご本人のほうに説明をさせていただいた中で、やってあります。","id":"exchange-022"},{"speaker":"若林委員","kind":"確認","question":"希望者はいるけれども、家賃の関係で、半年、１年以上ずっと空いていると、いわゆる借上型区民住宅のような事態には陥っていないという確認はさせてください。","respondent":"白鳥高齢者いきがい課長","answer":"今、入居は速やかに入るような仕組みをとっております。その部屋自体をリフォームしなければならないという期間がありますので、そういう意味では、整い次第入居していただくです。","id":"exchange-023"},{"speaker":"若林委員","kind":"質問","question":"そこはどうも、もう１回、そこは考え方を教えてください。今後整理するのであれば、またご報告ほしいと求めました。","respondent":"白鳥高齢者いきがい課長","answer":"これからの近傍家賃との比較の問題につきましても、明日の委員会のほうで、専決処分のことでお話をするところですので、そのときに詳しくお答えをさせていただきたいと考えています。","id":"exchange-024"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"しかし、一方で、高齢者住宅への入居の希望はとても強いものがあります。先ほど指摘いたしましたが、シルバーピア方式による高齢者住宅の建設をぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-03","title":"第４８号議案、平成２４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第４８号議案、平成２４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"教えていただきたいんですが、何にしろ、協力してくださっているほかの団体もあるではないですか。全体の金額がどれぐらいの中の９００万円を貸したのか、ないのか、そこら辺もあわせて説明を求めました。","respondent":"小川健康課長","answer":"今後の考え方ですが、協議をしつつ、そちらについては相談に応じてまいりたいと考えています。区のほうから貸し付けていただけないかということでご相談がありまして、会のご相談に応じて、貸し付ける方向で動いているところです。","id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問","question":"会長もされたのかどうかわからないけど、じゃあそれは協力しますというスタンスなのか、どうか。そこら辺だけ、ちょっと説明を求めました。","respondent":"小川健康課長","answer":"それぞれの会のご事情があるということで、今回につきましては、全体の工事費の半分程度を区のほうに見ていただけないかというご相談がありました。それについては、こちらのほうも誠実に対応したいということもございまして、対応するという判断に至ったものです。","id":"exchange-027"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今回は耐震化への対応ですから、対応されたのか、伺いたいと思います。今、打診があるものが、何かほかにあるのか、ちょっとその辺の状況も伺いたいと思います。","respondent":"小川健康課長","answer":"あちらは、今年度、区のほうで耐震補強工事を実施する予定の建物になってあります。それから、他の医師会館等については、今のところ、特に相談等、打診等はございません。","id":"exchange-028"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"１点伺いたいのは、現在、どういう状況なのか。ここもしっかり進めていくことが、震災時の対応として必要だと思いますけれども、その点について１点伺いたいと思います。","respondent":"小川健康課長","answer":"１点目の、地域のまちの診療所への支援ですけれども、地域の診療所等への支援はございません。それから、財源につきましては、そういった国と東京都の、今回の特定財源とするようなものは見当たらないということで、一般財源にしたです。","id":"exchange-029"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ぜひ、そこについて支援を進めていただきたいと思うんですけれども、この点をどうお考えなのか、改めて、伺いたいと思います。やはり国や東京都にしっかり財源を求めていくということも大事だと思いますので、どういうお考えなのか、伺いたいと思います。","respondent":"小川健康課長","answer":"地域の診療所等への耐震化支援の区の現状につきましては、先ほども申し上げたとおり、区としての補助制度はございません。区としては乗りたいと考えていますので、当然のことながら、機会があるごとに働きかけていくべきだと考えています。","id":"exchange-030"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"あわせて、地域の病院や診療所への耐震化支援が急がれていると思います。国、東京都に財政支援を求めるとともに、区としても、直ちに創設をするように、改めて求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"渡辺委員長","kind":"質問","question":"所管質問をなさりたい委員がいらっしゃいましたら、その基礎となる一般質問の項目と、それに関する質問内容をこの場でお願いいたします。所管質問がございましたら、ご発言をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"いろいろな団体とともに要望しているというご説明がありましたが、どういう中身を要望されていらっしゃるのか、要望書なのか。その２点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594819?Template=document&Id=3326#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":22516,"voices":97}},{"id":"h24-20120625-8","meetingId":"h24-cm06","date":"2012年6月25日","dateIso":"2012-06-25","committee":"建設委員会","time":"午前１０時００分～午後３時５０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件整理しています。","topics":[{"id":"topic-01","title":"第５４号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第５４号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"これ、定期利用の方もいらっしゃるかと思うんですけれども、定期利用はこれは含まないということでいいのかとの意見を述べました。","respondent":"谷口交通安全担当課長","answer":"現在、１日平均１０８台利用状況がありまして、十分に可能となりますので、それは余裕ができてくると思います。なお、ご質問の混雑状況ですが、定期利用なんですけれども、現在、定期利用が３７３台の収容可能でございまして、これは十分収容可能な状況です。","id":"exchange-001"},{"speaker":"沢田委員","kind":"確認","question":"一応確認で、定期が今、実際３７３台、毎月更新とかだと思うんですけれども、ずっとほとんど埋まっている状態なのか。","respondent":"谷口交通安全担当課長","answer":"現在、定期利用につきましては、五反田駅が、現在、定期利用が６５.４％です。６５.４％で十分、定期利用のほうは足りておる状況です。","id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"大体６５％ぐらいの利用率だったら、あと７０台ぐらいはこっちへ移せるのかなと、その辺はとの意見を述べました。","respondent":"谷口交通安全担当課長","answer":"現在、その見直しをやっているところでございまして、それもシフトしていく予定で進めておるところです。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"自転車の放置対策というのもあると思うんですけれども、昨年度の放置自転車、五反田駅周辺ではどのくらいの台数があるか、わかったら説明を求めました。","respondent":"谷口交通安全担当課長","answer":"現在、五反田駅周辺の年間、昨年度ですけれども、２,６１７台撤去しています。","id":"exchange-004"},{"speaker":"吉田委員","kind":"確認","question":"確認なんですけれども、１年間でということですか。２,６１７台の放置自転車。","respondent":"谷口交通安全担当課長","answer":"はい、そうです。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"１３７台ということなんですが、裏通りも含めて、これから放置禁止区域も広げながらという意味も込めて駐輪場を増やすということなんですか。それをちょっとお伺いしたい。","respondent":"谷口交通安全担当課長","answer":"現在のところ、放置禁止区域については現状のまま進めていきたいと考えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今、放置自転車が年間で２,６１７台ということだったんですが、これは何回でこんな数になるのか。１回当たりの数がどれくらいなのか、五反田駅の自転車駐輪場の需要ということについては、区としてどう考えられているのかを説明を求めました。","respondent":"谷口交通安全担当課長","answer":"おおむね１回に十五、六台の撤去です。民間施設等も含めて１カ所しかないですので、民間施設の開発も含めて、あれば働きかけをしていきたいです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"では、今回、１３７台増やすわけですけれども、それだけではまだ足りないということで、そういうふうに増やせるようなところがあれば、これからも増やしていくという考え方ということか尋ねました。","respondent":"谷口交通安全担当課長","answer":"そのまま引き続き、諸施設等を通していろいろ働きかけを進めていきたいと考えているところです。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"２つほど教えてもらいたいんですけれども、これで必要かつ十分なのかということをお伺いしたいのと、ガード下の歩道だと思うんです。それの安全とかそういうことに関しては、多分大丈夫だとは思いますけれども、何か工夫をされるのかどうかということについてお伺いしたいと思います。","respondent":"谷口交通安全担当課長","answer":"番地の関係のご質問ですが、包括して番地で条例化する予定です。この歩道を占有するのが１.７メートルですので、通行可能なのは４メートル確保できますから、安全確保は大丈夫と考えております。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"この４メートルぐらいあれば、特に特別な歩行者の安全対策といいますか、そういうことをしなくても大丈夫と、そういうことでよろしいのか尋ねました。","respondent":"谷口交通安全担当課長","answer":"国土交通省の指針で、一応歩行者の交通量が多い場合は３.５メートル以上確保できることという指針があります。十分確保できていると解釈しております。","id":"exchange-010"},{"speaker":"須藤委員","kind":"質問","question":"ここは管理はどこが管理するのかなということと、どういう状態なのか。ここが１３７台より、有料でやるかどうか、その辺はどういうふうにお考えになっているんか尋ねました。","respondent":"谷口交通安全担当課長","answer":"管理につきましては、今の現状の既存の場所と同じくＮＣＤのほうで管理をいたす予定です。確かに駅に近いということで利用者が増えてくると思いますので、それは利用状況を見ながら、また検討していきたいと考えております。","id":"exchange-011"},{"speaker":"原副委員長","kind":"意見","question":"まず１つ目が両側の電気が暗い、その辺のところをどうするのかということと、実際にホームレスの方が寝ているという状況がままある。そういう場所なんですけれども、関連の形になると思うんですけれども、その辺の対策等はとの意見を述べました。","respondent":"谷口交通安全担当課長","answer":"一応管理がおりますので、それぞれ巡回をしながらホームレスについては対応していきたいと考えております。電気につきましては、照明施設がありますので、また暗くならないような設置も準備していますので、それで対応したいと考えております。","id":"exchange-012"},{"speaker":"原副委員長","kind":"質問・要望","question":"これは要望なんですけれども、五反田の中でも何カ所かの暗いガード下という場所の１つになるものですから、気を遣っていただきたい。そこのホームレスの方が移動したときに、近隣に迷惑がかかるようなことにならないように、関係部署のほうに徹底をお願いいたします。","respondent":"谷口交通安全担当課長","answer":"わかりました。","id":"exchange-013"}]},{"id":"topic-02","title":"第５５号議案、品川区建築物不燃化促進助成条例の一部を改正する条例","agenda":"第５５号議案、品川区建築物不燃化促進助成条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この地域に全体で何棟ぐらいの建物が建っているのかということと、既に耐火、準耐火になっている建物が何棟ぐらいあって、今回の対象となる建物が何棟あるのかということを教えてほしいと求めました。","respondent":"品川防災整備担当課長","answer":"現在、この地区の建築物の棟数ですが、平成２３年度末で４５８棟となっております。それから、耐火建築物につきましては９６棟、準耐火建築物については３７棟となっております。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、全体で４５８棟、今回のこの準耐火のところまで助成が拡大されるということなんですけれども、この対象となる建物がどれぐらいあるかということも教えてほしいと求めました。","respondent":"品川防災整備担当課長","answer":"先ほど申し上げましたとおり、今回の対象建築物は、準耐火建築物の助成となっておりますので、３７棟ということになっております。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"すべてのここの地区の棟数が４５８棟で、既に耐火の建築がされているのが９６棟で、準耐火の建築がされているのが３７棟ということなんですよね。それ以外のところで、今回対象になるという建物は何棟ぐらいあるのかということなんですとの意見を述べました。","respondent":"品川防災整備担当課長","answer":"当然建て替え棟数になりますので、どれぐらいになるかというのは、今回の補正予算で見込んでいるものは４棟となっております。あいている土地に建物を建てる場合もありますので、実際に何棟と言われると、それは少しお答えができないです。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１棟当たり１４７万５,０００円で、その費用ということで４０万円という、そういうことで考えていいのでしょうか。１５０万円の助成制度があると思うんですけれども、その点について、助成金についてお聞かせほしいと求めました。","respondent":"品川防災整備担当課長","answer":"それから、国と都と区の補助金の割合ですが、国２分の１、都４分の１、区が４分の１ということになっております。それから、耐震の建て替え等と併用ができるかですが、こちらは併用ができないということになっております。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４分の１ということなんですけれども、そういう形で品川区が額を決めて国と都に補助金を求めていくということができるものなのか、この額そのものがどういう形で決まったのかということについてもお聞かせほしいと求めました。","respondent":"品川防災整備担当課長","answer":"昭和５６年以前の建物になりますが、建て替えをすれば助成が出るですので、その辺についても違いがあるというふうに考えております。これにのっとって区のほうでやっております。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうは言っても、今までよりは増額ということで、本当に耐震化が進むといいなと思っています。それともう１つ、なぜ対象から外れるのかということと、そういうふうに特定整備路線になるとどうなるのかということも教えてほしいと求めました。","respondent":"品川防災整備担当課長、中村建築課長","answer":"その中で６月末までに特定整備路線を決めるです。現在のところは、特定整備路線に選ばれますと、まずそこの道路を東京都と区が連携してやっていくということになります。 計画道路内では、建物の構造が木造や鉄骨造などの撤去しやすいものが原則。それから階数が３階建て、それから地下を有さないもの、こういったものが基準となっております。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"４戸あるとおっしゃいましたけれども、その４戸はまるっきり木造であるということでしょうけれども、最低限どこまでのことを言うのか説明を求めました。","respondent":"中村建築課長","answer":"こちらは例えば階段は３０分、梁の部分は４５分というような、火災に耐えられる時間によって区分されるものです。それからあと、あるいは耐火構造物ですよと試験によって認定されたものについても、その性能と同等のものというふうにみなされることになっています。","id":"exchange-020"},{"speaker":"浅野委員","kind":"質問","question":"ほかにこの不燃化促進重点区域として指定するというんですが、その予定とか見込みとか、そういうものは今後あるのかどうかということだけお伺いしたいと思います。","respondent":"品川防災整備担当課長","answer":"ほかに区域を指定する予定があるかですが、補助４６号線沿道、そこの道路の周りを不燃化助成するという制度を行っております。ということで、ほかのやっている地区に対しては準耐火建築物の助成をやる予定はございません。","id":"exchange-021"}]},{"id":"topic-03","title":"第４８号議案、平成２４年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第４８号議案、平成２４年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"地域振興費の中の応急活動対策費追加分についてお伺いしたいんですけれども、この点についてひとつお伺いしたいのと、あと。ぜひともこれは重要な案件でありますので、そこら辺のお考えをお伺いしたいなと思います。","respondent":"鈴木防災課長","answer":"この期限は、スプレーの缶のほうの規制がもともと耐用年数を３年程度にということで規定がありますので、それを原因とするものです。基本的に現時点では、通常のスプレー缶と同じように使い切って空にして、金属のごみで出していただくというのを想定しております。","id":"exchange-022"},{"speaker":"浅野委員","kind":"質問・要望","question":"一般質問の中でも、こちらのほうも品川区内には２３カ所あって、ぜひとも木密のほうが使えるようになってほしいなとは思うんですけれども。そのように、これは要望なんですけれども、お願いしたいと思います。","respondent":"鈴木防災課長","answer":"今ご指摘のありましたスタンドパイプ、街頭消火器等、初期消火関係のマップですが、区民の皆様に消防のほうからの排水栓の指定も含めまして、情報がそろいましたらしっかりとお伝えできるような方法を考えていきたいというふうに考えております。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つは、この旗の台・中延地区というのは、旗の台四丁目と中延五丁目ということで確認させていただいてよろしいでしょうか。防災都市づくり推進計画で指定している整備地域まで少なくとも広げるべきなんじゃないかなと思うんですけれども、その点はいかがか尋ねました。","respondent":"鈴木防災課長","answer":"それと次に、区の考え方といたしましては、基本的には自助を基本として区民の方に日頃から備えていただきたいという考え方です。まずは緊急的な対応ということで、区から一定の支援ということで配布をするものですので、ほかの建物や全世帯を対象にという方針は持っておりません。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"は、火災危険度４というところはたくさんありますし、この地域だけが本当に火災危険が高いというわけではないと思うんですね。区としてどう考えているのか、ほかのところはそうではないとは言えない状況の中で、拡大していくべきという考え方についてはどうか尋ねました。","respondent":"鈴木防災課長","answer":"ご指摘のありました区としての考え方ということで、先ほど申し上げた４地区で、対象とする建物は木造と防火造りの建物に限定ということになります。考え方といたしましては、もう１つは、そこに限定して例外的な自助の考え方を外して支援をするというのが現在の区の考え方です。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"区としても対策が必要だということで、今回、配備をするというふうなことでよろしいでしょうか。そういうことで確認させていただいてよろしいか尋ねました。","respondent":"鈴木防災課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それは私はぜひほかのところも本当に危険度は高い地域ですので、拡大ということで今後ともご検討いただきたいと要望をさせてほしいと求めました。それともう１つは、大地震のときには、どれぐらい効果があるのかということについてもお聞かせほしいと求めました。","respondent":"鈴木防災課長","answer":"消防からの説明でも、万が一、水道の本管のほうが割れたり破損したりで水が出ない場合は考えられる。これはあくまで水道管がちゃんと機能しているときの補助的な消火の器具だということで説明を受けておりますので。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"旗の台小学校の前の木造住宅が密集したところを対象に、２５式全部、そこの四丁目に配備するということなんでしょうか。そこだけになるのかということが１つと、街頭消火器を増やしていただきたいと思うんですが、そこら辺の品川区の考え方もあわせて説明を求めました。","respondent":"鈴木防災課長","answer":"区道であったり、モデル実施する中でもう少しよい配備の方法もあれば、それもあわせて検討していきたいというふうに考えております。先ほど申し上げたようにモデル実施ですので、このモデル実施の結果を検証してから、この後については。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当にこれだけ火災危険度の高い新たな想定がさらに出ましたので、町会などの要望に沿って拡大の方向でしていただきたいと、よろしくお願いします。６位、１０位、国や都の補助金というのがあるのかどうかということをお聞かせほしいと求めました。","respondent":"品川防災整備担当課長","answer":"１点目の豊町五丁目、まずこの辺の導入をしてみて、それについて状況を見て拡大するかしないかは検討していくというような考えです。それから、これはあくまで個人の土地ですので、その所有者の方がどうするかということを判断されるというふうに考えております。","id":"exchange-029"},{"speaker":"須藤委員","kind":"質問","question":"ページ１５、これは我々自民党として予算特別委員会でお話をさせていただいて、早速取り入れていただきましてありがとうあります。ページ１９、１９ページの「首都直下地震」という表現と、その２点を説明を求めました。","respondent":"鈴木防災課長、高山防災計画担当課長","answer":"単なる自助の支援というだけで配布するのではなくてという部分ですが、箱の表面には、木密に関する啓発のようなものの印刷を入れます。それから、箱の中には、消火具の取扱説明書とは別に。 委員お尋ねの２点目の「首都直下型」と「首都直下地震」の違いですが、基本的には地震の有り様といいますか、起こるメカニズムは同じものです。国、「首都直下地震」というような表現で統一されている、そのように考えております。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"スタンドパイプのことで基本的なことなんですけれども、具体的に質問させていただきたいんですけれども、消火栓をあけますよね。これが私の理解しているものとこれと同じなのか、それは質問なんですけれども、まずはそれがどうなのかお伺いしたいんです。","respondent":"鈴木防災課長","answer":"今、ご指摘のように地面よりふたをあけた下３０センチから６０センチぐらい、ホース等の金具の接続は手を差し込んで潜るような形になります。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"ですからこれは、これ、個数的にはどうなんでしょうか。その辺をお伺いしたいです。","respondent":"鈴木防災課長","answer":"区民消火隊６８台、それからミニポンプ隊が１３０台ありますので、合計で１９８本のスタンドパイプは消火用のポンプとセットで配備されるという形になります。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"それに付随して、たしかスタンドパイプをしただけではなくて、蛇口を、要するに、水道の蛇口と同じようにハンドルがあって、これを回さないと消火栓があかないと思うんですけれども、それも同じように同じ数だけ配備しているということでよろしいか尋ねました。","respondent":"鈴木防災課長","answer":"スタンドパイプと、それからホースの口径を合わせるための接続用の器具、この２点をセットでお渡しする予定で準備を進めております。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それをお聞かせいただきたいのと、また、東京都とか国とかの補助金があるのかということをひとつお聞かせほしいと求めました。お願いします。","respondent":"高山防災計画担当課長","answer":"高層住宅の定義という点ですが、おおむね１０階以上、高さにしまして３１メートル以上というような想定で考えてあります。それから３点目の区の単費、一般会計のみかという点につきましては、現状のところは一般会計での計上というところで考えております。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"どうして１０階なのかなと思って、もっと８階とか９階もある中、その辺はいかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"失礼いたしました。この対策検討の過程の中で、考え方として応用できるようなものは当然検討してやられると思いますので、そのように考えております。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どの地域を何軒くらいを想定して、どういう体制で、だれが行うのかということについてお聞かせほしいと求めました。これは整備事業の４地域ということで考えられているのか、対象が何軒あるかということについてお聞かせほしいと求めました。","respondent":"大串住宅担当課長","answer":"協議会が実施する相談会や個別訪問相談、一応２００万円、助成費として考えているです。あるいは踏もうと考えていらっしゃる方がいらっしゃいましたら、そちらに対して個別訪問を行いまして、このように考えているところです。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この木造住宅の整備事業の地域ということは、４地域ということですか。それからあと、これが防災ではなくて都市環境事業部でされているというのはなぜなのかということもお聞かせほしいと求めました。","respondent":"大串住宅担当課長","answer":"やはり専門家、専門的な知識、こういったものを有する方が中心になってこようかというふうに考えているところです。建設４団体とのおつき合い、リフォームの関係ですとか、このお話をまずはさせていただいたというところが端緒になっているところです。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ありがとうございました。この補正予算で、排水施設建設事業追加分ということで１億９,７００万円が計上されているんですが、ここの大まかな事業の中身を説明を求めました。","respondent":"武藤河川下水道課長","answer":"東京都と区が連携して進めております立会川の浸水対策事業におきまして、現在、立会川の下に立会川雨水放流管というものを整備しようとしております。その仮移転の先としまして、用地を取得して、一時改善施設を整備するものです。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"南大井児童遊園ですか、どうやって価格が決められたのかということを１つお聞かせいただきたいのと、お聞かせほしいと求めました。そういうところでは、送迎だとか、そういう対策もとられているのか、そこら辺のところもあわせてお聞かせほしいと求めました。","respondent":"武藤河川下水道課長","answer":"大変恐縮なところ、現在も園は使っている鈴ヶ森公園を中心にご利用いただきたいという旨の説明を、今後とも真摯に対応していきたいと考えています。","id":"exchange-039"}]},{"id":"topic-04","title":"議員提出第３号議案、品川区木造住宅耐震診断助成条例","agenda":"議員提出第３号議案、品川区木造住宅耐震診断助成条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"参考に、２３区では７区が一般耐震診断を無料で実施ということで書いてあるんですけれども、今議会に提案をされているということでお聞きしました。地域住民の命と財産、まちを守るという広域性の大変高いものであるという考え方から、無料化を提案させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"沢田委員","kind":"質問","question":"どれだけ違うのかということと、例えば無料の診断から、診断でどっちも終わることではないと思う。耐震診断ではなくて建て直しをされたという件数とか、今、現状でそういうものが進められている話とかがありましたら説明を求めました。","respondent":"品川防災整備担当課長","answer":"その中で無料簡易診断を受けた方が大体３分の１程度ということになっております。場合によっては無料簡易診断をしないで直接もう一般診断を受けていただいて、そのまま改修、建て替えというような流れになる場合もあります。","id":"exchange-041"},{"speaker":"浅野委員","kind":"質問","question":"１回無料を受けてから、そのまま流れていく。今は一般からそのまま行ってしまうのもありますよということだったので、そこら辺を説明を求めました。","respondent":"品川防災整備担当課長","answer":"無料簡易診断を受けていただいて一般診断に流れる方が、全体の３分の１となっております。それから、要するに、もう一般診断だけを受けて改修に行かれる方が、残りの３分の２というような形になります。","id":"exchange-042"},{"speaker":"浅野委員","kind":"質問","question":"そうすると、無料の簡易診断を受けて一般診断を受けない人が３分の１ということになるわけですね。その３分の２のうち、大丈夫だと言われたというんでしょうか、そこら辺を説明を求めました。","respondent":"品川防災整備担当課長","answer":"説明が少し足りなくて申しわけございません。無料簡易診断を受けていただいて、その後にすべての方が一般診断を受けていただき、改修に行くというような流れになっております。","id":"exchange-043"},{"speaker":"浅野委員","kind":"質問","question":"お宅は一般の耐震診断を受けたり、また改修しなくても大丈夫ですよと言われる人が全体でどのくらいいるのかなと、無料の診断を受けた方で。その先に進まなくてもいい人ですね、それを説明を求めました。","respondent":"品川防災整備担当課長","answer":"無料の簡易診断を受けた人が一般診断を受けたりとかして、例えば改修の必要性がないというような方がどれぐらいいらっしゃるかということなんですが、平成２３年の実績ですと、残念ながらすべての方がやはり耐震性がないという判断をしております。","id":"exchange-044"},{"speaker":"須藤委員","kind":"質問","question":"今お聞きして、今伺うと、助成を受けるときには一般診断を受けなければいけないよという順序になってしまうんだよな。ですから、そのあたりの仕組みづくりはどういうふうにしていくのか、考えを。","respondent":"品川防災整備担当課長、片田都市環境事業部長","answer":"それなりに耐震意識をお持ちの方というのは、一般診断をすることに当たってお金を出すことにそれほど嫌悪感はないというふうに考えております。とにかく耐震に興味を持っている方、専門家からアドバイスを受ける… ただ、実際にどこが支障があって、そういうものはやはり専門家と連携をしてやらなければいけないというような状況です。","id":"exchange-045"},{"speaker":"須藤委員","kind":"意見","question":"たとえ十何万円のうち２分の１負担するにしても、そんなところにやらないで、自分で単身工事をやりますよ。そうすると、何も補助しませんよという話になってしまうとの意見を述べました。","respondent":"片田都市環境事業部長","answer":"例えば建物のバランスを考えて荷重を均等にならす、通常の大工さんですと、なかなかちょっと難しいところがあります。専門家、それに基づいてチェックをしていくというような体制を、区としてもこれまで進めてきているところです。","id":"exchange-046"},{"speaker":"須藤委員","kind":"意見","question":"そうすると、区側としては、こういう条例みたいなものをつくっていくべきだという考え方になるのかとの意見を述べました。","respondent":"片田都市環境事業部長","answer":"区としては、これまでも条例をつくらずに要綱という中できちっと動いてきたところがあります。あるいは関係機関とも連携をとってやってきたところですので、きちっと今の制度の中で対応できるということで考えております。","id":"exchange-047"},{"speaker":"須藤委員","kind":"質問","question":"何かそこの辺が少し耐震化が進んでこないというのに、難しくハードルを上げてしまっているんじゃないかな。同じような形で補強というのはできると思うんだけれども、そういう改修も今のお話だとだめですねという話になってしまうことなんか尋ねました。","respondent":"片田都市環境事業部長","answer":"建物は壊れても、シェルターを設置したからといって、耐震化率が１以上に上がるわけではありません。やはり一番命が大事ですので、そういうところについても一定の評価が得たものに対して区としては支援してきているというのが実態です。","id":"exchange-048"},{"speaker":"須藤委員","kind":"質問・要望","question":"それが６ぐらいでも、そこまで完璧なものを求めないでも、廉価な費用でそういう仕組みも考えられないだろうかということで要望しているんだけれども。きちんと対応するよというようなことをしていかないと、次のステップに行かないだろうと思うんだけれども、そのあたりはいかがか尋ねました。","respondent":"片田都市環境事業部長","answer":"既存の建物でも、例えばシェルターを入れていただく、そうしたセット論でいろいろな角度から対応していかなければいけないと考えていますので。時間がかかるにしても、耐震化につなげていただきたいというところは粘り強く対応していかなければいけない立場だと考えております。","id":"exchange-049"},{"speaker":"須藤委員","kind":"質問","question":"理事者に質問していた経緯があるんだけれども、こういう助成をしてもそんなに変化がないよというのが今までずっと聞いてきているんだけれども、そのあたりはどういうにお考えになるのかな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そのベースの数を大きく増やしていくということが必要なんじゃないかということで今回提案をするものなんですけれども、平成１９年から平成２７年までの９年間の計画で、木造住宅を９,８００棟耐震化……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そういうところで進めたいということで、今回は提案をさせていただいたということなんです。今までも８年間で６１７棟という耐震診断の実態ですので、この一般診断を増やしていくということが第一歩になるということで提案をしていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"須藤委員","kind":"質問","question":"耐震化率を上げていく方法というのをほかのステップで考えていこうというのが我々が考えていることなので、そういうお話だけして、質問じゃないです。これは自分の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"耐震化の前提として一般診断が必要だということなので、やっぱり耐震化を進めるにはこれを広げていかない限りは耐震化が進まないという、そういう仕組みになっているということを一言つけ加えておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"須藤委員","kind":"質問","question":"どこがどういうふうに直せばいいんですかというお話を実際的に、私自身はちょっと違うな、同じお金を使うなら違った仕組みづくりで考えてもらいたい。そこへ入らなくても、壁をどうするよというようなときに、何とか対応していってもらえればというような話は前からしているんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"自分の命、その建物が倒れてどういう影響を与えていくのかということに対しても本当に認識できるというのがこの一般診断だと思うんです。本当にまちにどういう影響を与えていくのかということを認識する大きな認識の一歩にもなるし、今回、提案をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"原副委員長","kind":"質問","question":"先ほどちょっと、先に行政のほうにお聞きしたい。議案提出者ではなくてお聞きしたいのは、現状はどんな形での意見が出ているかというのは、その辺は把握されていますか。","respondent":"品川防災整備担当課長","answer":"協定機関ですけれども、建築士事務所協会のほうで１２万円でやっているというような形になっております。意見というのは、完全に１２万円以上費用がかかるということで、かなり好評ということはいただいております。","id":"exchange-057"},{"speaker":"原副委員長","kind":"提案","question":"私も逆に自民党提案の、そっちに回したほうがいいじゃないかというのは、個人的な意見としては賛成です。そういったものが発生しないかどうかというのは、その辺、どうなんか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"原副委員長","kind":"質問","question":"そうすると、調べがつかなかったりするケースもあるんですね。ですから、１回これ、そういう質問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そしてそこに、申請を出されたときに、そこのところで信用のできない耐震診断の専門家が入るということはまず考えられないということで思います。そこのところが条例の中にも盛り込まれていますので、そこで問題が起こるということにならない担保がされていると考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"原副委員長","kind":"意見","question":"やってくれるそこの協定先自体が対処できるのかどうかという問題、それから今度は区のほうが、これまた調べるのにもある程度大変な苦労が出てくる。その辺はどうなんでしょうとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回、無料化というこの条例が通れば、耐震診断は多分増えると思うんです。多くのところで、これは耐震診断が増えたとしても、それに対しては対応できる体制はとれるということで品川区からは伺っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"原副委員長","kind":"質問","question":"党ではなくて、その先に進んでいないというところがあるものですから、その先どうするんだというのが非常に大きい問題であろうかなという気がします。それによる悪影響というか、反作用というか、その辺をどうしても私は危惧してしまうというのが個人的意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この無料化しているところには直接お伺いしたんですけれども、５割までは行きませんけれども、４０％耐震化に結びついているということで。今回、それだけでベースが広がるわけですから広がるという部分と、さまざま対策は努力と工夫が必要だというふうなところで思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"須藤委員","kind":"意見","question":"今、区でも２項道路にしようというので、新しいまちづくりの方策をつくっているわけだよね。もうそういう場所は逆にとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"これは現在、品川区が要綱で定めているものをそのまま条例にしたものなんですね。助成金額を基本的に全額助成ということに改める内容ということで提案をするもので、品川区に今までどおりしていただくということになると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"須藤委員","kind":"意見","question":"それから、先ほど言ったように、どういった安全な形をとってあげられるのかということを考えていってやろうというのが行政だろうと思うので。そういった方向性というのをやっぱりつくっていくべきだろうと思うので、ここのところは、この辺も課題があるなというように思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"しかもそれに対して３％しか実現できていないということで、やはりこれを大きく進めていくということが今求められているんだと思います。こういう対策を本当にあらゆるところからとっていくということが求められていくと思いますので、ぜひこれを実現していきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]},{"id":"topic-05","title":"平成２４年請願第７号、家具転倒防止対策助成制度の拡充を求める請願","agenda":"平成２４年請願第７号、家具転倒防止対策助成制度の拡充を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"阪神・淡路大震災のところでも、家屋の倒壊や転倒による圧死というのがかなり多かったと思うんですが、そこら辺のところでは、区としては家具転倒による命の危険ということについては、どう考えられているのかお聞かせほしいと求めました。","respondent":"鈴木防災課長","answer":"建物自体がつぶれたことによって家具の下敷きになったという方が多かったと聞いております。区民の方が命を落としてよいということにはなりませんので、それについては区としても全力を挙げて取り組んでいくという考え方を持っております。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"自助、自助ということではなくて、その点ではいかがでしょうかということです。区としてもぜひそこで命が守れるというところにつながるわけですから、そこに足を踏み出すべきなのではないかと思うんですが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"お預かりした税金です、その財政と限られた人員の中で、やはり優先順位をつけて取り組むという必要は自治体の責務として持っていると考えております。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"全戸配布をして、その翌年には１０倍ぐらいに増えて、８,０００世帯を超える方々がこれを活用したということでお聞きしました。もう既に１万６,０００世帯を超えて、区民の命を守るというところで、ぜひ予算を組んでいただいてやるべきだというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうちょっと大変だなという方のお力添えをするという意味での、そういうことではなかったのかなと思うので、それを質問させていただきたい。どうだったか尋ねました。","respondent":"鈴木防災課長","answer":"今、委員ご指摘ございましたように、今回、従来の家具転倒防止に関する助成につきましては、高齢である、もしくは障害をお持ちであるというような個人の事情によって、自助を基本とする備えができない場合に、区として、福祉の視点で支援をするという制度となっております。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"区民の命を守るということで、家具転倒防止器具を大きく広げていくということが本当に重要な状況だと思います。巨大地震がいつ来るかわからないという、そういう状況の中で、これをぜひ実現させていきたいと思いますので、採択を主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"}]},{"id":"topic-06","title":"補助第４６号線（小山台地区）の開通","agenda":"補助第４６号線（小山台地区）の開通","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"ブロックが並んでいて、あとはそれを撤去するだけかなということで、本当に利便性が上がるのかなということを期待したいなと思います。あちらのほうまで今事業中ということですけれども、これ、大体目安としてはいつぐらいになるのか尋ねました。","respondent":"藤田都市計画課長","answer":"事業の期間ですけれども、平成２７年度までということで聞いております。今のところ、これに向けて進めているということで確認しています。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"補助第２６号線とか、２０メートルということなんですが、もう既に何メートルぐらいあるかというのを教えていただきたい。それは多分もう既にここまで、これからここを広げていくというのではなくて、もう既に進んでいるということでいいのか尋ねました。","respondent":"藤田都市計画課長、松代防災まちづくり事業部長","answer":"事業のほうですけれども、事業を都市計画道路の事業としては完了している区間ですので、基本的には２０メートルと同じということになってあります。概成区間ということで、ほぼでき上がっている区間ということで… ただ、都市計画道路としての２０メートルの幅は現在ございません。これは基本的に東京都のほうの事業ですので、今後、その概成区間をどうするかというのは、まだ現在示されていないところです。","id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この道路ができたことで交通の変化というのがどういうふうになるのか教えていただきたいのと、そこら辺を教えていただきたいのと、それから。例えば、立ち退き料にどれぐらいかかって、道路の建設にどれぐらいかかってというふうなものがわかったら教えてほしいと求めました。","respondent":"藤田都市計画課長","answer":"その人たちがどうしたいかという考え方もありますので、希望するような方については近場の土地を提供する中で住み替えを進めてもらってきてあります。１４１億円の内訳ですけれども、それ以上の中身については教えてもらえなかったので、ご容赦願いたいと思います。","id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その方々の立ち退き料とか、そういうふうなものというのはどういうふうになるのか。そこに持っていた土地は、その土地の価格というか、そういうものはどういう形で決められていくのかというあたりを教えてほしいと求めました。","respondent":"冨久増用地担当課長","answer":"具体的な中身については私どものほうでは存知しておりませんが、一般的な公共事業に対する補償の考え方についてご説明申し上げます。それから次に、当該土地の上に家屋等が存在する場合には、当該家屋の移転に伴う費用、これについて補償させていただいてあります。","id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"基本的なことがわからなくてすみません。家を建て替えるための費用ではないですよね、引っ越しするための費用という、そういうことなんか尋ねました。","respondent":"冨久増用地担当課長","answer":"その場合には、その家屋が全面的に予定地にヒットしてしまうという場合には、建物を再築をするための費用の補償ということになります。それぞれ個別具体の状況によって補償の形は変わってまいります。","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"何軒が立ち退いたかという、その件数はわからないということですね。この道路をつくった業者というのは、どういうところがやっているのかを、ちょっとすみません、どういうところが道路建設を請け負うのかなと思ってとの意見を述べました。","respondent":"松代防災まちづくり事業部長","answer":"数値的なこと等は、東京都が事業主体ですので、先ほど担当課長から申し上げたように、把握はしてございません。実際行いました企業についても、土木、道路を主とする企業が請け負ってやったものと承知しております。","id":"exchange-079"},{"speaker":"原副委員長","kind":"質問・要望","question":"５月なんていうのはかむろ坂というのは桜が有名なところですから、車、その辺のところでの交通体系が変わってしまうということがあるものですから。公園が２カ所、ここのかむろ坂にあるので、子どもがいろいろ行き交いすると思いますので、その辺の思いがあればお願いします。","respondent":"松代防災まちづくり事業部長","answer":"今回の１６３号線と同様に、幹線道路のほうにきちんと通って生活道路のほうに車が入っていかない、そういった効果が当然見込まれます。","id":"exchange-080"}]},{"id":"topic-07","title":"木密不燃化１０年プロジェクトの先行実施地区の提案書提出","agenda":"木密不燃化１０年プロジェクトの先行実施地区の提案書提出","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つは、この支援３のところで、そういう考え方の住宅ということでいいのでしょうか。これは具体的にどこにどのようなものの整備ということの計画があるのであれば教えてほしいと求めました。","respondent":"品川防災整備担当課長","answer":"地域への説明ですが、この間、地域の町会長、それからコア事業地区であります旧同潤会地区の役員に向けては説明を行っております。場所については、やはりかなり広い土地が必要となりますので、現在のところは未定ということです。","id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"町会長や同潤会の方に説明をされたということなんですが、今回の提案について説明されたということなんでしょうか。支援というところは、どういうことがあるのか、そのこともお聞かせほしいと求めました。","respondent":"品川防災整備担当課長","answer":"東京都の最終的な木密地域不燃化１０年プロジェクトの中でどういう支援をやっていくのかというものがはっきり決まったときにお伝えをしていこうとい…こういったところも支援１にありますファイナンシャルプランナー等の派遣をしまして、資産のアドバイスとか。","id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、協議会なり、地域なりに説明会をしていただく時期というのはいつぐらいになるのか、そのことを教えてほしいと求めました。それと、このコア事業、どれくらいの補助金が出るのかというふうなところがわかっているところがあったら教えてほしいと求めました。","respondent":"品川防災整備担当課長","answer":"それから、補助の種類ですが、こちらは防災街区整備事業という事業を行って、旧同潤会地区は共同建替えをしていこうというような考えはあります。この事業の中での補助を使って建替えのほうを行っていくような形になるかというふうに考えられます。","id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"指定されたらどういうふうになっていくのかという手法のところも含めて、ぜひお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/142731?Template=document&Id=4040#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":62666,"voices":268}},{"id":"h24-20120625-9","meetingId":"h24-cm06","date":"2012年6月25日","dateIso":"2012-06-25","committee":"文教委員会","time":"午前１０時００分～午後３時３５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を83件整理しています。","topics":[{"id":"topic-01","title":"平成２４年陳情第８号 「いじめ防止条例」制定に関する陳情","agenda":"平成２４年陳情第８号 「いじめ防止条例」制定に関する陳情","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"幾つか確認をさせてください。そういう今の現状の学校現場で、このいじめに対する具体的な取り組みはどうされているかということを、まずご答弁をお願いいたします。","respondent":"太田指導課長","answer":"現在の現場での対応についてですけれども、教員がそれについて確認し、対応すると。その他保護者、そこのところは連携をとりながら、現在は対応しているです。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"おそらく千差万別のごとくあって、いろいろなケースがあるでしょうから、個々のケースに応じて臨機応変に対応をしていると思うわけです。だからその確認が欲しいんです。","respondent":"太田指導課長","answer":"委員がおっしゃるように、その態様については千差万別ですので、いじめに対して明確な基準というものはございません。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"確認","question":"その問題を解決していくためには、現場の教師の臨機応変な態度がどうしても必要になってくるわけです。ただ、それから約３５万人の区民の方々に条例の適用が及ぶと私は判断するのだけれども、それでよろしいでしょうかという確認をお願いします。","respondent":"太田指導課長","answer":"いじめについては、先ほどもご説明申し上げたとおり、学校だけではなく、広く学校内外、そして品川区全体。そして対象も小・中学生だけではなく、全区民を対象とするものだと考えております。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"条例の適用範囲のことについて、もう一回確認させてください。品川区の条例の適用範囲というのは、およそ２３平方キロメートルの品川区の範囲と品川区民の方にだけ適用されるのか尋ねました。","respondent":"田村教育次長","answer":"条例には２つの考え方があると思います。先ほど指導課長の説明の中でも出ていましたが、学校と言っている意味が、文言で書いてあるわけではないんですけれども。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"もしその罰則を運用するに当たっては、それこそ警察を呼んで、行政が逆に訴えられる可能性も出てくるわけではないですか。その事実を確認するのかということをやはり考えていくと、そういう条例で決めることができる罰則の上限の確認と、答弁をお願いいたします。","respondent":"田村教育次長、太田指導課長","answer":"実際にこの事例が発生すれば、だれが判断するって、学校も判断できない。本当にそれをだれが判断して、実際刑法の第何条適用になるかというのは、すごく難しい話になると考えます。ただ、処分・罰則を伴うような条例に当てはめるような状況をつくり出せるかというと、それはなかなか難しいということです。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"意見","question":"だから、今、私が思うのは、条例化すると、逆にその辺が縛られる可能性が今の現状は出てくるわけです。より実践的・具体的、現時点ではこの陳情に対して、なかなか理解できないということだけお話をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"阿部委員","kind":"提案","question":"先ほどから指導課長のお話を伺っていて、これも難しいみたいな言葉をすごく言われていたんですけれども、どうなんでしょうか。個々の文言や提案に細かくこだわるよりも、どうしたらいじめをなくせるかという視点で、私は伺いながら率直なところ感じましたとの意見を述べました。","respondent":"太田指導課長","answer":"そして最終的に８年生、９年生になると、互いを尊重した対応というのはどういうことなのか。ただ、学校とすればそういった対応をして、保護者の信頼も得ながら進めているところです。","id":"exchange-007"},{"speaker":"阿部委員","kind":"提案","question":"でも、学習だって頭に入ってこないでしょうから、ぜひこういったことは力を入れてやってほしいと求めました。ご答弁は難しいかもしれませんけれども、教育委員会としてのお考えをお聞かせいただきたいとの意見を述べました。","respondent":"太田指導課長、若月教育長","answer":"その対応というのは、その対応についても共有しているので、平成１８年度の状況のままで我々が対応しているというのではございません。定義が不明確であったりする中で… 条例化して対応するというのは、多分、委員のお心の中にも、例えば学校を委縮させるとかという懸念があるというお気持ちを感じました。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問・要望","question":"やはり例えば先生方にこそ今の状況というのをわかっていただきたいし、新しい状況、その知識と行動をリファレントしていく。そういった意味で、抜け・漏れのない対策を教育委員会のほうでもとっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鶴委員","kind":"質問","question":"指導課長が、例えば現場で実際そういうことに当たられて対処されたというご経験があるかどうか、最初にそれだけ教えていただけますか。細かいことは結構です。","respondent":"太田指導課長","answer":"私も３月までは学校現場におりましたので、学校である以上、いじめ等も含めて子どものトラブルといったことはないことはないです。そういった形で対応しましたし、保護者の方も、そういったところでは非常にその問題が長期化するというようなこともありました。","id":"exchange-010"},{"speaker":"鶴委員","kind":"質問","question":"その当事者の私ですから、こんな問題がどかんと出てくる以前からですから、二十三、四年前です。なければないでいいです。","respondent":"太田指導課長","answer":"おっしゃるとおりだと考えています。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"減少はしているのか、増えているのかも含めて、もし変化がありましたら教えていただきたい。なぜ起きてしまっているのかと、今の実態はどうなのかというあたりを、ちょっと説明を求めました。","respondent":"太田指導課長","answer":"正直申し上げて、今までずっと学校も対応してきたところでも根絶できないというところでは、まだはっきりとらえることはできていないと思っています。","id":"exchange-012"},{"speaker":"南委員","kind":"意見","question":"ちょっと相手をいじめてしまったりとか、そのような状況があるのかなという思いがしているので、その辺はどういうふうに教育委員会としては見ているのかということを聞きたかったんですけれどもとの意見を述べました。","respondent":"太田指導課長","answer":"いじめられたとか、いじめたとか、いじめられたと感じるような原因につきましては、多分その相談についてもいろいろな理由があると思います。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"現場の先生に伺ってみたら、ちょっと回数はわからないんですけれども、アンケート調査を年１回とっていると。そういう思いもあってアンケート調査をしているんだろうとは思うんですけれども、そのあたりの調査の状況がどんなだったか、説明を求めました。","respondent":"太田指導課長","answer":"少なくとも学校は年に３回以上はそれを質問紙により行っているところです。それで状況をつかみ、対応しています。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"アンケートの中身も詳しく知りたいとは思ったんですけれども、よしとして、別の機会に伺わせてもらいます。そういういろいろな状況があると思うんですけれども、不登校の状況をもうちょっと、あわせて関連して伺っておきたいと思っているんです。","respondent":"太田指導課長","answer":"同じように、文部科学省のその調査によりますと、この不登校の数、発生率につきましても、品川区は東京都や全国よりも低い発生率となっている現状です。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"それから学ぶ権利と同時にさまざまな１人の人格を持った人間として、そういう部分では、時間的にも非常に大きなものがあると思うんです。その辺の子どもの権利との関係で、どういうことを意識して学校教育をしているか、そのあたりについての教育委員会の見解を伺いたいと思います。","respondent":"田村教育次長、太田指導課長","answer":"これも全国規模だと欠席日数が３０日以上の場合ということなんですが、品川区の場合には、継続して７日以上欠席のものも報告させています。件数は１月以上ではなく、１週間以上というものと、一定の効果があったものと思います。 その子どもがどういうふうに学校の中で育っていったらいいのかということを保護者の方とも連携をし、そこのところを学校もしっかり考えながら対応していきたいと、教育委員会としてもそのように考えております。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"解決をしてもらうということを求めようということで、学校にしっかり調査をしてほしい、相手もやはり複数だったんですね。トラウマにさせないかという問題でやはり見ていくべきだと私は思うので、意見として言ってしまいますけれども、この陳情には賛成できないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"高橋委員","kind":"意見","question":"これは会派のほうでもどういう取り組みをしているのか、きちんと説明してほしいということがあったので、教育委員会はそういうふうにわかりました。お尋ねしたいのは、どれぐらいの法的位置づけが教員や教育委員会に対してあるのかということをご答弁くださいとの意見を述べました。","respondent":"太田指導課長","answer":"それにつきましては、守らなければいけないというものだと考えております。","id":"exchange-018"},{"speaker":"高橋委員","kind":"質問","question":"それからあと、資料３ではアンケートをとるようにと出ているわけですね。ですからそれに伴って、この通知に基づいてきちんと指導していくかどうか、委員会も含めて一緒にいじめをなくしていく努力をしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"提案","question":"それから、これは提案ですけれども、例えば品川区は人権宣言を既にやっていますね。ですから、本陳情については、そういう意味で反対と表明しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"鶴委員","kind":"質問・要望","question":"やはりいじめの根絶というのは引き続き徹底して行っていただきたいというところでは、学校の先生も含めて、より一層の教育指導の徹底をお願いしたい。そこのところを強化していただきたいという意味で、この陳情については反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"高橋委員","kind":"意見","question":"先ほど一つ言い忘れたんですけれども、それも資料１の中に、隠ぺいしたりそういうのをしたらいけないというふうに通知で出ています。どうバックアップしていくべきかということが大事だと思っているので、条例化という点では、私はやはりこの陳情には採択できないということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"阿部委員","kind":"質問・要望","question":"それをどういう形でとっているのか。不断の努力を続けていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"あるいはＰＴＡも含めて理解することが、ぜひそういう努力はしていただきたいということを、この陳情を契機にお願いしておきたいと思っています。そのために、教育行政の改善ということで、教師の配置もしっかりとやっていただきたいということもお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-02","title":"はじめに、(1)の校舎改築事業の進捗状況","agenda":"はじめに、(1)の校舎改築事業の進捗状況","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"ちょっと確認させていただきたいのですけれども、やはり工事があるということで、かなり利用できる面積が少なくなると思って見ております。一番少ない時期で、この校庭の使用面積というのは、通常に比べてどのくらいになっているんか尋ねました。","respondent":"齋藤庶務課長","answer":"正確なものはわかりません。ただ、おおむね半分は大丈夫だろうということで、理解をしております。","id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"かなり子どもたちの戸外の活動が制限されてしまう。やはり成長期の子どもたちですから、どのような形で運動量を補っていくと考えていらっしゃるのか、説明を求めました。","respondent":"齋藤庶務課長","answer":"ご説明したとおり、通常の改築の中ではベターなほう、いいことだということはご理解ください。近隣に品川学園がありますので、今後具体的なお話をさせていただいて、特に授業量の確保には努めてまいります。","id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"その分が狭くなっているという状態なんですけれども、この旧園舎は、すまいるスクール以外にも使う予定はあるんでしょうか。園舎も撤去してしまって、かなりそれだけでも使える面積が広がるのではないかなと思うので、そういうお考えはないんか尋ねました。","respondent":"齋藤庶務課長、田村教育次長","answer":"丸々使えない時期はステップ４の４カ月ぐらいで、工事の中でどのように活かせるか考えてみたいと思いますが、なかなか難しいと思います。それで、残りをすまいるスクールで使うということなので、私どもとすれば、プレハブを建てたりするのは危なくてできませんので。","id":"exchange-027"},{"speaker":"阿部委員","kind":"意見","question":"今の点、了解しました。御殿山小学校については、今後地域の方への説明会なり、情報開示というのはどのように考えていらっしゃいますかとの意見を述べました。","respondent":"齋藤庶務課長","answer":"都度５回ほど説明します。もっと広く地域の方には、条例に基づく説明会を１２月末前後には開催する予定です。","id":"exchange-028"},{"speaker":"南委員","kind":"確認","question":"そのあたりのことをもう一回しっかり確認したいんですけれども、補強にとどまらずに改築する、反対することは全然ないと思います。どこまでどの程度進んでいるのかというのを、ちょっと最終的に確認したいんです。","respondent":"齋藤庶務課長","answer":"耐震補強工事は、小学校では２５校、中学校では６校実施済です。改築は小学校で６校、中学校では２校、一貫校では５校改築していると。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"そのあたりの見通しをちょっと伺いたいのと、中学校６校というのは、計画的にやってきた。改築を全面的にしていきたいという方針に変わったんだなという印象を持ったんですが、そのあたりのことはどうか、ちょっと説明を求めました。","respondent":"田村教育次長","answer":"説明が不十分だったと思うので、ちょっと補足しますが、改築を先行してやるなんていう考え方は品川区ではありません。補助金は５年ないし１０年、当面改築の予定も、今のところ全く予定はないです。","id":"exchange-030"},{"speaker":"南委員","kind":"確認","question":"最後に確認ですけれども、今回示された御殿山小学校の改築工事をもって、品川区の小・中学校は、小中一貫校も全面改築ですから、もちろん、すべて耐震は十分整ったというふうに理解していいですね。","respondent":"田村教育次長","answer":"おっしゃるとおりで、スタートを切って、当初は私が庶務課長になった４年前、５年前は２３区中２３番だと。スタートが早過ぎたのがあだになってしまったというような形ですけれども、今回の御殿山小学校で１００％ということになります。","id":"exchange-031"},{"speaker":"南委員","kind":"意見","question":"それでようやく、今、理解しました。何で急に数字を示さなくなってしまったのかなと思っていたんですけれども、今、ようやくわかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-03","title":"区立学校教育職員採用候補者選考日程について それでは、引き続き報告事項を行います。 午前中では、報告事項(1)まで終了しております。それでは…","agenda":"区立学校教育職員採用候補者選考日程について それでは、引き続き報告事項を行います。 午前中では、報告事項(1)まで終了しております。それでは…","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"すべて品川区内の先生になるだろうから、そうするとその方々をどういう位置づけで、小学校、中学校、一貫校を含めて勤務をしていただくのか。これは品川区の職員ですから品川区の基準によるでしょうから、この方々は、そのことについての位置づけをここでお願いいたします。","respondent":"太田指導課長","answer":"そしてまた、教諭経験おおむね８年目ぐらいの教員が一般の教諭をリードし、そしてまた育成を担当するような位置づけで、主任教諭という職があります。まだ副校長、校長に向けては、これから整えていかなくてはいけないと思って、これからの課題になっているところです。","id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、理論的に考えていくと、この方々は将来副校長、校長になれないとおかしいと当然思うわけですね。ですから、校長のことについての考え方を、もう一度お願いいたします。","respondent":"太田指導課長","answer":"そこのところをしっかりそういう制度を整えていかなくてはいけないと考えていますので、今、検討しています。","id":"exchange-034"},{"speaker":"伊藤委員","kind":"質問","question":"この３０名の方々に対して、どういう実績を品川区教育委員会としてはやってもらいたいと願っているのか。学校内での位置づけなり方向性なりを、この目的が達成されないと思うんだけれども、そのことについての考え方はいかがか尋ねました。","respondent":"太田指導課長","answer":"この品川区の固有教員につきましては、本区の教育改革の原動力となるような位置づけの人材になってほしいと考えています。品川区長からいろいろな方針を直接伺うとか、あとは教育長もそうですけれども、特にそういったような研修も年間を通じて実施して。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"特に自民党は独自教員を採用しろと言ったほうですから。実にこの目的を達成するのではないかと思うので、そういうことをやりますとの方向性の答弁をもう一度お願いして、終わります。","respondent":"太田指導課長","answer":"この品川区固有教員につきましては、今、お話のあったように、品川区の教育改革、それから小中一貫教育等を強力に推進する原動力として、品川区の教育委員会も育成していく方向でやってまいります。","id":"exchange-036"},{"speaker":"阿部委員","kind":"確認","question":"ちょっと聞きにくいことを伺いたいんですけれども、期待するレベルの応募者が集まってきていないという現状をあらわしているものなのでしょうか。そこを確認したいのと、やはりそこら辺の人を確保するのが難しいという背景があるのかなと思いながら聞いていたんです。","respondent":"太田指導課長","answer":"まずは人物本位、人材本位というところで、厳しい目で採用しているということが一つ大きなところだと考えています。後ほど倍率等も調べてご報告申し上げます。","id":"exchange-037"},{"speaker":"阿部委員","kind":"質問","question":"品川区だってやはり東京の中の自治体として、厳しい現状があるだろうと思いますので、そのこと自体を責めるつもりはありません。どういうような採用計画で考えているのかということを、今後の見通しなり、その辺のことをまず教えてほしいと求めました。","respondent":"太田指導課長、田村教育次長","answer":"先ほどの倍率ですけれども、昨年は約１５倍というところの倍率です。毎年その採用状況も見つつ、必要な人材をまず資格要件にも加えながら、いい人材の確保に努めていきたいと考えています。今までずっと議会で答えているのは５名６年で３０名ですけれども、人物本位で、処遇であわない人は採らないほうがいいだろうと。","id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"確かに学生さんにとっては就職ですから、先に内定が出たほうにどうしても傾いてしまうというのは、すごくよくわかります。この制度をつくったときに、実際にはなかなかそこが意外にも時間がかかっていて、ちょっと今後の見通しとしてどうなんか尋ねました。","respondent":"田村教育次長","answer":"突然５年、６年するとほかの三多摩へ持っていかれてしまうということになると、そのご本人も品川区にずっといたいと言っている人に相反してしまう。その機会にやはり品川区の主張を、すぐ動くかどうかわからないにしても、事あるごとに主張をしていきたいと考えております。","id":"exchange-039"},{"speaker":"阿部委員","kind":"意見","question":"２分の１や３分の１にかけてあれだけ自由になっている中で、しかも３０万人ぐらいの中核市では相当委譲が進んでいるわけです。これは個人的な感覚ですけれども、これについてもう少し名前を考えたほうがとの意見を述べました。","respondent":"太田指導課長","answer":"これにつきましてはそれほどこだわりはございませんので、このまま使用してまいりたいと思います。","id":"exchange-040"},{"speaker":"南委員","kind":"質問","question":"今までの質疑を伺っていると、わかりましたというふうには、ちょっと私としてはなり切れないかなと思って聞いていたんです。いずれ数年経つと何かそごが出てきやしないかという心配をしてしまったんですけれども、その辺についてはどういうふうに考えているのか、伺います。","respondent":"太田指導課長","answer":"それから、この独自の研修等で育てていく、将来的に教員として何かそごが生じるのではないかということですけれども、そういうことは全くありません。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"だからそういうことで、そごというか差異があっていいのかというのは非常に懸念します。そういうことはないと言い切っておられるけれども、そこは重々きちんと大事に見ていただいて、取り組んでほしいと求めました。","respondent":"田村教育次長","answer":"一番これから考えていかなくてはならないのは、東京都と協議しながら進めるとか、大崎中学校の校長先生がキャリアの人でしたね。そういうけん引役を担ってほしいということで、今回の研修だとか何かをやっているというふうにご理解いただきたいと思います。","id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"Ｃさん、その学校の中で研修・研究を繰り返してつくり上げていくものだと思うので、そこは本当に大事にしていただきたいと思っています。独自採用教員と都採用教員に差異があっては絶対ならないわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"高橋委員","kind":"質問","question":"中学校の先生が、今、９人いるんですけれども、教科がわかればというのが一つ。二つ目が資格要件で、今年変わったと言いましたけれども、それを変更した意図を教えてほしいと求めました。","respondent":"太田指導課長","answer":"申しわけありません。例えば英語でありますと、小学校の免許、それから中学校の免許を有する者という形に要件を変えました。","id":"exchange-044"},{"speaker":"高橋委員","kind":"意見","question":"４つの教科が中学校であるということで、そういう点について、今年の予定等も含めてお尋ねしたいんですがとの意見を述べました。","respondent":"太田指導課長","answer":"今回の要件が小学校・中学校ということですので、教科は特に限定しておりませんので、中学校の免許につきましては、その教科を限定して、何かこの教科ということでとらえているということではございません。","id":"exchange-045"},{"speaker":"高橋委員","kind":"質問","question":"そうなると、中学校の先生はやはり教科の専門性が小学校の先生に比べると必要だと思うんです。その教科の専門性についてはどこで担保しているのでしょうかという感じがあるので、この選考内容のどの辺で選考されているんか尋ねました。","respondent":"太田指導課長","answer":"教科の専門性につきましては、もちろん一次選考のうちでも、そこの内容について、点数だけでなく内容も見ていきますけれども、二次選考で個人面接、集団面接等もありますので、そこで個別に面接をしたり、集団の中でやり取りをする中で見極めていくという形になります。","id":"exchange-046"},{"speaker":"高橋委員","kind":"質問・要望","question":"最近では模擬面接を二次試験で行って、そういったことも今後二次選考の中で入れていっていただければ、力が見極められるのではないかと思います。これは要望です。","respondent":"太田指導課長","answer":"それから中学校の英語が３名、理科が４名、数学が１名、体育が１名です。失礼いたしました。","id":"exchange-047"}]},{"id":"topic-04","title":"の貸出期間の短縮","agenda":"の貸出期間の短縮","exchanges":[{"speaker":"阿部委員","kind":"確認","question":"それを１点確認させてください。そこも一応確認です。","respondent":"中元品川図書館長","answer":"予約があるものは、現在も延長はできない状況です。図書館ホームページのほうですが、図書館ホームページのほうで表示をします。","id":"exchange-048"},{"speaker":"阿部委員","kind":"質問","question":"今後は１回は延長ができるという話でよろしいんですね。ではなくて、１回だけでも延長はだめということか尋ねました。","respondent":"中元品川図書館長","answer":"１回のみ、延長はできます。","id":"exchange-049"},{"speaker":"伊藤委員","kind":"質問・要望","question":"その中で、わからないから教えていただきたいので質問しているんだけれども、予約をするには、当然利用者が何かしら登録をするわけですか。やはりインターネット予約の方々に対して、それも活用したらどうですかということなんだけれども、間違っていたらごめんなさい。","respondent":"中元品川図書館長","answer":"すみません。ちょっとそこの点につきましては、技術的にできるのかどうかを確認をさせていただきまして、課題とさせていただきたいのですが。","id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"もしあれば教えていただきたいのと、こう考えているけれどもどうだろうかみたいな、そういう対応というのはされているんでしょうか。もししていないのであれば、私はする必要があるのではないかなと思っているんですけれども、そのあたりの見解も説明を求めました。","respondent":"中元品川図書館長","answer":"期間短縮のことですけれども、実際に統計上、システムで管理しておりますので見ましたところ、１０冊以内の方が９２％という状況があります。もう一つの利用者の方にご意見お伺いしてはというご提案かと受け取りましたが、現状ではそういうことはいたしておりません。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"早く返している人は早く返しているわけですから、９２％が１０点しか借りていないし、聞いていて思うんです。どれくらい、どういうふうに検討されたのかというのがちょっと見えなかったので、伺いたいなと思ったのですけれども。","respondent":"中元品川図書館長","answer":"図書館の内規で最大２０冊しか買わないということで、どんなにリクエストが来ても、２０冊以内にしましょうという内部での申し合わせをしています。同じ状況、今までの運営の中から私どもは認識していますので、あえてまたここで何かをお伺いするということは考えておりません。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"最後に聞きたいと思います。しつこく質問させていただいたんですけれども、経験上こうだからということでひとくくりにしないでいただきたいという要望を表明したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]},{"id":"topic-05","title":"の病児保育の新規開設","agenda":"の病児保育の新規開設","exchanges":[{"speaker":"南委員","kind":"質問","question":"やはりどうしても休めないご家庭にとっては一定程度の受け皿になるのかなと思うんですけれども、もう少し内陸側にできなかったのかという、その辺のことを伺ってみたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"病児保育室の考え方ですが、品川区の場合は医療機関の併設と考えております。ですので、立地につきましては、確かに目黒区寄りではありますが、品川区内の２カ所目ということで、荏原地区に開設となったものです。","id":"exchange-054"},{"speaker":"南委員","kind":"質問","question":"生後６カ月以上ですから。就学前にしても子どもの命の問題ですから、また一定程度体力が落ちている子どもを連れていくわけですから、いかがなんか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"やはりスペースがないと、開設自体が難しい。なかなか継続していきづらい部分になっておりますので、こちらのサンタハウスこどもクリニックの山田先生に委託をということにさせていただきました。","id":"exchange-055"},{"speaker":"伊藤委員","kind":"確認","question":"一つだけ確認で、今、すぐわからないかもしれないけれども、予算のところで、事業委託費経費月額７７万円とありますね。それとも、毎月この金額を渡すんでしょうかという確認なんですけれども。","respondent":"伊崎待機児童対策担当課長","answer":"事業委託費経費ですが、こちらは人件費見合いと考えておりますので、月額の固定費でお支払いしていくものです。","id":"exchange-056"},{"speaker":"伊藤委員","kind":"質問","question":"そういう中で、果たしてこういうやり方でいいのかどうか、やはり議会からするとちょっと疑問です。当然差異が出てくるわけだから、それはなかなか難しいんですよねという素直な疑問なんですけれども、いかがか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"確かに委員がおっしゃるとおり、病児保育ですので、日によって利用者が４人から、いないときにはゼロという可能性もあり得ます。継続性というのがなかなか難しくなってまいりますので、そのあたりを考えまして、固定費で品川区としては補助しております。","id":"exchange-057"},{"speaker":"伊藤委員","kind":"確認","question":"ただ上限１日４人分だけれども、そういう裏付けとしてこの委託費があるという考え方でいいんでしょうか。確認だけお願いできればと思いますが、いかがか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"病児保育につきましては、これは最後のセーフティーネットということの考えは、変わりはございません。ただ、いつでもあいているからどうぞというスタンスをとっているとは考えておりませんので、適正な定員で運営していくと考えております。","id":"exchange-058"},{"speaker":"阿部委員","kind":"質問","question":"先ほどからご説明にもあったように、病児保育という非常に運営の難しいサービスといったらいいんでしょうか。広報の手段について、開設の広報はどのようにされるか、それを説明を求めました。","respondent":"伊崎待機児童対策担当課長","answer":"特にここまでの見込みということでは、数字としては正直、立ててはおりません。ホームページにはもう少し詳細なご案内を載せる予定です。","id":"exchange-059"},{"speaker":"阿部委員","kind":"確認","question":"例えば認証保育所とか保育ママとか、そういったところの利用者も、この病児保育室というのは使えるようになっているんですか。その辺を確認させてください。","respondent":"伊崎待機児童対策担当課長","answer":"そちらが、今、１カ所ですが、それを今度新規開設があるという形で追加をいたしまして、また各園に置くようにと考えております。それから利用者なんですが、両親も仕事によってどうしても保育ができないということであれば、ご利用ができるという条件になっております。","id":"exchange-060"}]},{"id":"topic-06","title":"の最後となりました(5)の児童センターあり方検討委員会報告","agenda":"の最後となりました(5)の児童センターあり方検討委員会報告","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"それとも、ここではあくまでもこのメンバーの中での話し合いであって、まだ実現に向けてはさまざまな手順があるということなんですか。そういった方々の意見を聞くお考えはなかったのか、とりあえずその２点、まず説明を求めました。","respondent":"安井子育て支援課長","answer":"一応この方針で、内部では検討したという形になります。それから、児童センターあり方検討委員会ということで、ここの中で検討していく中で説明させていただきながら検討しておりますので。","id":"exchange-061"},{"speaker":"阿部委員","kind":"確認","question":"その当時の文教委員会に、それから青少年委員たちは既にこういうことが検討されているということはご存じのことなんでしょうか。改めて確認させてください。","respondent":"安井子育て支援課長","answer":"今まで予算特別委員会であるとか、そういう場で検討していますお話はさせていただいておりましたという形になっております。それから青少年委員のほうの意見とか、そこら辺のところは、あえてこれをやっていますというふうに下ろしているというところではないです。","id":"exchange-062"},{"speaker":"阿部委員","kind":"意見","question":"こんなふうに検討していたのかと出てきてからわかると、青少年委員の職務を崩してしまうかもしれないので、それが今さらながら心配です。ちょっと私もわかりませんが、今後のこととしては、こういうことは事前に伝えておかないとまずいのではないかと思いますとの意見を述べました。","respondent":"安井子育て支援課長","answer":"青少年委員につきましては、ご意見を役員のほうからいただいています。青少年委員との関係で、児童センターとの交流の事業などをやっていて、そこら辺はとり急いでお話しするという形になると思います。","id":"exchange-063"},{"speaker":"阿部委員","kind":"意見","question":"それを受けた再編の児童センターの数だけが２０館程度と極めて具体的に出ていることに、これを読んでいると、何か減るだろうから２０館。ちょっとここがこういう表記に至った背景を知りたいんですけれどもとの意見を述べました。","respondent":"安井子育て支援課長、金子子ども未来事業部長","answer":"大体ベビーカーで８００メートルぐらいが通える範囲だろうと言われているんですけれども、そこら辺がちょっと具体的に急ぎ過ぎたところもあるんでしょうけれども、そこら辺が張ろうかなというところはあります。ですので、乳幼児人口の動向そのものはそう大きくかわらないと思っていますから、下りとしてはかなり大きな下りの数字になってくると見込んでいます。","id":"exchange-064"},{"speaker":"阿部委員","kind":"質問・要望","question":"今のを伺っていても、やはりここで２０館という数字を出すタイミングではないのではないかと。そういった１点をとっても、やはり児童センターとしては考えてほしいと求めましたが、その点はいかがか尋ねました。","respondent":"金子子ども未来事業部長、安井子育て支援課長","answer":"機能的に考えて、今後の児童センターというのはその各地域センターごとに１館というのを中心に考えていこうという考え方が基調になっております。一応目安として２０館というのを出していますけれども、先ほども申し上げたとおり… 遊びに来てもらって追い返すということではありませんので、小学校低学年向けの事業をあえてぶつけるというようなことはしないという考え方です。","id":"exchange-065"},{"speaker":"阿部委員","kind":"質問・要望","question":"それから後半のほうも、ぜひそういう方向であれば慎重にやってほしいと求めました。やはり子どもは敏感ですから、それが子どもに居場所として受け取られるかどうかというのは、ぜひ慎重にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"伊藤委員","kind":"確認","question":"確認をしたいんだけれども、この方向がぽんと出てくると、議会側もいろいろな思いがある。確認したいのが、要は子育て支援課の中に一つのグループがあって、そこで検討した結果を委員会で示したという判断でよろしいんか尋ねました。","respondent":"金子子ども未来事業部長","answer":"ただし、この検討委員会そのものが、先ほど子育て支援課長が申し上げたとおり。それは今後具体的に物事を展開していくときにもう一度検討して、その検討結果というものは、そのような扱いにさせていただければと考えています。","id":"exchange-067"},{"speaker":"伊藤委員","kind":"確認","question":"それこそ品川区の現在の考え方の確認と、それからこの施設そのものが０歳から１８歳までという非常に幅広い年齢層を対象とされているわけです。０歳から１８歳までという幅広い年齢層に対するサービスを提供していくことを考えれば、やはりそれは集約と、いかがか尋ねました。","respondent":"金子子ども未来事業部長","answer":"前提として、これの前提があくまでも児童センターのあり方検討委員会の報告書ですので、この中では児童センターとしてどういうことを考えていくか。あくまでも全体としては、大きなところで、もう一つ別の場で検討してまとめていくべきものだと考えています。","id":"exchange-068"},{"speaker":"伊藤委員","kind":"確認","question":"その中で、私は一定のこういう施設の方向性は持つべきだと思う。だからそこの最後の確認が、コンプリートされたものではないということの確認と、それからこれがこれからどう活用されて。","respondent":"金子子ども未来事業部長","answer":"この児童センターのあり方検討委員会、この５月に報告書を出しておりますけれども、今後来年度中に長期基本計画の改定についての検討が始まります。","id":"exchange-069"},{"speaker":"鶴委員","kind":"確認","question":"委員の質疑の中でいろいろ確認できたことも踏まえた上で、ベビーカーで通える範囲の設定、これは何かそういう基準とかがどこかにあるんでしょうか。それだけ、最初に質問します。","respondent":"安井子育て支援課長","answer":"７００メートルとか８００メートルとかいろいろ言われているんですけれども、そこから算出すると、大体子育ての方も同じくらいの距離という考え方です。","id":"exchange-070"},{"speaker":"鶴委員","kind":"質問","question":"現実では、地域に昔いたような近所の雷おやじのようなスタンスを地域でどう構築していくのかということも、私は大事ではないかなと。まとめていただいたほうの１２ページで、「多世代交流施設へ転用することを推進していく」とありますが、何か意味があったんか尋ねました。","respondent":"安井子育て支援課長、金子子ども未来事業部長","answer":"荏原のほうは、先ほど委員の方からもおっしゃられたように、高齢者の施設のほう、シルバーセンターのほうで平塚橋会館のその辺のところにですね。そういうところもあろうかなと思うんですけれども… そことの交流も実施しているということ、北品川の児童センター、保育園がわりと近接したところにあると。ここで一定程度検討が進められるのではないかということで、品川地区というふうに書かせていただいているところです。","id":"exchange-071"},{"speaker":"鶴委員","kind":"質問","question":"当然あり方検討委員会の中で検討の材料という大前提で、私は、今、質問させていただいているものです。小学生等各世代で(3)の今後の事業展開の中にありますけれども、そういう方向性をつくっていただけたらと思いますので、これは意見として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"南委員","kind":"質問・要望","question":"それはそれでわかるところなので、昭和４１年に初めて中延児童センターができて以降、何年でしょうか。４０年ぐらい経つんか尋ねました。","respondent":"安井子育て支援課長","answer":"児童センターでいっぱいになれば、また別の場所をカットしながらやるとか、そういうことは当然考えていくということは考えとして持っております。","id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"そういうふうな施設の事業に展開できるようにしていくべきだと思うので、そういう角度からのあり方という点で検討もしていただきたい。答弁のほうはいかがか尋ねました。","respondent":"金子子ども未来事業部長","answer":"少なくとも効率性というのは非常に大きな要素として検討の点では考えましたけれども、コストありきということから、この報告書を出したものではない。","id":"exchange-074"},{"speaker":"南委員","kind":"質問","question":"これを読んでいても思ったし、今のご答弁の中を伺っていても、何かまだちょっとそこはわかりません。これを読んでいて、何かそのことを、児童センターのあり方も変えてしまうということをしてはならないということを強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"阿部委員","kind":"提案","question":"手短に１点だけ。逆に提案していきたいところは提案して、非常に必要だったと思いますので、それだけ申し伝えておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"渡部副委員長","kind":"質問","question":"思っていますので、２人欠けるなんていうことがないように、やはりそこの部分はいろいろな地域との調整係が僕は必要なのではないかと思う。ただ、すぐできるところはすぐやるべきではないのかなという思いがあって、１点だけそこを伺いたいです。","respondent":"金子子ども未来事業部長","answer":"長期基本計画を待つまでもなく、実行できるものは、当然のことながら検討していくべきものと考えています。ですので、何か大きく変わる場合には委員会に報告すべきものだと考えていますので、またそれは報告するべきものはしていきたいと考えています。","id":"exchange-077"},{"speaker":"高橋委員","kind":"確認","question":"最後にちょっと確認だけなんですけれども、行政評価委員会でコストについても十分に検討していくという指摘が出ているんですね。今後どのような思いで、長期基本計画の改定の中なのかもしれませんけれども、どこで十分に検討していくのか。","respondent":"安井子育て支援課長","answer":"そうですね。そういった事業全体の見直しの中で、いろいろ不要なものというか、効率化できるものについては精査していくと考えております。","id":"exchange-078"}]},{"id":"topic-07","title":"の３の所管事務調査","agenda":"の３の所管事務調査","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"今、例えばこの保育園運営に関することというテーマで何をするのかがもう少しわからないので、もう少し具体的なところを伺いたいなと。そのあたり、運営に関することの内容と、それから今後の所管事務調査に関する委員長の考え方をお伺いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"阿部委員","kind":"質問・要望","question":"そういった意味で、この三つならこの三つをやるのでもいいんですが、もう少し突っ込んで、何をどのようにやるかという時間をぜひとっていただきたい。よろしくどうぞ。","respondent":"金野委員長","answer":"保育園運営に対する今のご意見をいただきましたので、確かに具体的に何をするのというところでのお示しは、今、していないので、皆さんの中でやはりこの時期、これをということは議論の中に含めていく、そういうことも考えていきたいと思います。","id":"exchange-080"},{"speaker":"渡部副委員長","kind":"提案","question":"１回この土曜授業を見に行くべきではないかというような話も正副でもしていますので、皆さんのご都合とか、やはり行く必要を感じた場合は。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それは必要な手続をとって、そうでなくてもできるわけですから、それはぜひやっていただきたいということをお願いをしておきます。日曜日出張するのであれば、これはまた別の日にかかっているわけですから、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"例えば保育園運営に関することで、待機児童だけでなくて、もっといっぱい問題意識をそれぞれ持っているのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/162678?Template=document&Id=4762#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":76779,"voices":194}},{"id":"h24-20120625-5","meetingId":"h24-cm06","date":"2012年6月25日","dateIso":"2012-06-25","committee":"総務委員会","time":"午前１０時００分～午後１時４６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":")の第４９号議案からの審査でありますが、会議の運営上、審査の順番を入れかえ、(2)の第５６号議案、(3)の第５７号議案を先に行います。…","agenda":")の第４９号議案からの審査でありますが、会議の運営上、審査の順番を入れかえ、(2)の第５６号議案、(3)の第５７号議案を先に行います。…","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"そういうものが盛り込まれているかどうか気になったのでお伺いしたいのと、いつ全体が機能するのか、そこを教えていただきたいのが２点目です。簡単に教えていただきたいのと、資格とかがあるのかどうか、その辺も説明を求めました。","respondent":"平澤経理課長、武藤河川下水道課長","answer":"こちらにつきましては区の職員が行うわけですが、土木工事に関しましては根拠、工法について、国土交通省のほうで考え方が示されております。そちらに基づきまして行っているです。現場でごく簡単にですがご説明させていただきました立会川雨水放流管という工事が、この事業につきましても最低でも約４年間かかると聞いております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"その辺を伺いたいのが、細かい積算などができたんだけれども、今そういうところがなくなっているので。〔「ある」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"国の指針でということですけれども、特に地震などどの程度の規模とか、そういったところまで具体的に指針が出ているのか教えてください。積算から契約金額の妥当性というか、妥当性というのをどう証明できるかというか、伝えられるのかというところをお伺いします。","respondent":"平澤経理課長、武藤河川下水道課長","answer":"お手元の資料３ページの、入札状況調書をご覧いただければと思います。予定価格に占める割合は９１.９％、３につきましても９４％から９８％ということで、この数字については妥当な額だと考えているところです。 これにつきましても国のほうで一定の考え方があります。いわゆるレベル１対応、レベル２対応ということで、そういった地震への対応力というものを事前に計算でチェックして。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういうところもきちんと、こういう契約であってほしいなと思っていますが、区として加味されているところがあったら教えていただきたいのが一つと。最後ですが、支出科目が道路橋梁費になっているのですが、財源を教えてほしいと求めました。","respondent":"平澤経理課長","answer":"発注に関する積算の根拠の中に、こちらにつきましてはその内容の中に入っているというふうに私どもは考えてあります。科目ですけれども、これは受託事業ということで、先ほど河川下水道課長がご説明申し上げましたとおり東京都からの委託事業になりますので。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"それとも定期的に、例えば１０年に１度ぐらいそういうものは排出するようになっているのですか。そういう可能性もないのか、長いスパンを考えてお聞きしたいので、それだけちょっと説明を求めました。","respondent":"武藤河川下水道課長","answer":"そういったものがどうしても下水道管の中に入ってきますので、こういった雨水の排水管には、やはり土砂の堆積が徐々にたまってまいります。","id":"exchange-005"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、貯留をされたものは最終的にどこに行くのか、そこを１点だけ説明を求めました。","respondent":"武藤河川下水道課長","answer":"本工事は、大雨が降ったときに貯留します。ためた雨水につきましては晴天時に水再生センター、そこで処理をして運河、海に放流するという流れになります。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"今の続きで、芝浦の水処理場へはここからどういうふうに行くのか、ちょっと説明を求めました。","respondent":"武藤河川下水道課長","answer":"この図にあります貯留池から水再生センターは、既に整備されています下水道管、この辺は日常今も、汚水は芝浦水再生センターのほうに流れておりますので、そこにポンプアップでくみ上げまして、その既にある下水道管に落とし込みまして、ずっと流れていくです。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この辞退の内容を教えていただきたいのと、受けとめは変わりがないのかどうかというのが１つと、その辺を説明を求めました。","respondent":"平澤経理課長","answer":"調書の２番目のところの「辞退」の原因ですけれども、経営上の理由ということでお伺いしております。３点目のスーパーゼネコンであり、それができる業者につきまして選定させていただいて、こちらの業者が落札されたです。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう一回教えていただきたいのと、処理が終わっているのでということですが、影響は全くないのでしょうか。その辺を聞かせていただきたいのと、そういった予防の手だても教えていただきたいのと、どういった補助金とかがつくのか説明を求めました。","respondent":"平澤経理課長","answer":"入札前の工事説明会等をしていないです。最後になりますが科目につきましては、先ほどのご説明の最後のほうで申し上げましたとおり、経費については補てんされるということになってあります。","id":"exchange-009"},{"speaker":"須貝委員","kind":"確認","question":"確認なのですが、それは今言った地域の方たちからお金が出るということで、こういう支出科目になっているという考え方でよろしいですか。土木費ということで出ると思うのですが、今回こういう支出科目になっていることについて、ちょっと一言お願いいたします。","respondent":"溝口都市開発課長","answer":"第５７号議案の北品川の下水道工事につきましては特殊な事案になっておりまして、そういった経緯に基づいて、今回は都市開発費という形での科目の計上をしています。","id":"exchange-010"}]},{"id":"topic-02","title":"第４９号議案 品川区特別区税条例の一部を改正する条例","agenda":"第４９号議案 品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"石田（慎）委員","kind":"質問","question":"区民税の均等割の標準税率についてお伺いします。東日本大震災の復興を目的として行われるということですが、これをもう少し具体的にどのような趣旨で行われるのか、お聞きしたいと思います。","respondent":"高森税務課長","answer":"国が東日本防災関連で、全国の防災対策費として国がいろいろと予算化したものがございまして、その中に住民税が０.６兆円という形になってあります。これを幅広く、現在も防災対策経費をいろいろと使っておりますけれども、そこに重点的に配分していくというような趣旨です。","id":"exchange-011"},{"speaker":"石田（慎）委員","kind":"質問","question":"国のほうで１０年間の、区民税でいえば５００円のプラスだと思うのですが、その５００円をプラスにしたということだと思うのですね。それが１０年間上がるのですけれど、使うのは平成２３年度から２７年度の間に使われる防災に関してのものという、その認識でよろしいのか尋ねました。","respondent":"高森税務課長","answer":"委員ご指摘のとおり、その認識で。","id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"意見","question":"そうすると、おおよそ幾らが１０年間で防災費に充てられるかというのを計算して、平成２７年度までにそれを防災費として充てるのですよね。例えば年間で１億円ずつと見込んだ場合１０億円、その１０億円を下回ったり超えたりした場合というのは、区としてのお考えを説明を求めました。","respondent":"高森税務課長","answer":"確かに委員のご指摘のとおりです。これが大体おおよそ１０年間ということになりますので、総額としては１０億円ぐらいの経費と見込むわけですけれども、ご理解いただければと思います。","id":"exchange-013"},{"speaker":"石田（慎）委員","kind":"意見","question":"１点目は、今回のこのプラス５００円いただく財源の使う方向性というのは、どのようなものに使っていくというお考えがあるのか。そしてもう１点は、区民の皆さんにわかりやすいように説明をする必要があると思うのですが、その点のお考えを説明を求めました。","respondent":"本城企画財政課長","answer":"税務課長からもご説明がありましたように、トータル約１０億円ですが、平成２４年度の当初予算ベースだけでも約３６億円を使っております。個別にどの事業にと分けて１対１の対応関係があるわけではございませんが、そういう趣旨だということでご理解いただければと思います。","id":"exchange-014"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"一般財源に行くということで、その中で防災費に充てるというのはわかるのですが、区民として上げられた部分がそういったものにちゃんと使われているんだよという説明ができるように、努めてほしいと求めましたので、改めてもしあれば。","respondent":"本城企画財政課長","answer":"今ご指摘いただきましたように、新たに課されることになる税金の部分も含めて、どういう形で防災対策に区の財源が使われているかということを明確に示していく必要があると考えておりますので、そのような対応をしていきたいと思います。","id":"exchange-015"},{"speaker":"阿久津委員","kind":"質問","question":"附則第１６条の東日本大震災に係る雑損控除等の特例、私は税に詳しくないものですから、ここのところについてお伺いしたいと思うのですが。平成２２年に生じた損失と見なすということで、事業なのかわかりませんが、これはどういうことを想定されているのか説明を求めました。","respondent":"高森税務課長","answer":"家が滅失したということで、雑損控除１,４００万円ほど、そういう人が１件ございました。今後の見込みとか予測というのは実はつかない状況で、どんな状況であっても品川区としては整備していくことが大変重要なことだと認識しています。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１の行政手続法の適用除外項目の改正から、順番にお伺いします。確認なのですが、利用者にとっては増税にならないという確認でいいのか、そこが１点です。","respondent":"高森税務課長","answer":"滞納処分を行いますというふうな、２３区等も見て、検討していきたいと考えております。改正後はこれが３０万円になるという、区民税とした場合は３万円の増、税収増という形になるです。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"２点目のところがちょっと具体例がなく、すっと読むと、以前よりも説明をきちんとしていくという受けとめ方でいいのでしょうか。納税者の側が理由を提示しなくてはいけないとか、説明を今までよりもよくしていくという受けとめ方でいいのかどうか、ちょっとそこのところを。","respondent":"高森税務課長","answer":"もう簡単に異議申し立てを却下したりというのが現状のいわゆる滞納処分なのですが、それをもう一歩も二歩も踏み込んだ形で、異議申し立て等があった場合についても説明責任を果たしていくというふうな理解をいただければと思います。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"確認","question":"確認なのですが、区民というか納税者の側に不利な状況になるということではない、という受けとめ方でよろしいのか尋ねました。","respondent":"高森税務課長","answer":"そのとおりです。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"ここのところをお伺いしたいのですが、均等割のところが一律５００円上がるということで、増収分になるのかということを教えてください。先ほど一般財源に入るのだけれども、具体的に防災のために使わなくてはいけないという縛りはあるのでしょうか、ないのか尋ねました。","respondent":"高森税務課長、本城企画財政課長","answer":"増収額は、先ほど申し上げましたけれども２０万７,０００人ほどということで対象者を見込んですので。ですから、１０年で換算しますと１０億円です。 ただこれから充実する施策の中で、今回引き上げた趣旨を踏まえて確実に充実のために使っていくという、そういう趣旨でご理解いただければと思います。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"均等割で一律に都民税のほうも５００円、年間１,０００円ですよね。６、７に該当する品川の区民の方はどのぐらいいるのかお伺いしたいのですが、この辺についてのお考えを説明を求めました。","respondent":"高森税務課長","answer":"一説には２００人とか、そういう意味では、どのぐらいと言われてもお答えできないというのが実情です。非課税者は７万８,５７１人ということで、現状で今はそういう形でもって処理をしていますので、改めてということでの考えはございません。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"非課税の方もいらっしゃるし、そう大きな影響がないという受けとめ方なのでしょうか。本当に１円でも２円でも貴重なお金なので、新たな増税は所得の低い人に悪影響を与えると思うのですが、もう一度お願いします。","respondent":"高森税務課長","answer":"住民の方に負担していただきまして、防災施策に充てるという趣旨から、今回５００円の引き上げにつきまして提案をさせていただいている部分です。ご理解をいただきたいと思います。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"その辺について、これからなのかもしれないですけれど、コマーシャルももちろん区ではきちっとやっていかなければならない。その辺についてどのように取り組みをお考えになっておられるか、もし今の段階である程度わかっておられるならば、ちょっと説明を求めました。","respondent":"高森税務課長","answer":"今、所得税につきましては平成４９年までの２５年間ですから、２.１％ということで上乗せされる状況になってくるだろうと。ホームページ、年４回ほどなのですけれども、そういう中で周知については十分行っていきたいと考えています。","id":"exchange-023"},{"speaker":"須貝委員","kind":"意見","question":"どこにどう使われているのかと、本当なのという話になると思うので、くれぐれもその辺よろしくご配慮くださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"庶民にばかり増税を求めるというやり方は、共産党としては改めるべきであると思っています。特に低所得者や被災者にも重い負担になる、庶民だけへの増税の求め方はやめるべきだと考えていますので、この点は反対をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-03","title":"本定例会の一般質問に係る所管質問ですが、本定例会の一般質問中、総務委員会にかかわる項目","agenda":"本定例会の一般質問に係る所管質問ですが、本定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今のみやこ荘の跡地の広さを、面積を教えていただけたらと思います。","respondent":"柏原行財政改革担当課長","answer":"こちらの土地の面積は、３,３５７.２５平方メートルです。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区が示されましたが、今後の議会に対する報告とか審議というのはどういう形でやっていかれる予定なのか、これだけちょっと。金額的にも、先ほど３,３００平方メートルとありましたけれど、議会側の審議としての方向性を教えてほしいと求めました。","respondent":"日下部企画部長","answer":"今後いろいろ調整していきたいと考えていますが、区としても最終的な判断は出せませんので、基本的にはその段階で議会のほうにご報告すると。それはまた適宜、議会にもご報告をさせていただきたいと、このように考えております。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579213?Template=document&Id=1916#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":22256,"voices":104}},{"id":"h24-20120626-6","meetingId":"h24-cm06","date":"2012年6月26日","dateIso":"2012-06-26","committee":"区民委員会","time":"午前１０時００分～午前１１時０６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"の品川第一区民集会所の休館","agenda":"の品川第一区民集会所の休館","exchanges":[{"speaker":"井上副委員長","kind":"質問","question":"その辺はどういうふうに、ここにとまっていたりあると思うんですけれども、そこら辺はどのような配慮をなさっているんか尋ねました。","respondent":"久保田地域活動課長","answer":"駐輪場につきましては、今回の工事の対象にはなってございません。外壁の改修は一部の改修ですので、その辺は充分配慮しながら、駐輪場は工事期間中も使えるような形で考えております。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"今、区民集会所の改修は耐震がメインになってくると思うんですが、ほかの地域センターや集会所というのはどういう状況になっているのか。ああいった計画もまだあるのかどうなのかということを、計画というか、そういったことが論議されているのかということをお聞きしたい。","respondent":"久保田地域活動課長","answer":"平成２４年度に耐震改修を行いますのが、併設になりますけれども、品川第一地区の地域センタービルで行います。区単独ではできませんので、検討というところが、課題としてはあるというものです。","id":"exchange-002"}]},{"id":"topic-02","title":"の第６回品川区・ポートランド市青少年スポーツ交流事業","agenda":"の第６回品川区・ポートランド市青少年スポーツ交流事業","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"ホームステイの状況で、日本のほうもそうなんですけれども、比較的多く応募というか、手を挙げる方がいらっしゃる、その辺の状況ですね。これは６回目なので、今まで５回やってきて、教えてほしいと求めました。","respondent":"今井協働・国際担当課長","answer":"なお、原則として品川区少年野球連盟が、ホストファミリーとして受け入れる家庭をなるべく派遣するというお考えで公募したと聞いております。","id":"exchange-003"},{"speaker":"武内委員","kind":"質問","question":"そういうエピソードが聞けたというのはよかったと思いますけれども、ホストファミリーの応募で、品川区国際友好協会で働いている方たちも積極的に手を挙げているらしい、そんな話もちょっと聞くんですけれども、今回その辺はどうだったんか尋ねました。","respondent":"今井協働・国際担当課長","answer":"今回、これまで国際交流事業に携わってきた区内在住の職員も含めて、広く呼びかけたいと聞いております。ただ、品川区国際友好協会の職員が今回受け入れのホストになったかというのは、申しわけありません、存じ上げません。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問","question":"派遣選手なんですけれども、２２人、例えば、男子の野球であれば、少年野球連盟がその選手たちに声をかけるのか、それとも逆にこっちから僕、行きたいですという自薦で行くのか、他薦で行くのか、そのあたりのバランスはどうなっているんですか、女子のバスケットボールも含めて。","respondent":"今井協働・国際担当課長","answer":"区立中学校の指導主事にも入っていただきまして検討した結果、地区の配分を考えながら、野球連盟のほうで選出してきたと聞いております。これは学校の部会を通じて、バスケットボール部がある区立中学校の生徒を中心に広く声をかけて公募したという状況だと聞いております。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"私はこの事業自体は認めているんですけれども、昨今の経済状況の中で、やはりずっと続けられているというのもあるんですけれども、見直しということは行政サイドで出ているんか尋ねました。","respondent":"今井協働・国際担当課長","answer":"今回は男子が１種目、女子１種目にしていこうということが１つ、種目数の削減ということです。この２点が大きく削減した部分です。","id":"exchange-006"},{"speaker":"藤原委員","kind":"意見","question":"それと、今日の資料の中で、「大森貝塚を発見したモース博士の誕生地であるという縁」というのがあるんですけれども、その点から交流が始まったというけれども、この辺についてちょっと説明していただけますかとの意見を述べました。","respondent":"今井協働・国際担当課長","answer":"品川を一番ＰＲできるものというところで、大森貝塚のモース博士というところで、一番最初の縁が築かれたと聞いております。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"品川の大森貝塚だったのに、どういうわけか大森貝塚が大田区にももう一つできていて、大森貝塚が二つになってしまったんですね。この辺に関して、品川区としてはっきりした見解を持っているのか、説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"私からお答えしますが、もう一つは、碑は大森貝墟になっています。大きなビルの外、そこにも一つあって、大森貝塚という品川区の公園にも大森貝塚があるという形になっています。","id":"exchange-008"},{"speaker":"藤原委員","kind":"意見","question":"大事なことなので、今、課長の答弁でもう自信を持てたんですが、いわゆる本家というか、元祖というか、大森貝塚は品川のものが本当なんだという気持ちでこれからずっと生きていていいんですよねとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"物の本によれば、そう書いてあるので間違いありません。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"質問は、こっちでやる試合のチーム編成というのは、同じような考え方でいいんでしょうか。その品川のチーム編成の仕方、声のかけ方というのは、派遣するときと同じような声のかけ方なのか、そこだけちょっと確認したいんです。","respondent":"今井協働・国際担当課長","answer":"先ほど選手の選出でもご説明しましたとおり、少年野球連盟の方が相談してチーム編成を考えていると、野球では聞いております。同じように派遣する代表チーム同士の試合が１試合ありますが、その決定も、いろいろなチームと対戦できるように決定していくと聞いております。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問・要望","question":"６回目ということで、国際交流はどういうメリットがあるのかというのを、参加されない一般区民の方にしっかり打ち出さなければいけないと思います。もし、答弁があればお願いします。","respondent":"今井協働・国際担当課長","answer":"それと広報にも貝塚の遺跡庭園がありますということもきちんと周知していく予定です。天王洲公園野球場も大変立派な球場だと考えていますので、この機会を通じてぜひアメリカに持ち帰っていただければと考えております。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"国際的な交流はすごく大事なところだと思います。受け入れ先としてどういったご家庭が多いのか、特徴的なところがあれば、説明を求めました。","respondent":"今井協働・国際担当課長","answer":"ホストファミリーの説明会は今後実施いたしますが、食事は豪勢なものを出さなければいけないんですか、日本の方はご心配があります。中には英語にご堪能で、ぜひ自分でも英語で交流したいのでというところで、応募があると聞いております。","id":"exchange-012"},{"speaker":"井上副委員長","kind":"質問・要望","question":"派遣のほうで、選手の数が２２名ということなんですけれども、全体の選手団としては、どういう構成で、何人になるのか教えていただきたいのと、あと、スポーツ交流事業は何年に一遍の事業として行っているんか尋ねました。","respondent":"今井協働・国際担当課長","answer":"今予定しておりますスポーツ交流事業の派遣人数ですが、全体で３２名の派遣を予定しております。周年事業とか、それぞれの状況に応じまして、今までは４年もしくは５年に１度この事業を進めているところです。","id":"exchange-013"},{"speaker":"井上副委員長","kind":"質問","question":"予算的なものが、先ほどの１,８００万円の中に一緒に入っているのか、その辺を説明を求めました。","respondent":"今井協働・国際担当課長","answer":"２点目、先ほど申し上げました品川区国際友好協会の予算額につきましては、すべて品川区国際友好協会の補助金の金額です。実行委員会の中には、そういう所管も入りまして、区と一緒に事業を進めているところです。","id":"exchange-014"}]},{"id":"topic-03","title":"の３、行政視察","agenda":"の３、行政視察","exchanges":[{"speaker":"武内委員","kind":"意見","question":"商店街の活性化、長野県佐久市に岩村田本町商店街、平成２３年度にあしたのまち・くらしづくり活動賞の内閣総理大臣賞をとった商店街があります。平成１９年にも佐久市に行っていますけれども、ほかとの兼ね合いもあると思いますけれども、一つ参考にしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"山内委員","kind":"質問・要望","question":"非常に観光客が来ているということで、品川区に取り入れることが可能ではないかという考えの中から、視察をしたらどうかということです。東京２３区では千代田区なんかがもう既に行っている実績があるということで、もし、ちょっと参考にしていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"本多委員","kind":"意見","question":"我が党が観光行政についてというのを出させていただいた根底には、品川区をどうやって売り込むか、ＰＲしていくかということに着眼しました。品川区もどう売り込もうかということで、山内委員が述べられたということなので、そんな意見を述べさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"意見","question":"若者の就労支援というところで、一番近くて、足立区でもやっているんですけれども、足立区もいいかなと思うんですけれども、あともう一個、群馬県にも、ジョブカフェというのをやって、利用率も、就労に結びつく、相当率が上がっているということで、見てみたいなと感じていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"井上副委員長","kind":"質問・要望","question":"ほかの地域で、これは都市部でないとだめなので、品川区としてはそういうところと同じような部分をちょっと検討していただきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"藤原委員","kind":"確認","question":"今、副委員長から都市部というお話が出たんですけれども、まず一つ、委員長、副委員長に確認したいんですけれども、改めて行政視察の目的というのは、どういうふうに考えているんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"井上副委員長","kind":"意見","question":"そういうことも賛同いただければ、そういう方法もあるんじゃないかと、それは委員会での考え方だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問・要望","question":"品川区の議会として視察に行くわけですから、さっき自民党が品川区でどう活かしていくかというのは、ちょっと言いましたよね。ですから、品川区にどう活かすかということで、人口規模とか、都市とか、そこのベースだけは考えていただきたいと思っているのが１点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"武内委員","kind":"意見","question":"人口も違うけれども、２３区でも、品川区と全く同じような風土なんてないわけです。視察が有効になってくると思うので、今の意見とあわせて、そういう点もぜひ正副委員長で検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"武内委員","kind":"意見","question":"それで、あとはこれを見たいというのをまず決めていただいた中で、それが合う日程があると思うんです。それでお決めいただければいいのではないか、私は特にどっちにというあれではないのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"山内委員","kind":"質問","question":"第１希望を２３日からにして、相手先の都合もありますから、第２希望で２２日、第３希望で２４日という感じにしておいたらいいんじゃないですか。それで平日。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"藤原委員","kind":"提案","question":"視察先なんですけれども、観光と商店街、両方あわせ持った京都を提案します。新幹線で、一応提案だけ、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-04","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"山内委員","kind":"意見","question":"これはどこにするんだろう、アピールをするというか、そういったことはないのか。何かハンドボールばっかりで、その辺はどうなんでしょう、別にハンドボールが悪いというわけではないんですけれどもとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"私どもの品川区では、正式競技はハンドボールなんですけれども、デモンストレーションとして、グラウンドゴルフを行います。地域の皆さんにも実際に喜んで、待ちに待っているところでもありますし、何とかこれを品川区で発展させていきたいと考えています。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118408?Template=document&Id=2640#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":18695,"voices":83}},{"id":"h24-20120626-7","meetingId":"h24-cm06","date":"2012年6月26日","dateIso":"2012-06-26","committee":"厚生委員会","time":"午前１０時００分～午後０時１１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"石田（秀）委員","kind":"提案","question":"もし弁護士とそういう話だったら、なぜそういう提案をしたのかというのをまず区側の立場として教えていただきたいというのが１つ。ここら辺を弁護士とどう話して和解を受け入れたのか、弁護士とだって感覚が合って、そこら辺のところをぜひ教えてほしいと求めました。","respondent":"白鳥高齢者いきがい課長","answer":"今後の影響については、これから２年後にまたこの借上住宅の更新時期がまいります。やはり、こちらにつきましてはさまざまな社会情勢もかんがみながら、これから判断していきたいと思っているところです。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"提案","question":"１０年６万５,０００円とこちらが提案したのですかという質問から入って、それは例えば、それは可能なわけですよね。どういう提案をして、２年後に向かってどういう家賃のことを下げていくことができるのか、現実との意見を述べました。","respondent":"白鳥高齢者いきがい課長、早津健康福祉事業部長","answer":"まず、やはり、さまざまな調査結果のもとで品川区といたしましても家主にはこの月額にしていただきたいということでお願いをしたところであります。やはり、当初の２０年間を引き続き… まず、ご提案の２年あるいは５年というのでは、２０年の長さを短縮するので１０年という提案をさせていただきました。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"提案","question":"７万円と６万５,０００円で、５,０００円の乖離があるわけですから、そこの部分をどういうふうにしていくおつもりでいらっしゃるのか。","respondent":"早津健康福祉事業部長","answer":"まず、需要もあるということを踏まえる中で、一定の継続が必要であろうという判断の中でこのようにさせていただいたものです。例えば、２年の中では前回提案したのを改めて蒸し返すというのは、やはり経済状況次第ということになろうかと考えています。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう１回その考え方、そこだけはもう一度答弁をいただきたいのと、１０年契約をしたその１０年後の次の契約というのはどういうふうになっているの。１０年後の方針については区が何かを言って受け入れられませんでしたというならまだしも、１０年後のね、そこは明確に教えていただきたい。","respondent":"早津健康福祉事業部長","answer":"その場合には、契約書上に１０年後どうするかということの記載はございません。それから、もう１点の、２年間のことにつきましては、社会経済情勢のみではなく、建物の老朽化のぐあい等、注視していきたいと考えています。","id":"exchange-004"},{"speaker":"塚本委員","kind":"質問・要望","question":"高齢者住宅のそもそものオーナーと高齢者の間に需要があって、その一方で貸そうというオーナーがいるわけですけれども、その間に区が入ってこういう事業をやっているそもそもの意味というか、ねらいというか、目的というか、そこをまず確認させていただきたいのですけれども。","respondent":"白鳥高齢者いきがい課長","answer":"ただいまのご質問ですけれども、そもそもこの高齢者住宅の必要性でありますけれども、住宅に困窮する高齢者に住宅を提供するという大前提があります。その生活の安定と福祉の増進を図るということがこの高齢者住宅を設置した大前提の目的です。","id":"exchange-005"},{"speaker":"塚本委員","kind":"意見","question":"では、もうちょっと詳しく言うと、借上型という形でオーナーがいらっしゃるところに、間に区が入って仲介業みたいなことを、仲介業と言ったらちょっとおかしいですけれども、間に入ってこの事業を進める意味ですとの意見を述べました。","respondent":"山田副区長","answer":"当初、なぜ高齢者住宅を区が借り上げまでして実施をする施策としたかと申しますと。そうした方々の状態も含めてご理解をいただけるいわゆる家主、その方たちと連携をしながら高齢者住宅の提供を図っていくということで進めたものです。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"これは何というんですか、矛盾というんですか、そういったところをちょっとお伺いしたいのですけれども。","respondent":"白鳥高齢者いきがい課長、早津健康福祉事業部長","answer":"１点目のほうの近傍家賃との差ですけれども、先ほど来からお話をしています２年ごとに双方協議の上の近傍家賃を参考にした改定ということは、この住宅政策を進めているところです。 その結果、それは当初提案した６万５,０００円から見ますと少し高めが提案されたということになろうかと考えています。経過としてはそういうことだと思います。","id":"exchange-007"},{"speaker":"塚本委員","kind":"意見","question":"それはそういう措置に訴えるかどうかというのは、また安心した価格で提供するということを考えたときに、そこの原点に返ってくるんですね。必要によっては本当に強行的な措置もとっていく必要があるのではないかと思いますので、その点、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"そこをちょっと特徴を説明していただきたいのと、今後、どう事業を進めていこうと思っているのか、その概要も改めて伺いたいと思います。専決処分を行ったことの報告ではありますけれども、議会に説明するタイミングについてはどんなふうにお考えなのか、考え方を伺いたいと思います。","respondent":"早津健康福祉事業部長、白鳥高齢者いきがい課長、渡辺委員長","answer":"その場合にはどういう対応ですが、打ち切るということが俎上に乗っているわけではありませんので、可能性としての話をしました。その後については… こちらについては東京都の宅地建物の取引業協会、宅建品川支部の協力によりまして住宅をあっせんして助成金を交付しているものです。この高齢者住宅… 施策自体の今後の展開と、あと、議会の説明のタイミングと、あと２点かと思いますが。当面、現状で推移させていきたいと考えています。","id":"exchange-009"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"その点をどうお考えなのか伺いたい。やはり、介護つきのほうも区民が利用できる料金設定に進めていくということが必要だと思いますけれども、最後にこの点を伺いたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"現在、このシルバーピア型のものについては平成５年ということで、この平成３年から５年のこの約２年間の中で３棟を建設したところです。それから高齢者住宅のあり方をこれから検討しながらも、必要性につきましては今後の検討課題とさせていただきたいと考えています。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういうストックを活用して区内に住み続けていただきたいというのが私の記憶で、そういう形の中で高齢者に対する需要にも対応していく。まだ今後の検討課題という話は大分違うような気がするのだけれども、私の間違いだったかどうか、わかるように説明してほしいと思う。","respondent":"早津健康福祉事業部長","answer":"私が先ほどお答えしましたように大井林町がオープンしたということで、現状しばらくはこのままで行きたい。お話にもありましたように、あっせん制度等を活用する中で、高齢者の住宅対策としていきたいと考えています。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"意見","question":"空き住戸には丸々１棟空いたり、１０戸のうち５戸空いたり、いろいろなことのパターンがいっぱいあるわけでしょう。品川区内に２万幾つもあって、これから考えていくではなくて、そうではないみたいだから聞いているわけですとの意見を述べました。","respondent":"早津健康福祉事業部長","answer":"空いている住戸の活用については今後検討をさせていただきたいと思います。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"私も今のいわゆる２万戸という空き家、どうもそうではないというご答弁なので、そこをまずはっきり伺いたいと思います。この部署でわかりませんということであれば、それで結構ですけれども、でも、それは余りにもちょっと縦割りかなと。","respondent":"白鳥高齢者いきがい課長","answer":"すぐにでも、きのうの委員会の中でも説明させていただきましたように、すぐにでも速やかに入っていただくような対応をしています。１４７万６,０００円以下の方につきましては、３万円で使用料をお支払いをしていただければ入居いただけるという内容です。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"この再利用とかっていう発想ってできないのですか。今の２万戸というストックとこれからはストックが出ていくという、そのストックの活用の仕方は高齢者の住宅施策として何か考えがありますか尋ねました。","respondent":"早津健康福祉事業部長","answer":"それについては住宅政策全体の中でどのように活用するかということを考えていく必要があろうかと思うのですが、適正な区としての支出額をどういうふうに考えたらいいかということもにらみ合わせながら、空き家全体の活用について検討していきたいと考えています。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"６万５,０００円になっているときの相差と、７万円とか７万２,０００円のときの相差って違うではないですか。そのオーナーを育てたり、つくるために、次の宅建とかにご協力をいただいてやろうとしているわけではないか尋ねました。","respondent":"早津健康福祉事業部長","answer":"これまでもあっせん制度の中では大家たちの理解を得ながら高齢者の方のお住まいを提供するように努めてきたところです。それから、そのようなことのないように今後も近傍家賃を調べた上で、近傍家賃に近いような形での契約を進めていきたいというふうには思っております。","id":"exchange-015"}]},{"id":"topic-02","title":"平成２３年度品川区介護保険制度の運営状況","agenda":"平成２３年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"これはなぜなのかということと、どう評価されていらっしゃるのか伺いたいと思います。あわせて伺いますけれども、評価も含めて伺いたいのと、それにどういう対応をされているのか伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"区の考え方としましては、まず一つは当然のことながら、マニュアルに沿って実施をしている。そういった中で、サービスが保険料が支払われなくて受けられないという方の数値については基本的にはいらっしゃらないと認識をしています。","id":"exchange-016"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"平成１９年が９８３人、平成２４年３月が９５０人なのですけれども、これが少なくなっているのはどういう理由なのか、伺いたいと思います。何人いらっしゃるのか、状況を伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"その方が一番多いのは東京都内ですね、こちらのほうが約４割。それから神奈川県のほうが３割ぐらいというところで利用しています。","id":"exchange-017"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"２０万円、３０万円する料金のが特養ホームよりも多い給付だというのはどう考えているのか、そこを伺いたいと思います。合わせて、特養ホームと有料老人ホームと、介護報酬についてなんですけれども、１ベッドあたり月額幾らなのか伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"こういった有料とバランスを、有料のほうは区の中で実施をしていくというところよりは、民間活力という中でつくられてきております。そういった意味では特養のほうがこの１割の負担は高くなっているという状況です。","id":"exchange-018"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今の運営状況をいろいろ伺ったわけですけれども、払い切れない、選びようがないという実態をぜひ知っていただきたい。選択できると言いますが、そういう実態ではないことはどう考えているのか、改めて伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"先ほど来説明していますように、そういったところに入りながら、生活をされていくということを区のほうは認識をしています。区のほうも現時点では手を挙げさせていただいたという状況です。","id":"exchange-019"}]},{"id":"topic-03","title":"立会川浸水対策事業における「月見橋の家」の仮移転","agenda":"立会川浸水対策事業における「月見橋の家」の仮移転","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"この１枚目のページの今後の予定の下に鉛の土壌汚染が判明したことから、仮移転施設建設前に浄化対策工事を実施と。ちょっと、ここを少し詳しくお話をほしいと求めました。","respondent":"原高齢者福祉課長","answer":"この６９０mgというものが数値から見ると、約４倍強ですけれども、これから汚染の除去ということで実施をしていくところです。そういった意味では５cmから５５cmというところでそういったものが出てきたところですけれども、除染をするというところで聞いているところです。","id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"月見橋の家の移転ということで利用されている方々、その家族への説明と、あと、何かご要望とかが上がっているのかどうか、状況を伺いたいと思います。この建設費というのですか、それともどこか別の部隊が持つのか、そこの関係をご説明ほしいと求めました。","respondent":"原高齢者福祉課長","answer":"この間、私も含めて関係課、所管あるいは東京都の事業ですので、東京都の出席のもと、まずは１回、家族への説明を行っております。７月にも月見橋の家の利用者家族ということで予定をしています。","id":"exchange-021"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"認知症ケアの学会の評議員の方がやっていらっしゃるような、そういうのをわかっていらっしゃるような施設がグループホームとしてはいいと思います。これが旭川にあるので、ここだけでなくていいのですが、検討してもらえればと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"若林委員","kind":"質問","question":"所管事務にはなりませんですけれども、発達障害とか、それも含めたいわゆる自立就労支援ですかね。そこら辺を中心に、具体的に行くところは今後行くところがあれば、お出しするという理解でいいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"若林委員","kind":"提案","question":"７人、８人全員でと言っておりますけれども、毎年あります。アイデアとしてというのですか、そういう２班に分かれてというやり方も、ご提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"向委員","kind":"質問","question":"北海道にも見に行くような施設が１つあるわよと伺ったので、それでもしそういったところでまとめて行けるのであれば、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"意見","question":"今、若林委員からも２班という話もあった。だから、このことだけを先行するというわけにも行かないだろうから、これも合わせて正副に私はお任せをしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"財源確保について国に要望しているということですけれども、どんなふうに要望されているのか、その内容について。何を検討されるのか、どんな方向なのか、そこの中身を少し詳しくご説明ほしいと求めました。","respondent":"伊津野品川区保健所保健予防課長","answer":"制度改正に当たっては、地方自治体や医療機関が無理なく対応できるよう十分な準備期間をとり、地方に一時的な事務負担が生じないようにすること。この４月に全国市長会を通しての要望としてまとめられ、同じ内容で進められております。","id":"exchange-027"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"既に東京２３区でも独自に３ワクチンへの助成を行っておりまして、自己負担なく進めている自治体もあります。改めて品川でも自己負担をなくすようにしていただきたいと思うのですけれども、そこについての検討は今どういう状況なのか伺いたいと思います。","respondent":"伊津野品川区保健所保健予防課長","answer":"この一般質問の内容につきましては、現在任意接種で行っている３ワクチンが定期化された場合の財源措置であります。現在の任意接種についての区の自己負担のあり方につきましては、従来どおり半額程度の負担ということで進めさせていただきたいと考えています。","id":"exchange-028"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今回、そして財源確保も求めることは大事なことだと思いますけれども、区独自でも自己負担なく接種が受けられるようにすべきではないかと。自己負担なく区民が予防接種を受けられるようにすべきではないかと、まずはこの３ワクチンに限ってですけれども、改めて伺いたいと思います。","respondent":"伊津野品川区保健所保健予防課長","answer":"まだ国のほうでも具体的にどういうふうになるかというのが示されておりませんが、これまでの流れですと、定期接種化された場合は自己負担を徴収するというのはなかなか難しい問題であると考えております。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594819?Template=document&Id=3328#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":38258,"voices":103}},{"id":"h24-20120626-8","meetingId":"h24-cm06","date":"2012年6月26日","dateIso":"2012-06-26","committee":"建設委員会","time":"午前１０時００分～午後１時４２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"の３、行政視察","agenda":"の３、行政視察","exchanges":[{"speaker":"浅野委員","kind":"意見","question":"栃木県の足利市のスマートグリッド通信インターフェイス導入事業ということで、この二つのうち、どちらかに行ければなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私も、地産地消という考え方でかなり取り組みを進めている長野県の飯田市、そこが一番できれば行きたいなと思っているところです。それ以外のところでも、高知県の梼原町とかいろいろあると思うんですけど、できれば飯田市に行けたらいいなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"須藤委員","kind":"意見","question":"都市はどこだと決めていませんので、そのハード、ソフトでいろいろ地域のコミュニティを見ていきたい。エネルギー云々というのは、それよりも今我々は区民のために何ができるんだろうということを考えて、所管事務調査に対応してもらえればと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"木村委員","kind":"意見","question":"３月１１日以来のことで、もしできましたら、そういうところを探してほしいと求めました。今までの、過去のあれを見ますと、どちらかというと西日本がすごく多いので、できたら上のほうがいいかなという感じもしますがとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"吉田委員","kind":"意見","question":"ちょっと聞きかじったんですが、和歌山県がそういうのがあるんではないかというのがありました。その辺がいいかなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"須藤委員","kind":"質問","question":"火曜日スタートのような形で、１日置いて準備してもらって、こういうような形をとらせてもらっているんです。ですから、２９の月曜日じゃなくて、逆に３０日火曜日あたりのスタートというので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"立会川浸水対策事業における区施設の仮移転用地取得","agenda":"立会川浸水対策事業における区施設の仮移転用地取得","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"４年間という日程的なものがあるんだろうけど、できるだけ前倒しにできるものはやってもらって、早く完成させるようにというお願いです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"縦横何ｍぐらいあるのか教えていただきたいのと、あと５ｍの管が２本というのは、こういうふうな形で縦に２本並ぶということなんでしょうか。その勝島ポンプ所が完成をして、この今回の工事が完成する前にそれは可能なのか、そこら辺のところをちょっとお聞かせほしいと求めました。","respondent":"武藤河川下水道課長","answer":"５ｍのものを２本という形で、立会川の直下では５ｍを縦に２本並べるような形で工事を進めていくということで聞いております。現時点は、また先ほどご報告いたしました浜川雨水排水管といったものを整備する予定をしておりまして、流せるということを聞いております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この図に書いてあるのは１本だけが書かれているので、縦にというところの下にまた５ｍというのが来るということになるんでしょうか。そこのところを勝島ポンプ所できれいにして海に流すというような、そこら辺の仕組みというのはどうなっているのかということを説明を求めました。","respondent":"武藤河川下水道課長","answer":"Ａ３の資料の図で見ていただくとわかると思うんですけど、今ご説明した立会川の雨水放流管、あと図には示していないんですけれども。その貯めたものは、できる限り外海にある京浜運河の水質をよくするといったことも、このポンプ所の機能としては検討されているものです。","id":"exchange-009"},{"speaker":"沢田委員","kind":"確認","question":"土壌汚染のことでお伺いしたいんですけれども、持ち主の東京電力が負担するのかという確認をしたいのと、ほとんどこういうことはなくなるのかということを教えてほしいと求めました。","respondent":"武藤河川下水道課長","answer":"地歴という、どういった形で使われていたという調査を実施しておりますけれども、詳細には鉛による汚染の原因というものは特定できませんでした。今回雨天時に立会川に流れる洪水の大部分、現在のように立会川に流れるような状況はかなり改善されるというふうに認識しております。","id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"これは普通公園にする、何かあったところを公園にするときというのは、基本的にはあまりそこまで調査というのはしないものなんですか。ほかの場所とかでも、どういうふうな状況なんか尋ねました。","respondent":"多並公園課長","answer":"公園の取得の際の土壌汚染の考え方ですが、取得する際、もちろん法律に従いながら調査等をして購入等しています。今回土地所有者である、東京電力が所有者ですが、土地所有者が法令の中で自主調査という形の扱いで調査をされたということで判明した内容です。","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"昭和４９年ということで、そういうのも特にやっていなかったので、今回わかったということか尋ねました。","respondent":"武藤河川下水道課長","answer":"用地の取得の調査の経緯につきましては、先ほど用地担当課長がお答えさせていただいたとおりでございまして、土壌汚染の調査をしたというものです。","id":"exchange-012"}]},{"id":"topic-03","title":"北品川五丁目付近合流改善施設整備工事","agenda":"北品川五丁目付近合流改善施設整備工事","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"貯留池というのはどういう仕組みになっているのか教えていただきたいのと、今までは下水がそのまま目黒川に流れていたということなんでしょうか。そういうところでは、まだまだどれぐらい残されているのか、そこら辺の実態というのも教えてほしいと求めました。","respondent":"武藤河川下水道課長","answer":"つまり汚水と雨水が１本の管で流れるという方式ですけれども、かなり雨が強くなってきた場合には、一部の雨は川に放流されることになります。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その貯留池というのは、今回初めてできるということなんでしょうか。どういうふうにして、そういうのはどういうふうにして浄化して、そういう仕組みというのはどうなっているのかもちょっと説明を求めました。","respondent":"武藤河川下水道課長","answer":"目黒川沿いでこのような形で整備するのは初めての施設になっております。降雨後、ずっとその汚水管をたどって水再生センターまで送られ、そこで処理して海だとか運河に放流されるということになります。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"品川区の計画としてこういう形で工事されると思うんですけれども、上流のほうの対策ですね。目黒区とか上流は世田谷区ですか、そういうところから流れてくるのが実際あるのかなと思うと、されつつあるのか教えていただきたい。","respondent":"武藤河川下水道課長","answer":"今、上流の目黒区でも同様な貯留池を整備計画して、その調整に入っているというふうに聞いております。いわゆる宅地で貯めたりとか、宅地で浸透させたり、そういった流域全体の取り組みを推進しているというふうに聞いております。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"品川区は最後ですから、私どもは権利があるんではないかなという気がしてならないので、その点はぜひともお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"須藤委員","kind":"質問","question":"６００mm、９００mmとなっている違いはなぜなのかというのが１点と、どういうふうな手順で持っていかれるのか教えてください。現状あるのかどうか。","respondent":"武藤河川下水道課長、溝口都市開発課長","answer":"質問の２点目です。再開発組合のほうの施行ですけれども、これは今後、本工事と調整しながら本工事の点線の部分につきましては、別途、後に工事する予定です。 組合施工分の工事についてご説明します。延長としては約２８３ｍ、施工延長を予定しております。","id":"exchange-017"}]},{"id":"topic-04","title":"水とみどりの基本計画・行動計画の策定","agenda":"水とみどりの基本計画・行動計画の策定","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この２１.２％というのは、２３区の中でも低いほうなんじゃないかと思うんですけど、２３区の中での位置というのはどれぐらいになるんでしょうか。この目標というのは、もうちょっと高くすべきなんじゃないかなと思うんですけど、そこの考え方についても説明を求めました。","respondent":"多並公園課長","answer":"３点のご質問にお答えいたします。今後の推進計画と区として進めているものを考えまして、それを目標として掲げて進めていきたい、そのように整理したものです。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこら辺のところをもうちょっと増やすべきなのではないかという考え方についてはいかがでしょうかということと、区が掲げた１.４％増の３３.２haというのを、具体的にどういう形で実現をさせていくのかというところがもうちょっと見えるような形でご説明いただけたらと思います。","respondent":"多並公園課長、松代防災まちづくり事業部長","answer":"ここに示していますような３.９haというのは、または再開発の中で整備される公園のリストを整理して、今後の見込みの中で考えたものです。行動計画かなにかでも新しいみどりの施策につきましては検討しながら、進めていく方向… 密集市街地で公園として今買えるのは２,０００m2、１,０００m2、もしくはもう少し低いものです。果たしてこの１０年間でどれだけの数字ができるかというところで、かつ努力をする目標として今回このような数字を挙げたものです。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほんとうにそれの３分の１ぐらいということでは、公園は防災事業と開発ということで、私はもうちょっと広げていただきたいという要望があります。そういうところはどうなのかということと、町会の中で、一つも公園がないというところも残されているわけですよね。","respondent":"松代防災まちづくり事業部長","answer":"公園の設置の考え方ですけれども、区の考えも同様ですが、あることが望ましいというような一つの指標があります。そういった意味では、公園という手法であるとすれば、まず最優先に取り組んでいきたいというふうに思っているところです。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"中延の地域で言えば、中延四丁目は木密地域として指定されていないんですけど、そこの町会には多分火災危険度が４ぐらいになっていると思うんですね。そういうところがあると思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは手法としてなんですけどね。どちらにしても公園が増えればいいわけなんですけど、そういう考え方で進めていただきたいと思うんですが、いかがか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"では取り組まなければいけない防災という区民の命を守る意味の観点からいえば、やはりその地区を最優先にしていく、そういう考えでおります。そういったところから、少しでもこのみどり、総論でのみどりが増えていくような取り組みを今後進めてまいります。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区のほうにこれをぜひ購入して公園をつくってほしいという要望というのは、さらに公園を増やすためにも補助金制度を求めていくというところで、最後に一言お願いします。","respondent":"松代防災まちづくり事業部長","answer":"財源構成は区にとっては非常に重要な施策を実施するに当たっては重要な視点です。一定の面積要件がありますので、そういった仕組みづくりということを以前から要望していますし、今後も要望してまいります。","id":"exchange-023"},{"speaker":"須藤委員","kind":"質問","question":"緑被率の増加が１.２％、水のほうは１.２％という数字になってきて、内陸のほうがあるんだよね。逆にそこから浸水をしてくるよという逆の面も見えてくるので、そのあたりの対応はどういうふうに考えていらっしゃるのか、２点お伺いします。","respondent":"多並公園課長、武藤河川下水道課長","answer":"そこにつきましては、今も保存樹、保存樹林という形で保全という形でご支援しています。行動計画の中でも民間との協働という形で検討していくということになってありますので、これも今後研究課題として考えていきたいと考えております。 先ほど報告でも説明させていただきましたが、東京都はそれを中心に今、整備を進めております。あわせて、今国や都では季候変動に伴うさまざまなそういった変化といったものの検討に入っているというふうに聞いております。","id":"exchange-024"},{"speaker":"須藤委員","kind":"意見","question":"六年前に立会川があふれたときに、今５０mm対応というような話も、少ししかできないんじゃないかというのがまちの人たちの形なんです。やはり、逆の面ということが出てくるので、それに対する危険性というものも考えておいていただければということでお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"パブリックコメントについてお伺いしたいんですけど、２０件で７名の方というのは、ちょっと少ないと思うんですが、どのような経緯かちょっとその辺を説明を求めました。","respondent":"多並公園課長","answer":"パブリックコメントについてのお問い合わせにお答えいたします。先ほどの１カ月の期間につきまして、結果としては７名、２０件の方のご意見をいただいたものです。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"ちらっとお聞きすると、やっぱり使う方は区民の皆さんなので、そういうもうちょっと幅広くご意見を聞けたらいいなと。これから何かご意見等を聞くような機会があったらいいなと思うんですが、その辺はどうなんか尋ねました。","respondent":"多並公園課長","answer":"勝島運河倶楽部であったり、水とみどりにかかわる活動をされている区民の方々との意見交換会というのを７月と８月、計２回実施しています。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"今７月、８月に意見交換会ということですので、たくさん意見を取り入れていただいて、練ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"浅野委員","kind":"質問","question":"概要版と本冊というんでしょうか、どういう形で発行されるのかということを一つお伺いしたいのと、四角の中が空欄になっていますね。これはものが入らないんか尋ねました。","respondent":"多並公園課長","answer":"５ページです。今後の予定につきましては、内容につきましては、策定されたということは区報でもお知らせするような形で考えてあります。","id":"exchange-029"},{"speaker":"浅野委員","kind":"質問","question":"みどり率２５％、平成３３年度、実際に友禅流しというのはいつぐらいまであったのかなというのをちょっと参考までに教えてほしいと求めました。５７ページの真ん中に主な事業というのがありまして、これはどこら辺のことを言われているのかが気になったので教えてほしいと求めました。","respondent":"多並公園課長、武藤河川下水道課長、藤田都市計画課長","answer":"これにつきましては、昭和５９年に緑の基本構想を策定し、今後もそのようなことで進めていきたいと考えているという方向性を示したものです。… そう遠くはない昔だと認識しているということと、昭和の初期から高度成長期にかけて、やはりそれ以前だというふうに認識しています。ということで… 目黒区もぜひこの辺については取り組みたいということでお話をいただいていますので、この計画の中に盛り込んだというふうに聞いてあります。","id":"exchange-030"},{"speaker":"浅野委員","kind":"質問・要望","question":"今の友禅流しの件はわかりました。こういうふうに言ったら少しメディアが沸くんじゃないかなというのがあれば展開してもらいたい、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-05","title":"区営住宅入居者募集","agenda":"区営住宅入居者募集","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この区営住宅の入居者募集というのは、基本的には年２回行っていくという考え方でいいんでしょうかということが１点と、それから前回の１月のときは、何戸に対して何人ぐらい応募があったのかも説明を求めました。","respondent":"大串住宅担当課長","answer":"募集につきましては、委員おっしゃるとおり年２回を予定しております。今回の７月と年明けの１月、１月を予定しておりますが、そのときに空きがあるかどうかというのは何とも言えないところです。","id":"exchange-032"}]},{"id":"topic-06","title":"大井一丁目南第１地区再開発準備組合主催「再開発事業近隣説明会」状況報告","agenda":"大井一丁目南第１地区再開発準備組合主催「再開発事業近隣説明会」状況報告","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういう状況なのかなということで参加したんですが、そういうことでの資料がないということで、そういうのを求める意見がかなりあったんですね。そういうふうなものはぜひ、出せないのかな、出すようにということで指導ができないかなと思ったんですけど。","respondent":"溝口都市開発課長","answer":"説明の中でパワーポイント等を使って風環境の影響ですとか日影については事業者のほうから説明をされております。不確定な情報を、そういったところを勘案しながら、資料等の配付については今後とも組合と調整を図っていきたいと考えています。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ここもかなり高い建物が建つことになりますので、そういう影響がどうなるのかということを近隣の方は心配されていましたので、およそどういう状況になるのかというのがわかるような形での資料というのはぜひ今後工夫していただくようにということで指導をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"須藤委員","kind":"意見","question":"近隣説明会の対象区域というのは、建設敷地から建設建物の高さの２倍の範囲、約４,０００世帯というメンバーで、７２名という話なので、こういうメンバー以外の方も参考のために聞きに行くというのはできるのかとの意見を述べました。","respondent":"溝口都市開発課長","answer":"計画高さの２倍の範囲でお配りをさせていただきまして、今回事業の開催の案内につきましては、戸別にポスティングを行っております。計画高さの２倍の範囲の方たちに今回の計画についてはご説明を聞いていただきたいということで開催している説明会であります。","id":"exchange-035"},{"speaker":"須藤委員","kind":"質問","question":"地域の方々が意図していないような質問があったり、そのあたりはどういうふうにするのかなというのは、そのあたりはどういうふうに考えているのか。","respondent":"溝口都市開発課長","answer":"準備組合と計画を進めていく上での近隣に対する説明ですけど、通常であれば月１回からの、そういったことが大切だというふうに考えております。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"現地も見たかったですし、それから地域の中で皆さんどういう意見を持っていられるのかということをお聞きしたいということで参加したものであり。そのことはお話ししておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"須藤委員","kind":"質問","question":"ただ、どういう人が参加するんですかという質問をしただけなんでね。一言も言っていないので、近隣説明会のあり方、準備組合の説明会のあり方はどうなんですかという質問をしただけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４月２２日、２３日に行われたという事業者による住民説明会の対象というのは、これはやはり２Ｈの範囲ということなんでしょうか。それから、その後に今年の９月頃に都民の意見を聞く会を行う予定だということなんですが、その対象についても説明を求めました。","respondent":"野呂瀬環境課長","answer":"対象範囲は、委員おっしゃられましたとおり２Ｈの範囲と認識しております。それと、都民の意見を聞く会ですけども、先ほどと同じような形で２Ｈが対象です。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この建築物のＡタイプのところが高さ１２０ｍで、Ａタイプのオフィスビルというのが１棟、この大きな１棟というような形で考えていいんでしょうか。Ｂタイプは高層部と低層部というふうなことになっているんですけど、ここは何棟ぐらい建つのかということについてもお聞かせほしいと求めました。","respondent":"溝口都市開発課長","answer":"私のほうからＡ街区、Ａ地区、Ｂ地区、それぞれの建物の内容ですけど、それぞれＡ地区には１棟、Ｂ地区にも１棟、それぞれ１棟の建物が建つような形の計画になっております。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"準備組合に入っていない人というのはそのうち何人ぐらいいるのかということもお聞かせほしいと求めました。「反対者がいる場合でも」というふうに書かれているんですけど、この反対をされている方というのはどういう意見なのかということも説明を求めました。","respondent":"溝口都市開発課長","answer":"２点のご質問についてお答えいたします。都市計画反対云々というよりも、まず自分の生活再建についてどうかというところで反対をされている意見があるというふうに聞いております。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のところを教えていただきたいのと、夜間人口がどうなっているのかということと、またこの建物でどうなっていくのかというところがわかればお聞かせほしいと求めました。","respondent":"溝口都市開発課長、山崎マスタープラン担当課長","answer":"当開発についても、オフィスビルについては供給計画がありますので、当然それに伴う人口増というのは増えてくるというふうに考えております。当然オフィスビルと事業、オフィスビルを建てている関係から… あっ、恐れ入ります、平成１７年の数字です。住民票ベースの人口が約５万人、昼についてはその３倍ということですから１５万人というようなことです。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"平成１７年の段階で３倍ということですと、それから６年たっているとさらに増えているということになるんでしょうか。そこら辺のところの増え方と、１００ｍを超えるビルがこれで何棟ぐらいになるのかという、その数字がわかったら説明を求めました。","respondent":"溝口都市開発課長、片田都市環境事業部長","answer":"３地区については事業をしておりまして、いずれも基本的には１００ｍを超えるビルを計画または完了しているという実態になっております。詳しい数字については今持っておりません。 たしか１００ｍというとらえ方ではなくて、前に６０ｍ以上の高層ビルというような話をした経過がありますけども、区内全体の中では今７０棟ぐらいには来ているというような状況です。","id":"exchange-043"}]},{"id":"topic-07","title":"その他を先に行います。 まず、(1)所管質問","agenda":"その他を先に行います。 まず、(1)所管質問","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"補助２９号線が木密地域不燃化１０年プロジェクトに指定されるだろうということなんですが、２０２０年までに１００％完成を目指すということにこの木密地域不燃化１０年プロジェクトの中には書かれているんですけれども、その手法も含めて説明をしてほしいと求めました。","respondent":"藤田都市計画課長","answer":"１番の支援メニューの例にもありますとおり、沿道の用途地域や容積率の変更の前倒し、さまざまなことを考えていかなければいけないと考えています。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"補助３１号線のほうは区道になると思うんですけど、この東京都に働きかけていくというのは、東京都の決定というのも必要になるんでしょうか。ちょっと質問がたくさんになっちゃってすみません、完成しているのが何ｍぐらいあるのかということもあわせてお聞かせほしいと求めました。","respondent":"藤田都市計画課長","answer":"補助３１号線を整備しただけでは道路の交通のネットワークも、今回、補助３１号線はまだ時期が早いのかなというふうに考えてあります。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"補助３１号線を東京都に働きかけていくというのは、都の決定がなくても、これは区道なので区として決められるということなんでしょうか。補助金の関係とかで東京都が決定するとかということがあるんか尋ねました。","respondent":"藤田都市計画課長","answer":"この事業を進める上では、補助２９号線の整備とセットでなければ効果を発揮しないということで、東京都に働きかけるです。補助金等のこともありますので、まず根本的な部分で東京都に働きかけないといけないというふうに考えてあります。","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"かなり長い距離になるわけですけど、これすべてが特定整備路線ということで、指定されるということも可能性としてはあるんでしょうか。指定されたところは、不燃化特区とあわせて事業をしていくということになるのか、そこら辺のこともちょっとお聞かせほしいと求めました。","respondent":"藤田都市計画課長","answer":"その上に、不燃化特区の本格実施ということで、平成２５年のところに地区募集というのがあります。やはり道路を通すということだけでなく、仮に指定をされればこうした地区との連携を図って進めていくことが必要なのかなというふうに考えてあります。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０年プロジェクトというにもかかわらず、２０２０年まで１０年も満たない、八年の事業となっている。この２０２０年というのは、考えられる手法について、わかっているところがあったらお聞かせほしいと求めました。","respondent":"松代防災まちづくり事業部長、藤田都市計画課長","answer":"ここのペーパーの中では検討中のメニューの例として、沿道の用途・容積の変更、さまざまなメニューを検討して。そういった点では、今後、東京都の動向を見ながら、よく検討していく必要があるだろうと、このように考えているところです。生活再建のための特別な支援策をあわせてやるという中で、もっと早期に、短い間でできるというような形で東京都として考えているところです。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この補助２９号線全長を整備するとしたら、おおよそ事業費はどれぐらいかかるのか、区として考えられているところがあったらお聞かせほしいと求めました。","respondent":"藤田都市計画課長","answer":"区施工の路線であれば、おおむねの想定をしながらはじくようなこともありますけれども、今回の道路は東京都が整備する路線ですので、そういう中では、区のほうとしてそういった数値は把握してございません。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、補助３１号線だったら、およそどれぐらいという事業費がわかったら説明を求めました。","respondent":"藤田都市計画課長","answer":"補助３１号線についても、もう少し具体的になった段階ではお金をはじくようなことになると思いますが、大変申しわけございません、今の段階ではそういったはじきはございません。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"最後に、随分前に決められたこの都市計画道路が、こういう形で進めていくということになれば、区民の方、ここにかかわる区民の方にとっては、ほんとうに驚きだと思うんですけど、そういうところでは、区民への説明についてはどう考えられているかを説明を求めました。","respondent":"藤田都市計画課長","answer":"これまで議会のほうにもいろいろな形で地域の方々からお話が来て、いろんな経緯があったことも私のほうも把握しています。そういった面としては、区のほうとしても必要なことについてはしっかり地域にお話をしながら事業等をして進めていきたいというふうに考えてあります。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後です。今週中にも決まるということですので、ぜひ区民には十分説明をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/142731?Template=document&Id=4042#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":48305,"voices":165}},{"id":"h24-20120626-9","meetingId":"h24-cm06","date":"2012年6月26日","dateIso":"2012-06-26","committee":"文教委員会","time":"午前１０時００分～午後１時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"始めます。 予定表の順番では２の行政視察についてですが、先に予定表の３、その他","agenda":"始めます。 予定表の順番では２の行政視察についてですが、先に予定表の３、その他","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"やっぱり３・１１の震災の後ですから、やはりこれからのことを考えると、防災教育のほうをしっかりみてきた方がいいのではないかと思っています。案として、話しをさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"阿部委員","kind":"質問","question":"ちょっとなかなか困難なものですから、現行で行きたいなと思っているのが、大分県の豊後高田市です。やはり品川は津波というより、火災のほうが現実的に思えるので、火災を想定した防災教育の視点で視察できればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"鶴委員","kind":"意見","question":"全国には１００を超える幼老複合施設というものがあるので、こういう施設があれば、そういうところを選定していただいて視察したい。ただ、ちょっと発祥は富山県なんですが、今全国に展開されているということなので、検索した中であれば、そういう施設もあわせて見たいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"南委員","kind":"意見","question":"私は、１０年ぐらい前から、権利条約に基づいたまちづくりをしようというので検討委員会を立ち上げてやっているというところがあるんですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"高橋委員","kind":"意見","question":"相談施設と診療所と通園施設と、就学前から１８歳、青少年前までのトータルでやっている。「愛荘町」、２００７年のライブラリー・オブ・ザ・イヤーで大賞として受賞した愛知川図書館もぜひ参考に調査したいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"渡部副委員長","kind":"意見","question":"これからこども園がどうなっていくかわからないわけですが、園に限らず、さまざまな子育て施策等を見れるかな。どこか視察に行くとしても手前にあるので、一気に遠くへ行く前にということも考えられると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"意見","question":"今、防災教育で思い出したんですけど、「釜石の奇跡」というのが相当出ました。視察ができるかどうかは別としても、群馬大学の高崎教授だったかな、このことを想定していらっしゃったのはとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"阿部委員","kind":"質問","question":"少しフリートークとか議論とかをした上で、正副で調整していただけるというほうがいいのではないかなと思います。やはり議会の場ですから、多少は意見を言い合うということが１個挟まったほうがよろしいのではないかと私は思うんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"例えば、今一応皆さんから伺った中でも、それに対して皆さんいろいろまた聞きながら思ったことがあると思うんですよね。逆に正副の方々はどういう視点で調整されることになるのか、自分が正副だったら困るよなという感じになってしまいますし、どうなんでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"渡部副委員長","kind":"質問","question":"大事な２泊３日をどう有効に動くかというのを、あえてそこで話を伺うのではなくて、実際具体的にどこら辺に行けるのか。日付もあらあらこの辺でという時期的なものも決まっていますので、それを加味してここから選んでいくというような形で正副で調整したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"阿部委員","kind":"意見","question":"そういった形で、皆さんそれぞれほかの方々の意見についていろいろ感じるところがあるだろうなと思います。それを出し合ったところで、高いものになるのではないかなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"私は正副委員長にお願いするべきだという意見を持っています。ですから、それぞれの項目をぜひ部課長を含めて整理、それから対応していただいて、有効な行政視察になるように設計してくださることをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/162678?Template=document&Id=4764#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":8583,"voices":29}},{"id":"h24-20120626-5","meetingId":"h24-cm06","date":"2012年6月26日","dateIso":"2012-06-26","committee":"総務委員会","time":"午前１０時００分～午前１１時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"第４８号議案、平成２４年度品川区一般会計補正予算","agenda":"第４８号議案、平成２４年度品川区一般会計補正予算","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今回は、補正を組んでいて、基本の考えというんですかね。繰越金を使っていく考えとか、どの程度繰越金というのはこういう補正なんかに使っていけるのかという、大もとのところを説明を求めました。","respondent":"本城企画財政課長","answer":"初めに今回の補正の考え方ですが、冒頭説明させていただきましたとおり、当初予算の段階では想定できなかったものを緊急的に対処するというものです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"当初が２４億円の繰越金のうちで、もっと住民の方からもう少しここのところをやってほしいとか、きっと希望が出てくると思うんですね。その辺の見通しを教えていただきたい。","respondent":"本城企画財政課長","answer":"繰越金の関係ですが、５月末の出納閉鎖で締めた段階で、今回計上しております規模の繰越金が少なくとも見込めたので、今回の財源としています。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"何で皆さん笑っていらっしゃるんですか。そこをお伺いしました。","respondent":"本城企画財政課長","answer":"当初予算の段階で２４億円を繰越金と見込んでいたものにつきましては、それは財源としての当初予算の中に組み込んでおりますので、それを飛び出た、それ以上に見込まれたところを財源に見込んで今回の補正予算を組んでいるです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"その辺をお伺いしているんです。いかがか尋ねました。","respondent":"本城企画財政課長","answer":"当初の２４億円の繰越金については、平成２４年度の当初予算の中の財源として既に組み込んでありますので、その分は各事業に充て込まれています。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"今回においても、２４億円以外に見込めて新たにできてきたので、それを充てたというご説明でしたよね。新たに財源が生まれる見込みがあったらばというとらえ方でいいんか尋ねました。","respondent":"日下部企画部長","answer":"ですから、逆に言えば、それを差っ引きますと２億６,０００万円ほどの余裕がまだ見込まれるということが１つ言えます。今後、例えば契約落差とかいろいろなことが見込まれるとは思いますが、現時点ではっきりと財源として見込めるものは。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１５ページのところ、お願いします。一番上の一般管理費のところの非常用発電機付帯設備改修費のところをお伺いしますけれども、現状と。","respondent":"本城企画財政課長","answer":"現在、運転時間が２５時間ということになっておりますが、それを１１０時間に延長するものです。今あります非常用発電機の燃料タンクに接続することによって、それで容量を高めまして、２５時間から１１０時間に延長する工事をするというものです。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２５時間が１１０時間ということで、この１１０時間の根拠というか、その後は対応ができるという見込みなんですかね。そういうふうになっているのかどうかというのが１点と、あともう１つ、電源確保をするといったお考えを持っていただきたいなと思っているんですが。","respondent":"本城企画財政課長、平澤経理課長","answer":"前段でご説明させていただきましたように、かなりの長期的な緊急対応をする、そういうシステムになります。は太陽光発電ですが、第２庁舎の屋上のところに設置されているものにつきましては、庁舎全体の０.００１％ぐらいだと思います。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"数字の確認だけさせていただきたいんですけれども、これは４,０００円と先ほど発言いただいたんですが、それが１つ。そこらのところ、行政情報ですから確かな数字というのが必要だと思うんですけれども、そこらあたりの数字の違いの説明をほしいと求めました。","respondent":"本城企画財政課長","answer":"繰越金のご説明ですが、こちらに書かせていただいているとおりです。議案説明会の中で私のほうで説明させていただいたところだと思いますが、私が１２０と言ってしまっていたら申しわけございませんでした。","id":"exchange-008"},{"speaker":"阿久津委員","kind":"質問・要望","question":"発電機を点検する会社に勤めていたものですから、１つは、あと重油の貯蓄というのはできるのかどうか。一応確認で、それでもし弱いところが見つかった場合のその後の考え方、改修していくスケジュール的なものですね。","respondent":"平澤経理課長","answer":"１週間とかはどうかなと思うところですが、工事が終わったときにはやるところですが、非常に難しいかなと思っているところです。ただできるものについては、例えば家具の転倒防止みたいなことにつきましては、できるだけ早めにやっていきたいと考えているところです。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこら辺の基本的な防災に対する都と区と国の役割の分担あるいはお金の仕分け方というのは、基本的な考え方を教えていただきたいなと思います。以上、２点です。","respondent":"本城企画財政課長","answer":"貸付額自体は今回は９００万円ということですが、１,８００万円強ということで、約２分の１分の貸し付けということになっております。それから、もう一方の防災等にかかわる役割分担ということですが。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"もうちょっと具体的にお伺いしなければいけないんですけれども、防災ですから、国がかかわってきたりするわけですよね。とりとめのない質問なんですけれども。","respondent":"日下部企画部長","answer":"帰宅困難者というのは非常に平等性が高いですから、一基礎自治体のレベルで対応することにも限りがあるとか、そういう問題があろうかと思います。基本的には広域の視点で対応するというのが今の制度の現状になっておりますので、それはそれとして東京都にしっかりやっていただく。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"お話しいただきました１つ目、まさにそういうことを伺いたかった部分があるんですけれども、近隣区や何かとの連携が必要な部分が非常にある。品川区の予算におきまして、仮に特定財源化した場合のメリット、デメリットはどういうところに出てくるのか教えていただけますか。","respondent":"日下部企画部長","answer":"いわば財源を持ち合っているという状況でありまして、なかなか財政のいろいろな負担に一区のレベルで対応していくことは難しいかなと考えております。現行のそういう財源の仕組みをどう活用していくか、まずこれを優先的に考えなければいけないと、このように考えております。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"それから２年ほどはたっているんですが、１,８２３万円という補正ですが、これは有効なんですか。効果があるんか尋ねました。","respondent":"本城企画財政課長","answer":"先ほどご説明させていただいたような形の条件で貸し付けを今回行うことに想定していますが、このような貸付条件で対応させていただいたです。従前の類似の団体につきまして、荏原医師会に対して貸し付けという対応をさせていただいた経緯があります。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"４月１８日の被害想定で今回、こういうふうになったということで、ちょっと疑問に感じたので。よくわかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"石田（慎）委員","kind":"確認","question":"３月に基本的には当初予算を通して、４月からの実際的に運営ですので、なかなか第２回の定例会にこれほどの補正予算というのもないのかなと。大体が防災のことなので、そこが一番の理由で今回の補正予算を組むと思うんですが、そこだけ改めて確認と説明をほしいと求めました。","respondent":"本城企画財政課長","answer":"４月になって東京都から新たな被害想定が出まして、今回、防災関連のものを補正として出させていただいたです。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点目は、どういう範囲で考えられるのか、どういうところが対象になるのかというのを伺いしたいのが１つです。使いやすいところに設置してほしいというのが地区からも出ていますので、ちょっと今後についてお伺いしたいのと、実際に配備された後。","respondent":"本城企画財政課長","answer":"もう１点の旗の台周辺の配備の関係ですが、今回は２５器をこの周辺に配置することになりますが、それは検討していくということになってくるものです。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"行動を始めているところなので、引き続き区民の中から出てくる要望も受けとめていけるような姿勢で臨んでほしいと求めましたので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その予算委員会でもかなり議員側は各会派からもいろいろな質問も要望も出ました。そこら辺を１回お答えいただきたいのと、それから全体的な考え方として、大沢委員の質問の際に企画部長のお答えですごく理解はできました。","respondent":"日下部企画部長","answer":"きちんと見極めた上で１月中旬の原案確定、それで３月の議会にお諮りする、そういう手順を踏んでおります。あるいは最終段階での財源更正という形で、そういう一貫した一つの流れの中で反映させていただいている、そういうものです。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"意見","question":"１点目は十分行政側はわかっていると思いながら、あえて言わせていただきました。２点目の補助金に関しては、３月の当初予算の段階ではまだこれが対象になっているかどうかわからない、ちょっと意味がわからなかったとの意見を述べました。","respondent":"本城企画財政課長","answer":"先ほども木密地域不燃化１０年プロジェクトの関係で新たに計画が必要だとか、その財源となるものを上げさせていただいたということで、財源自体は決まっている形ですということです。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"中身じゃなくて、単純にちょっと教えていただきたいのが、明許の繰り越しと事故の繰り越しの違いが、これを見てどこがどう違うのかがよくわからなかったので、説明を求めました。","respondent":"本城企画財政課長","answer":"実際の会計処理としまして、原則として、地方自治法で、会計年度独立の原則ですが、その例外的な運用として繰り越しがあります。年度内の執行が見込めないものについて、避けることができず、事前に議会の繰越明許の手続をしていたかどうかによって変わってきます。","id":"exchange-020"}]},{"id":"topic-02","title":"の債権の放棄","agenda":"の債権の放棄","exchanges":[{"speaker":"石田（慎）委員","kind":"質問・要望","question":"１点だけ確認させていただきたいんですが、借りたときは生活保護を受けていなかったのかを確認させてください。その点、借りているときに生活保護を受けていてなのか、その辺をお知らせください。","respondent":"福田会計管理者","answer":"今、委員が例に挙げられました高齢者等住宅使用料、これはいずれも生活保護を受けていないときに若干滞ってしまったというものです。それから、女性福祉資金につきましては、お貸ししたときには生活保護を受けていなかったというものです。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"そういったところでは、全部は返せなかったという受けとめをしたんですけれども、こういった解決困難な事例はほかにもあるんでしょうか。その辺をお伺いしたいのと、ほかにこういうのがあるのかどうか、そこを説明を求めました。","respondent":"福田会計管理者","answer":"それから、この条例ができてこういう迅速な処理ができるようになったんですが、国でも、法律の中も債権を免除するという規定があります。それは返さなくなってから１０年たって初めて放棄できる、この条例を議会にお願いした、こういう経緯です。","id":"exchange-022"},{"speaker":"阿久津委員","kind":"質問・要望","question":"２つお伺いしたいんですけれども、高齢者住宅の使用料について、私の勘違いかもしれませんが、これは利息とか延滞金とかはつかないんでしょうか。２つ目が、平成１５年４月１日というこの積算の根拠というか、これは何なのかというのを教えてほしいと求めました。","respondent":"福田会計管理者","answer":"２点目でありますが、平成１５年４月１日というのは、これはもともと国の財産でした。したがって、区の条例が適用されて、区の遺失利益が生じた日、これが平成１５年４月１日という意味です。","id":"exchange-023"}]},{"id":"topic-03","title":"の立会川浸水対策事業における月見橋の家（総務部分室）の仮移転","agenda":"の立会川浸水対策事業における月見橋の家（総務部分室）の仮移転","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"こちらも売りに出ているでしょうか。ぜひ取得をしていただきたいという思いがあるので、こっちも売りに出ているのかどうかとか、そして今後の見通しについてお伺いしたいと思います。","respondent":"柏原行財政改革担当課長","answer":"ここも東電の敷地でございまして、１年ほど前、このマンションが震災の関係で工事が基礎を打ったところまででとまってしまっているという状況です。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"要望だけですが、ぜひ買っていただきたいなという思いが強くありますので、この場でお伝えしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この事業自体は東京都の浸水対策と水質改善ということで、事業は十分わかります。要望的なものになると思うんですが、区の月見橋の家と関ケ原児童遊園の広さというのはどのくらいあるのかなというのを１点教えてもらいたいんですが。","respondent":"柏原行財政改革担当課長","answer":"こちらのほうの面積です。こちら側だけで３４０m2程度、関ケ原児童遊園で２４０m2ということで、合わせて５７０とか８０m2程度の面積です。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"確認","question":"行政側として考えられたと思うんですけれども、このすぐ近くに大井保育園が、もう築５０年になる施設がありますね。容積等の問題も確認していないんですけれども、どういうふうに考えていたのか、もしよろしければ教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"大井保育園の部分につきましても、このお話が出てきた際に、大井保育園もというのが検討の中では出た部分はあります。総合的に判断して大井保育園をこちらに移すのはちょっと難しいなという判断をしたところです。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当然、区としても考えていらっしゃるでしょうし、いろいろ常に検討していらっしゃるんでしょうけれども、何か有効利用できれば、さらにいろいろな意味でご検討いただきたいということをお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"山元副委員長","kind":"確認","question":"こちらの移転場所をもう一回確認したいんですが、新しくつくりかえるのか、ちょっとお聞きしたかったんですが。","respondent":"中山人権啓発課長","answer":"まだ今の施設ができて１２年目ぐらいになるんですけれども、ちょっと位置をずらして、今の関ケ原児童遊園側に位置を移してまた建てるということになります。","id":"exchange-029"},{"speaker":"山元副委員長","kind":"質問","question":"自分の家を中心に考えたらもったいないなと思ったものですから、そのまま継続して使えないものなのかなと。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つだけ委員長にお伺いしてよろしいですか。委員長のご判断として、視察に行けるときと行かないときとどういう仕切りになるのか、ちょっとお伺いさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-04","title":"の４、行政施設","agenda":"の４、行政施設","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"もう１つ、東京の狛江市だったら行ってすぐ帰ってこられるなと思って提案をしました。２つ提案をさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"須貝委員","kind":"意見","question":"実際、それぞれ地方に行きますと、それぞれの自治体が財政的に、あと人口減ということでそれぞれ苦労されています。やはり２３区、したほうが、できれば近くでじっくり勉強できるところを選んでいただければありがたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは都内ではできない部分もあるわけですから、都内でなくても、日本全国ということで考えるべきだと思います。ですから、視察テーマ並びに視察先、ご判断をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"提案","question":"さっき２点提案したんですが、今年度の所管事務調査に契約についてというのが入りました。公契約条例制定に向けて提案をして、私はぜひ視察に伺わせていただきたいなと思ったので、あわせて提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"阿久津委員","kind":"提案","question":"今回の本会議での一般質問で同僚議員からもお話が出ましたけれども、１回見て、それを見て勉強したいなという思いはあります。フェイスブック等を使って、市民と行政の間が非常に近くなる、そういういろいろな取り組みをされているところですので、１つご提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-05","title":"の５、その他","agenda":"の５、その他","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"２０分で終わっちゃっても、３時間いたのでということでチケットをもらえれば、それはないんですか。質問はしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"早くて聞き取れなかったんですが、料金設定がどんなになっているのかというのを、もう１回説明を求めました。","respondent":"平澤経理課長","answer":"庁舎を利用される方は原則２時間までは無料ということになってあります。先ほどご説明いたしましたとおり、例えば会議等で長時間になる場合でも、職員に伝えていただければ、それは無料ということの取り扱いをするです。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579213?Template=document&Id=1918#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":33879,"voices":106}},{"id":"h24-20120627-14","meetingId":"h24-cm06","date":"2012年6月27日","dateIso":"2012-06-27","committee":"行財政改革特別委員会","time":"午前１０時００分～午後３時０２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"浅野委員長","kind":"質問・要望","question":"ご要望を踏まえ、理事者の意見も伺いながら、正副委員長で調整をさせていただきました。適宜、各委員の意見、要望等もお聞きしながら柔軟に進めていきたいと考えております。","respondent":"柏原行財政改革担当課長","answer":"私から、本日の視察に係りますご説明を、簡単に申し上げたいと思います。こちらのほうは、請願第６号に係わるものでございまして、建物やグラウンドなどの外観をご覧いただこうと考えています。","id":"exchange-001"},{"speaker":"中塚委員","kind":"意見","question":"私は、委員会に支障がない範囲で、委員会中も構わないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"西本委員","kind":"意見","question":"慣例という中では、そういうふうに決めたのには、いろいろ理由があると思うんです。いろいろたかれるということもありますので、できれば、始まる前だけにしてよろしいのではないかと思うんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"意見","question":"あえて、審査中に撮影してはだめだという明確な理由が示されておりませんから、構わないと思います。ただ、委員会質疑に支障があるのであれば、そのときは、委員長のほうで指摘をすれば済む話だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"委員長の判断ではなくて、だったら諮っていただきたい。前だけなのか、いいのか、はっきりしたほうが、運営としてはいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"平成２４年請願第６号、豊葉の杜中学校跡の活用に関する請願","agenda":"平成２４年請願第６号、豊葉の杜中学校跡の活用に関する請願","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"平成２６年９月以降ということですけれども、さきの一般質問で、ということを質問させていただいた経緯もあります。行財政改革特別委員会も始まったばかりですし、もうしばらく議論をしながら、考える時間があってもいいのではないかというふうに考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、若干指摘がありましたけれども、改めて、この点をどんなふうにお考えなのか、重ねて伺いたいと思います。公益的な行政需要、またやりくりについて、どんなふうにお考えなのか、伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"そういった部分については、かなり困難な面もあるというのは認識しています。何とか地域の要望にもこたえられないかということで、現在、調整をしています。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"前回の委員会では対立しないというお話もありましたけれども、改めて、そこのお考えを伺いたいと思います。その点については、どんなふうにお考えなのか、あわせて伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"着実に整備を進めてきているところですので、そういったところを考えながら、調整をはかっていくというものであろうと考えています。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"企画部長の答弁がありましたけれども、その趣旨は、どうなのかを伺いたいと思います。なかなかさまざまな要望にこたえる施設として難しいのかな、地域開放の要望を、中身をもう少し伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"どちら対どちらということではありませんので、区としては、それを総合的に判断するというところであろうと思っています。いろいろなことが考えられると思いますけれども、それから議会からいただくご意見を参考にしながら考えていくというものであろうと思います。","id":"exchange-009"},{"speaker":"西本委員","kind":"確認","question":"確認をしたいところがあるんですが、避難所機能というのは、多分同じではないと思うんです。どこに移動するというか、どこを避難所として決まっていくのかというのは、何かお考えがあるんか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"そちらのほうの町会の方に対する、例えば豊葉の杜学園施設や、こちらの荏原第四中学校跡に割り振りが若干出てくるというのを検討しています。普通教室を避難所として考えていますので、普通教室という考え方がなくなっていますので、内部で話を進めております。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"はじめの質問で、ほかの施設がありますよね。そこら辺、周りの避難所に振り分けたみたいな、そういう形になっているのかどうか。","respondent":"柏原行財政改革担当課長","answer":"詳細には、あれなんですけれども、その学校でもってそのまま使えるところでは、そのまま避難所でありますし、使えなくなった場合には、別の学校に割り振りをしたりとか、振り分けたり、そういう形で、いわゆるあぶれるということがないように調整するです。","id":"exchange-011"},{"speaker":"西本委員","kind":"意見","question":"(2)のスポーツということでは校庭が十分に広く使えるということになりますから、校舎については、全く違う考え方になる可能性もありますよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"同様の議論があって、防災を強化しなければいけないけれども、１階は保育園、２階、３階が高齢者施設、こっちにいわゆるシルバーセンター。先ほどの説明から、そこがちょっとよくわからなかったんですけれども、改めて伺いたいと思います。","respondent":"日下部企画部長","answer":"シルバーセンターの機能、それから保育所の機能、それから、体育館の部分も含めて地域交流施設ということです。入居施設一辺倒ではありませんので、あそこについては、原小学校の跡を現状のまま避難所として活用するということで決まった経緯があるです。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"意見","question":"今後の委員会の中でも、というお話があったり、先ほど、校舎の中の、という、これからそれもさまざまいろいろな検討を重ねていかなくてはいけない。結論は出さないでいただいて、やはり１回継続していただいて、我々もしっかりもう一度やっていければと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"地域の方々がどう考えるかというものを出していただいて、ただ新たなニーズというのも、やっぱり取り入れて考えてほしいと求めました。ということで、今後、引き続きということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"稲川委員","kind":"質問・要望","question":"いろいろほかの委員の方の質問を聞いて、地域の要望を優先させるということは、もちろん大前提であります。もっと議論していくべきだと考えていますので、私は、態度としては継続にしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"今、区が検討をしているとき、言いかえれば、決まっていないわけですよね。だからこそ、地元の願い、どういう願いがあるのかということをしっかり示すことは大事だと思いますので、結論を出すべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]},{"id":"topic-03","title":"の報告事項につきましては、関連する内容のため、一括して説明、質疑を行い、その後、請願","agenda":"の報告事項につきましては、関連する内容のため、一括して説明、質疑を行い、その後、請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"金額や契約書もなく学校を貸すということなのか、どうなのか、そこを伺いたいと思います。資料の一番下に、「９月以降の貸付に向けた協定等に明文化する」ありますが、明文化することになったいきさつを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"さらに検討を続けるといったところですが、第２、第３ＴＯＣビルの耐震検討を早急にさせたい。一時貸し付けが終わる９月までの間には、こういったことはきちんと、同意ができるように合意したうえで明文化をしたいというものです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"コンセプトも要望、工事着工も要望、伺いたいと思います。いわゆるＴＯＣの負担を少しでも安くするためということでよろしいのか、どうか、伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"区の土地鑑定評価をベースに考えていきますよと、貸し付け期間については８年間というところで、大体詰まってです。それから、賃借料の下限の問題ですが、先ほど申しましたように、財産価格審議会の部分につきましては、お話しはできないです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、なるべく早く議会に示したいというご説明がありましたが、それが９月の前なのか、後なのか、そこを伺いたいと思います。それだけに契約を結ぶにあたっての条件というのは、私は大事だと思うので、改めて伺いたいと思います。","respondent":"柏原行財政改革担当課長、日下部企画部長","answer":"基本的には、それが合意の内容ということになってこようかと思います。合意に向けて進めてまいりたいと思ってありますが、いろいろな動きある中で調整しながら、進めていきたいと考えて思います。 先ほど、行財政改革担当課長のほうからご説明申し上げました。しっかりと明文化する、担保をここでしっかりと確保するという考え方でおりますので、ひとつご理解をいただきたいと思います。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"暫定契約であれ、契約書どおりに履行されているのかどうかも確認できないというのは、一体どういうことなのかと思うんです。地域の声に耳を傾けるべきだと思うんですけれども、冒頭説明がなかったので、そこも伺いたいと思います。","respondent":"日下部企画部長","answer":"説明会でありますけれども、ご説明の機会を持たせていただきましたけれども、改めて具体的なご説明の機会を持っていきたいと考えています。どうでもいいということではありませんが、そういう形で対応をしていくと、今の段階ではこれが一番適当ではないかと考えております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の契約に係わってのことですから、やっぱり契約の前なのが、後なのかというのは重要だと思うので、そこをどう考えているのか伺いたいと思います。そうした住民要望こそ直ちにやるべきだと、私は思いますけれども、改めていかがか尋ねました。","respondent":"日下部企画部長","answer":"説明会の時期ですけれども、これはもう、当然のことながら、契約を交わす前ということで、私どもは考えております。契約前の段階で事前協議がすべて済むという形にはならないと思いますので、これは、契約後という形にならざるを得ないと受けとめております。","id":"exchange-022"},{"speaker":"須藤委員","kind":"質問","question":"ＴＯＣビルというのは、建設されてどのぐらい、いつころできているビルなのかということ。それから、ここに書いてある特定緊急輸送道路沿道の建築物耐震改修制度というのは、どういうことなのか、ちょっと説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"首都高速２号線、そういった趣旨を使って、ＴＯＣのほうも耐震等々について寄与していきたいです。それから、たしか昭和３７年築、そのぐらいだと思います。","id":"exchange-023"},{"speaker":"須藤委員","kind":"質問・要望","question":"こういった要望が出てきたら、ある程度、そういうものも速やかに出てくるだろうと思います。必要ではないかなと思いますので、後段は要望として、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"要望のところに、仮設の催事場、卸・店舗等とありますが、これはどういうイメージと思ったらいいのでしょう。そこの集約をどういうふうにされているのか、お聞きしたい。","respondent":"柏原行財政改革担当課長","answer":"平成１７年当時、それは学校の移転の関係がありましたので、そういった関係での説明会を行っております。平成２２年当時についても、説明会を行っています。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、だからといって、すべての要望は、当然ながら受けるわけにはいかない。さらに発展する側の要望というのですか、そういう流れで住民説明会をしていただければと、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鶴委員","kind":"確認","question":"今、それぞれほかの委員からあったところも踏まえて、お尋ねしたいと思います。開館が昭和４５年３月となっていましたけれども、建物をつくったのは昭和３７年ということでいいんですか、そこだけまず確認します。","respondent":"柏原行財政改革担当課長","answer":"申しわけございません、ちょっと訂正します。昭和４５年の築です。","id":"exchange-027"},{"speaker":"鶴委員","kind":"確認","question":"一つだけ確認なんですけれども、西本委員のほうからも確認がありましたけれども、第一日野小学校のあとに仮設店舗が建つわけですよね。これは、基本的にはそれをＴＯＣのほうで更地にして品川区にバックされてくるという考えでいいかどうか、そこだけちょっと説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"今、ご質問がありました貸し付けが終わった後ということだと思いますけれども、仮設でできた建物については、全部取り壊していただいて、更地の状態でお返しいただくということで考えております。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ、確認したいんですが、区内在住の中小企業も多く入っていると。そこら辺のところの要望は、もちろんつくってもらえていると思うんですけれども、そこら辺のところの確認だけはしておきたい。","respondent":"柏原行財政改革担当課長","answer":"そういったところについても、ＴＯＣのほうとは話をしています、こういった拠点になるような建物にしてくださいと。それは協議を行っていますし、これからも、そういう形で協議を進めていくと考えております。","id":"exchange-029"},{"speaker":"須藤委員","kind":"質問","question":"先ほど質問して答弁をいただいたように、できるだけ早く協議を進めていく。この請願に対しては願意に沿いがたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"塚本委員","kind":"質問・要望","question":"結論を出す。区の、ＴＯＣの貸し付けという要望に応じる形のさまざまな進め方についてを指示いたしますので、この請願については不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"本日、結論を出してほしいと求めました。この９月の暫定貸し付け終了後、さらにいろいろと考えながら進めていってほしいと求めましたので、不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"稲川委員","kind":"質問・要望","question":"結論を出すということで。非常に道路過密地域というのですか、進めてほしいと求めましたので、願意に沿いがたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"結論を出すということと、態度ですけれども、採択すべきだと思います。切実に求められている特別養護老人ホームや保育園や防災広場や、こうした住民要望に沿った活用、住民の声に耳を傾けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"ちょっとあれなのかなと、どういう事情なのか、そこをちょっと伺いたいと思います。はっきりしたものいいができなくて、申しわけないんですけれども、住宅のことはどうなのか、現状のお考えを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"前面道路が行きどまりになっていますので、狭いというところがありますので、そういった形での利用はなかなか厳しいものはあるのかなと考えています。社会福祉法人にお貸ししたときに、経費等を含めまして、そういった形の活用はなかなか難しいのかなと思ってあります。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"難しいというお話がありましたけれども、検討の俎上に乗ったことがあるのか、もう少しお考えを伺えたらと思います。改めて伺います。","respondent":"柏原行財政改革担当課長","answer":"住宅という部分を検討もなかったわけではございませんけれども、いろいろ検討した中で、かなり経費がかかるです。なかなか使いづらい部分もありますので、総合的な判断の中で、なかなか利用するのは難しいのではないかです。","id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"意見","question":"まだ、今検討中という言い方だったから、売却するならするということを決めて、それに向かって動いていくということのほうが、私はいいと思うんです。今まだ検討中みたいな発言だったから、改めて聞きたいとの意見を述べました。","respondent":"日下部企画部長","answer":"先ほど、行財政改革担当課長のほうからご説明させていただきましたけれども、区のほうとしましては、いろいろな角度から検討しました。いろいろな角度から検討しても難しいのではないかという中で、基本的には、売却の方向で進めていきたいという考え方を持っております。","id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"意見","question":"そうすれば、その分、高く売れると私は思うので、今、議会の意見もいいけれども、財産をしっかり高く売るにはどうしたらいいのか。そこら辺のところも加味して、やっぱりしっかり対応していくべきだと思うんですけれども、そこら辺の考え方はどうかなと思うとの意見を述べました。","respondent":"日下部企画部長","answer":"私ども、確かにそのようなことも考えられますので、できるだけ早めに方向性をはっきりとさせて進めていくということが重要ではないかと思います。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"ちょっと質問です。平成１５年４月から平成２４年度まで、これはどういう使い方をされていたのかと思うんですが、お願いします。","respondent":"柏原行財政改革担当課長","answer":"多くはそちらでございました。部屋としましては１４部屋、平成２３年度、ちょっと需要としては厳しいかなというところがございました。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"そうすると、アパートという形で使っていたということですか。どういう位置づけで、どういう目的なのか。","respondent":"柏原行財政改革担当課長","answer":"働いている職員がそこに入った。利用者ではなくて、職員がそこに入っていたというものです。","id":"exchange-040"}]},{"id":"topic-04","title":"３、特定事件調査、区有地と区有施設に関すること","agenda":"３、特定事件調査、区有地と区有施設に関すること","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"一つ教えてほしいというか、今ここに出ているのが平成２０年の結果ということなんですが、スケジュール的に発表は可能なものなのでしょうか。可能であれば、いつぐらいかということを説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"おそらく、速報ですが、秋ぐらいには出てくると思います。完全な形で、集計できるというのはもう少し後になろうかと思いますけれども、お渡しできる状態については、出せる段階でご報告します。","id":"exchange-041"},{"speaker":"石田（秀）委員","kind":"質問","question":"年少人口が２１人増えたということでしたけど、逆にどのぐらいになったかというのは、お調べになってないかな。私の記憶が違っていたら教えてください、２８％から３０％近くだったじゃなかったかと思っているんですけれども、今わかれば説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"平成２４年６月１日現在の住民基本台帳ベースということで、６５歳以上の高齢者の割合につきましては、八潮地区については２５％になっています。確かに２０％後半台になっていくような推計を出しておったんですが、高齢者につきましては、ほぼ近い動きをしていると考えています。","id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"伺って、どう考えているのか、委員の中でも意見交換していくということだと思うんです。どうしても、今、若いファミリー層を呼ぼうという話が多いではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"基本的なスタンスを伺いたいと思ったんです。どういう地区で、どういう施設なのか、この辺のお考えなどを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"その地区ごとの状況であるとか、そういったところを考えながら、配置等々、検討するのではないかという点から、当然、している中です。それから、検討ができませんので、地域のこういう施設がどうなのだというということを検討していくというところになってこようかと思います。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"南大井さくら会があるわけですから、どの辺がベストなのか、やはり一定の考えを持つべきだと思うんですよ。今後の委員会でもいろいろ議論はしていきたいと思うんですけれども、まず品川区はどんなふうにお考えなのか、基本スタンスを伺いたいと思います。","respondent":"日下部企画部長","answer":"人口は３５万人ですけれども、かなりコンパクトにまとまったエリアの中で３５万人が居住していらっしゃるという特徴が一つあろうかと思います。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域センターで言えば１３地区ですけれども、特別養護老人ホームのような施設でも大事にしていただきたいと、そこは改めて伺いたい。そういうものがまちづくりじゃないかと、私は思うんですけれども、改めて伺います。","respondent":"日下部企画部長","answer":"柔軟に、かつ弾力的にいろいろ対応できるという点では、区民の皆さん方のニーズにこたえてきているという状況だと思います。そういうケースについては、受け皿として特別養護老人ホームを設置していくと、このような考え方も含めて対応していきたいと考えております。","id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今から言うから、控えられるなから控えてほしいけれども、例えば、今、品川区でも保育園は待機児をゼロにしようと頑張っている。こういうところは、中塚委員の考えは、希望した人が全員入れる施設整備を区に求めているのかということを聞きたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"中塚委員","kind":"意見","question":"だから、まずは、目の前の問題として、特別養護老人ホームで言えば、一日も早くつくってほしいとは、当然思います。今年の４月に入れなければ、この問題を解決することは喫緊だと思いますので、希望者全員が入れるように目指すべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、すべてその日にそろう、明日からやって、４月に、というわけにはいかない。区営も含めてゼロにするような区の施設整備を求めているのか、求めていないのかということだけを言ってくれれば、それでいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"中塚委員","kind":"意見","question":"１割自己負担の問題があって、それがゼロになるかどうかというのは、必要だということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認させてください。そこら辺、何か施策的な考え方というか、ありましたら、説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"そういった協力をいただけるかというような話をした際にも、一定程度協力できるのではないかという回答をいただいているところです。","id":"exchange-051"},{"speaker":"西本委員","kind":"意見","question":"やっぱりそこは、そこにお金を落としてもらうということのほうを、何かしらその施策の中に入れるべきかなと考えたりしています。そうすると、そこら辺も含めて考えると、またちょっと違う視点が見えてくるかなと考えましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/931720?Template=document&Id=5926#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":52578,"voices":128}},{"id":"h24-20120628-17","meetingId":"h24-cm06","date":"2012年6月28日","dateIso":"2012-06-28","committee":"震災対策特別委員会","time":"午前１０時００分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員長","kind":"質問・要望","question":"９月下旬の委員会までに皆さんにお示しし、まとめに反映したい主なご意見について、各委員からご意見を伺いたいと考えております。もしご意見があったら午後の時間にぜひ出していただきたいと考えていますけれども、中途半端で悪いんですけれども、いいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"まとめのページのところで、最後の切りかえのところで、なかなか我々に、正副一任と基本的にそれでお願いしたいんですけれども、委員会はないんですけれども、まとまったものを委員会じゃなくても、見せていただくことがもし可能でしたら配っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"武内委員","kind":"質問","question":"想定外で閉じられなかった場合に全壊が１００棟ですか、全壊が１０棟で、東京都の被害想定で。丸投げになっちゃうと、ある程度それをやるために区がどこまで情報としてお示しできるのか、お手伝いできるのかなというところなんですけれども。","respondent":"武藤河川下水道課長","answer":"一定程度想定外への対応を考慮しておりますので、現時点では津波による浸水のエリアといったものを避難の前提として情報提示する予定はございません。","id":"exchange-003"},{"speaker":"武内委員","kind":"質問","question":"想定外ということですから、そういう面で、ハザードマップというのは東京都自身が出すかどうかというのはわからないということですね。その辺はどんな状況なんか尋ねました。","respondent":"武藤河川下水道課長","answer":"東京都が一定の法に基づく対応、津波の危ないエリアを、区としましても法に基づく津波の指定といったものができません。我々としても想定外の対応といった中で、内部で検討している段階でございまして、何か特別にどこか指定しているという状況ではございません。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"津波ですから、４ｍ以上の高台、こういうことに携わっていない方はどこが高台なのとわからないわけですよ。そこのところはどういうふうにお考えになって、今後どういうふうに、どちらなのか教えてほしいと求めました。","respondent":"稲田道路課長","answer":"荏原地区等はいわゆる高台でございまして、現在のところは当初計画した海側、そして河川沿いの設置でやっていきたいと考えております。１月２１日にも広報紙で、そういうふうな広報で周知していっておりますので、その辺で認識していただければと考えております。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"認識をしていればこういう質問は出ないわけでありまして、全部が全部つけろという話をしているわけではありません。必要性を感じないのか、それとも必要性を感じなく現状のままこれをとり行われるのか、もう一回教えていただきたいです。","respondent":"稲田道路課長","answer":"今回、津波に対するというところで低地部、河川沿い、海側ですので、現在のところは今回設置したところでやっていきたいと考えております。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"そこの部分、線引きをしてしまうのも広がりに足りないような気がするんですけれども、どういうふうにお考えになりますか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"はそのことをきちんと対応しながら、今後、委員からのお話がありましたようなことについても、今後きちんと対処等を考えてまいりたいと考えています。一遍にはなかなかできませんので、今は全力を挙げて取り組ませていただきたいと、このように思っているところです。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"優先順位からすれば確かに海沿いのほうは、することは、非常に優先順位は高いと思います。今後、荏原のほうは海抜何ｍぐらいなんですかということを、そんなような流れもひとつつくっていただきたいなと思いまして質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういう形になるかわからないんですけれども、啓発の活動をぜひしていただきたいということで、まず要望させてほしいと求めました。そういうところに対しては情報をどういうふうに提供していくのか、また避難をどういうふうに誘導、その点について説明を求めました。","respondent":"武藤河川下水道課長、松代防災まちづくり事業部長","answer":"作業を進めているのは３地域における、モデル地域として作業を進めておりまして、あわせてそれに必要な情報も準備をしていきたいと思っています。海の近く、そういった方々にも自主避難マップを個々に作成していただく中で… 今、担当課長が申し上げましたように、まずはモデル地区で実施し、低地部についてはそれをもって広く皆さんで考えていく。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私たちも改めて津波がどういう状況をつくり出すのか、できる限りのところで想定をしていただいての対応をぜひお願いしたいと思います。八ツ山通りですか、準備ぐあいというのは区としてはされているのかどうか、そこのところについても説明を求めました。","respondent":"武藤河川下水道課長","answer":"パワーポイントでもご説明させていただきました、海抜から見ましてもそれ以上の高い地域というのは各地域で考えられるところもあります。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"災害時要援護者のところでもそうなんですが、その点では津波に対してもぜひそういう方向で取り組みを進めてほしいと求めました。今後の対応ということもあるのかと思うんですけれども、そこら辺のところの今後の対応も含めた考え方をお聞かせほしいと求めました。","respondent":"武藤河川下水道課長","answer":"要援護者等に対する対応といったことですけれども、１点目は、先ほどのパワーポイントでも説明させていただきましたけれども。当然、まずワークショップとしましてはそういったことを中心にご説明させていただいて、進めてきていただいていると認識しておりますけれども。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"私は事前にどういうふうに避難するかということをお互いに確認し合っておいて、そしてスムーズにできるという、確認し合っておくということがすごく。災害時要援護者を津波からどう避難させるか、守るかという、いかがか尋ねました。","respondent":"武藤河川下水道課長","answer":"１点は、繰り返しになりますが、まずは個人が助かるといったことを前提に、きちんと説明していきたいと考えています。高齢者の方々だとか、要援護者の方々だとか、そういったことを一人ひとりが考えるきっかけといったものには活用していきたいと思っています。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この法律、去年１２月１４日に公布されたということなんですけれども、そのことでしょうか。そして、津波防災地域づくりの推進計画というのを区としてもつくっていくことになっていくのか、そのことについてお聞かせほしいと求めました。","respondent":"武藤河川下水道課長","answer":"ですので、当然、区としてはそれに基づく対応というのも、現時点では考えておりません。もし東京都がこの法に基づく動きがございましたら、その時点で区としての対応を考えていきたいと考えています。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すみません、長くなって。これは確認なんですけれども、護岸の耐震化というのはされているのかどうか、そういうところの耐震化についてお聞かせほしいと求めました。","respondent":"稲田道路課長、松代防災まちづくり事業部長、武藤河川下水道課長","answer":"橋梁長寿命化計画というのを平成２３年から実際、５年ごとの見直しをかけながらやっていくというふうに今、進めている最中です。… は津波というところでの対応と、今回の３.１１の映像でそういったシーンが出ましたが、内陸部に橋はかかっております。… 河川の護岸に対する耐震性の技術的な検討を昨年度から行っておりまして、まだその検討の最中と聞いておりまして、詳細はまだ報告されておりませんので。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に海から４kmも先の川までさかのぼって、ここら辺のところは、またわかりましたらご報告ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"阿久津委員","kind":"確認","question":"いろいろ質疑を伺っていて、私が考えていたものとこの津波自主避難マップというものが大分異なっているんだなというのがわかってまいりました。中で幾つか確認とお伺いをしたいと思うんですけれども、またお声がけはどういうふうにしているのか、そこら辺を教えてほしいと求めました。","respondent":"武藤河川下水道課長","answer":"企業のほうには区からお声かけしまして、近隣の比較的規模の大きい企業等にお声かけしまして、３社ほど正式にはご参加いただいております。","id":"exchange-016"},{"speaker":"阿久津委員","kind":"提案","question":"特に第二のほうは海沿いに大きな企業がたくさんあるものですから、先ほど私が伺っていて、そこら辺は今いろいろ検討されていると。検討の余地があるのかどうか、ここら辺もちょっとお伺いしたいと思いますとの意見を述べました。","respondent":"稲田道路課長","answer":"現在のところ既に設置してあるんですけれども、そういうところでの海抜の説明とか、そういうのを図りながら。設置する場所をいろいろと検討した中で、当初予定で、今設置したばかりですので。","id":"exchange-017"},{"speaker":"阿久津委員","kind":"質問・要望","question":"ワークショップの中で１つお伺いするのを忘れてしまったことがありまして、７月２１日に現地歩きをされると、大井南浜町会ですか。仕事の方ももちろんいらっしゃって、なぜ日曜日ではなかったのかなと、ここら辺のところを教えてほしいと求めました。","respondent":"武藤河川下水道課長","answer":"ご指摘の第３回のまち歩きの開催日程に関するご質問ですけれども、まち歩きにつきましてはこの日程ということで、町会長ともお話しさせていただいて決めた内容です。","id":"exchange-018"},{"speaker":"阿久津委員","kind":"質問・要望","question":"地元のもちろんご要望が第一だと思いますので、そのとおりかと思います。次の地域におきましても十分にご相談されて、一番皆様が集まりやすい、まち歩きしやすい日程を決めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"渡辺委員","kind":"質問","question":"その中で、今日のくくりでいうところの津波・高潮対策に限って伺えればと思います。それと、もう一点は、行政の限界、行政マンが直接動けなかったときに、準ずることを事前に準備できないものか、まず現状を伺いたいと思います。","respondent":"高山防災計画担当課長","answer":"気象庁発表のものが警察、そして消防のほうにも提供されますので、それぞれの機関において適切に周知の行動がとられるものと考えております。そういったものも複層的に加えて、津波などの緊急を要するような情報提供の手段として活用してまいりたいと、そのように考えております。","id":"exchange-020"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういった準備の体制という視点でぜひとも伺いたいし、検討されたい。高潮という点で伺いたいと思ったので、現状と、あるいは今後の見込みを伺えればと思います。","respondent":"武藤河川下水道課長","answer":"１点はですね、今回の東日本大震災での津波の対応で、それがどんどん周りに波及して避難行動につながったという情報があります。まずは行動につなげるといったところでの取り組みで、この津波自主避難マップ、そういったことをできるような形で進めていきたいと考えています。","id":"exchange-021"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ですから、情報伝達であればこうですよということを特に力を入れられてもいいのかなというのが要望であり、感想です。これはこれで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"津波の威力ですか、５０cmでも足をとられるというのに対しても少し、具体的にイメージがわくと思うんですよね。もうちょっと詳しくお知らせしたほうがいいんじゃないかなと私は思うんですけれども、その辺はどうでしょう。","respondent":"武藤河川下水道課長","answer":"その中でも今回いろいろな意見をいただいております。今後も第２回、第３回だとか、伝え方は考えていきたいと考えています。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"３.１１のあのすごい津波の映像を見ますと、先ほどおっしゃったようにわからない方、情報伝達のところをぜひ正しく伝えてほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"小学校とか企業の参加はどうだったかということで質問がされていましたけれども、同じように、こういうところに参加が必要だと思うんですね。それと、ここでそういう方たちの参加をちゃんと要請していたのか、お伺いします。","respondent":"武藤河川下水道課長","answer":"第１点は、今回は限られた方々への説明の中で、まずそこに住まわれている地域の方々を中心にお声かけをしています。特に施設管理者、一義的には施設管理をする方々が利用する方々への津波の避難といったものを考えていただきたいと認識しておりますけれども、保育園。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"そういったところに参加していただくことで情報というか、いろいろな課題も共有できるかと思うので、働きかけのほうは進めてほしいと求めました。そういうところの視点はどんなふうにあるのか、実際にはどういうふうに考えられるのかというところを教えていただきたいんですが。","respondent":"武藤河川下水道課長","answer":"重々ご承知のとおり、今回、低地部に開催しております津波の避難として考えている高台のほうというのはそういった方面になっております。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"そこのところをどういうふうに説明されていくのか、そこが結構、課題としてイメージをされている部分だと思うんですね。そこをどういうふうに説明されて、そこら辺をもう一度お願いします。","respondent":"武藤河川下水道課長","answer":"どうしても一定程度やはり、そういう情報を一人ひとりがまず認識していただくことが第一歩なのかなということを説明せざるを得ないかなと。区としてもできるだけ、我々の持っている情報をお出しする中で、一緒に考えていきたいと考えています。","id":"exchange-027"},{"speaker":"武内委員","kind":"質問","question":"その地域に住んでいる４ｍ未満ですか、そこまでまだしていないのかわかりませんけれども、その辺の判断。ワークショップの中でどういうふうにやっているのか、もしくはこれからやろうとされるのか、説明を求めました。","respondent":"武藤河川下水道課長","answer":"１０ｍ以上高いというのが、３階建てであれば、やはり高台を中心に考えていく必要があると認識しております。低い地域の方々におかれましては津波を心配される方は高台等に逃げることが基本になってくるかと認識しております。","id":"exchange-028"},{"speaker":"武内委員","kind":"質問・要望","question":"そこは統一見解はある程度出してあげたほうが、まず、第一の学校避難所も含めて要望しておきたいと思います。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"向委員","kind":"質問","question":"ラジオを私は持っていなかったですし、言って回ってくださったことがあるんですが、品川区はこうやって運河もあるじゃないですか。そういうときに船で通って呼びかけをするとか、そういった体制というのはこのあたりはあるんか尋ねました。","respondent":"武藤河川下水道課長","answer":"例えば今回の津波のワークショップの関係でも、非常に高い津波に対しての船からのアナウンスというものは具体的なものは今、定めてはおりません。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"津波火災については品川区としてはどのような想定をされているのかということをお聞きしたいんですが、今回の大震災の中でも津波火災から陸地のほうまでということがあったわけですけれども、そういう津波火災についてはどう考えられているかを説明を求めました。","respondent":"武藤河川下水道課長","answer":"例えば東京湾内にある船舶だとかが港湾施設に衝突して物的な被害があるだとか、浸水地域に放出された乗用車だとかが原因で火災が発生する可能性があるだとか、そういった定性的なシナリオは示されております。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区としてはそういう危険物施設とか、船舶がどれぐらいあるのかとか、そういうところでの、この被害想定というところは検討されている部分は、区としてはないということか尋ねました。","respondent":"高山防災計画担当課長","answer":"その上で、主たる対応という部分では、やはり消防関係であるとか、そういった部門が一義的な対応をしてくださるということかと思います。区としても一義的な安全対策の責任といいますか、対応というのはなかなか難しいものはありますが、そのように考えております。","id":"exchange-032"},{"speaker":"高橋委員","kind":"質問","question":"先ほど、情報の伝達がありましたけれども、そういう標示は今後どのようなふうにお考えになっているんでしょうか。２つ。","respondent":"稲田道路課長、高山防災計画担当課長","answer":"他の自治体の事例等も見て今回つくったんですけれども、現在のところは今の形でやっていこうかというところです。 常日頃からそういったご自身がお住まいになっていらっしゃる地域の近くの避難所を認識してもらうような方法の一つとして、そういった標示物による掲示などについては検討して、そのように考えております。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"１点だけお伺いしたいんですけれども、その辺がどういう、こういう揺れだったら海溝型というのがわかるというのはどういう状況か尋ねました。","respondent":"武藤河川下水道課長","answer":"どういった地震のタイプかを認識できるかというご質問なんですけれども、難しいと、極めて困難なものだと判断されます。","id":"exchange-034"},{"speaker":"沢田委員","kind":"確認","question":"判断力というところで２つに分けて書かれていたので、できるだけ高い高台へ避難という、そういうことでいいということでよろしいですか。確認を。","respondent":"松代防災まちづくり事業部長","answer":"特に低地部の方はそういった危険性の高いところだということをまず認識していただく。それを我々は受けとめて、どう対応すればいいかというのを今まさに備えとして考えるべきではないかと、このように思っているところです。","id":"exchange-035"},{"speaker":"木村委員","kind":"質問","question":"もし大きな地震が来た場合には、まずは最低限、何をしなければならないかということをしっかりと区民に周知するのが一番大事ではないでしょうか。そして、あともう一つ、標示板ですか、海抜ですね。","respondent":"松代防災まちづくり事業部長","answer":"低地部等の対応がどうなんだ、それに対する対応は何ができるんだというようなことがありまして、いち早くそういった対応を今とっているです。まず低地部の地域の区民の方々に対してどう今後の対応をすればいいのかというところにまず視点を置いておりましたので、ということは。","id":"exchange-036"},{"speaker":"本多副委員長","kind":"質問・要望","question":"外に出ている屋形船の、おそらく１日相当な、まだなければその辺のところを意識を持って取り組んでほしいと求めました。その点だけ説明を求めました。","respondent":"武藤河川下水道課長、松代防災まちづくり事業部長","answer":"まさに副委員長ご指摘のとおり、海沿いに来ていらっしゃる方々に対する津波の対策というのも非常に重要な観点だとは認識しております。連携しながら進める部分もあると思いますので、今後… 少し、今、副委員長から話がありました屋形船に限っていいますと、観光協会等を通じていろいろな話を伺っております。","id":"exchange-037"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"直接でも行けるようにしてほしいという要望が出されて、福祉のほうの部署からは直接でも受け入れるということになった経過があると思うんですね。細い字でもいいと思うんですけれども、そういう形でぜひ示していただきたいと思うんですけれども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"それを入れますと、線がかなり重複しまして見にくいものになります。その後が学校避難所と、もしくは表がわかりにくくならない範囲でつけ加えなどして、しっかりとお伝えしたいと思います。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"こういう図ができたことはよかったと評価をしているんですが、ずっと前からそういうふうに考えていた方たちというのはなかなか、変更するのが難しい。３.１１でも、そこもちゃんと課題としてとらえていかないといけないと思うんですけれども、現状はどうか尋ねました。","respondent":"鈴木防災課長","answer":"今ご説明した内容をしっかりと認識されていないかですが、５月、６月にかけて各地区の防災協議会の総会がございました。直接、今回のこういう整理の必要性があると、お知らせする必要性があると認識した次第です。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/167861?Template=document&Id=6412#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":47373,"voices":101}},{"id":"h24-20120717-6","meetingId":"h24-cm07","date":"2012年7月17日","dateIso":"2012-07-17","committee":"区民委員会","time":"午後０時５９分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"武内委員","kind":"質問","question":"６４名の方が就職できたというお話ですけども、(3)の内容の中に、この６４名の中には生活保護と内職の方は含まれているんでしょうか。この１０社程度の中で、これはそうすると、向こうの企業のほうから手を挙げていただいた中から選考するというふうになるんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"ちなみに、相談件数につきましても、７月までで３０２件ほど、生活保護の方の相談を受けているです。こういうものを各企業にお配りしまして、それで応募してもらって選考するという形をとりたいと考えております。","id":"exchange-001"},{"speaker":"武内委員","kind":"質問","question":"内職相談、ここはどうなんですか。その辺はどうなんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"そういうことが多いという雰囲気ですので、なかなか難しい面があろうかと思います。今年の１２月までに求人を決めていこうというふうに、来年以降、自社のほうで独自に詰めていただければというふうに考えているものです。","id":"exchange-002"},{"speaker":"武内委員","kind":"質問","question":"今の話だと大学卒業もしくは卒業後３年ぐらいの方ということですけど、こちらは、ただあくまで企業支援ですよということなんですよね。あれ以上はなかなか、場所、スペース的にはとりようがないと思うんですけど、その辺はどんなイメージなのか、考えているものがあれば説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"一般の就業支援につきましては、ハローワークのほうでもかなり行っていますので、そこと連携しながら行っているというものです。さらにそれを進めてですけれども、そういった方々に対する支援につきましては、それについては十分研究していきたいというふうに思ってあります。","id":"exchange-003"},{"speaker":"山内委員","kind":"質問","question":"教えてほしいのが、区内企業の雇用の件数、現在、今把握しているだけで、どれだけの会社が雇用を望んでいるのかというのを教えてください。それと、平均的な年齢層を教えてほしい。","respondent":"福島ものづくり・経営支援課長","answer":"ハローワークのデータでしかわからないですし、また日々変わってきますので、その日その日でいくつあるかというのを検索してみないとわからないです。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問","question":"そういうのを探すことは可能なんでしょうけれども、そういった観点からちょっと今伺ったので、まず生活保護受給者にどうやって周知をしているのか。毎月１日が彼らにとってはいわゆる生活保護を受給する日になっていますけれども、その日に、そのあたりを今日伺いたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"生活保護のケースワーカーと、またハローワークから週３回そのための者が来ていますので、その三者でもって相談をするという形をとってあります。ですから、働きかけにつきましては、すべて生活福祉課のケースワーカーが行っているです。","id":"exchange-005"},{"speaker":"山内委員","kind":"質問","question":"さっきは１１件という話だったけれども、大体どれぐらいの人たちというか、そういった生活保護を受けている人たちはこれまできているのか。もしわかればでいいんですけど。","respondent":"福島ものづくり・経営支援課長","answer":"生活保護受給者ということでお答えしますと、相談件数に関しまして、７月１３日までの段階で３０２人の方について相談をしたです。そのうち、仕事を実際に紹介できたのが２４８人、それで実際に就職をしたというのが１１人という結果です。","id":"exchange-006"},{"speaker":"山内委員","kind":"質問","question":"２４８件のあっ旋ということで、もう少しそこを活用して、１１件というのはちょっと少ないなと思うんですよね。もう少しその辺に力を入れていくべきではないのかと、これだけ大きな問題になっているので、そのあたりをどう考えているか説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"確かにそのとおりだと思いますし、実際に行っているのは生活福祉課というセクションで行ってあります。私どものほうとしましては、就業につながるところで支援をしているという関係ですので、よろしくお願いします。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"実際ハローワーク品川と品川区就業センターの一体化というのは、具体的にどういう施策で反映されているのか教えてください。それと、就職の件数が平成２４年度で６４人ですが、この６４人という数字を、区としてはどう考えているのか説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"平成２４年度につきましては、年間４００人を目標として、これから４００人を超えるようにということで日々格闘しています。したがいまして、この３カ月で６４人ということであれば、年間目標は達成できるんではないかというふうに考えているものです。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"そのぐらいの割合でいいんですかというか、どこかいいところはないですか」、必ず「いいところはないですか」と言われるんですけれども。さっきの上のほうの２行でという質問の答弁で、福祉にかかっている方の、これがやっぱりメインだったんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"先ほどお答えさせていただきましたけれども、一般の方の就業支援ということがメインですし、よりいいのではないかというふうに考えてあります。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"開設されてから３カ月半ぐらいですか、おおむね順調にいっているなというふうに今聞いていて思いました。その辺のあっ旋をしたり、その後の対応の根気よくやる取り組みについては、どういうふうな感じか教えていただきたい。","respondent":"福島ものづくり・経営支援課長","answer":"やはり根気よく来てくれるように、うちとしましては、そういう対応をしていきたいと思っている次第です。毎日のようにここに来て、ハローワークと生活保護と一緒になってこうした問題に取り組んでいけるんじゃないかというふうに考えてあります。","id":"exchange-010"},{"speaker":"武内委員","kind":"質問・要望","question":"これは要望なんですけど、実態と違うケースというんですかね、圧倒的に少ないわけです。やっぱりどう見てもこの人は、連携みたいなところも含めてやっていただけるといいなと思うんですが、何かその辺についてあれば。","respondent":"福島ものづくり・経営支援課長","answer":"ただ、セミナーになりますと、個別の相談の中でもそういったことについても相談に乗るようにという形はとっていきたいというふうに考えてあります。","id":"exchange-011"},{"speaker":"井上副委員長","kind":"質問・要望","question":"協定を結んで事業を一緒にやりましょうというものなのか、そこの辺の一体的に実施というところの組織的なものについて、ちょっと先に整理をさせていただきたいので説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"入り口のところに１名受付の者がいたかと思うんですけれども、あの受付につきましては、区のほうの経費です。そういった形で、国、ハローワークと品川区とで役割分担、経費分担をしっかりした上で、共同で運営しているというものです。","id":"exchange-012"},{"speaker":"井上副委員長","kind":"質問・要望","question":"それは今お伺いする部分では、ちょっと大きなところで結構ですので教えていただきたいことと、品川区が求めている生活保護の支援を中心にというような意味合いでそこを持っていかれたのか。","respondent":"福島ものづくり・経営支援課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"井上副委員長","kind":"確認","question":"先ほどおっしゃられた生活保護の専門相談員３人というのは、それは同じ人なのか、ちょっとそこのところの確認をお願いしたいんですけど。前にやっていた品川区の人材の事業が今どうなっているのか。","respondent":"福島ものづくり・経営支援課長","answer":"昨年まで行っていました生活保護の専門員による事業、それはそのままこちらで行っているという形です。","id":"exchange-014"},{"speaker":"井上副委員長","kind":"質問","question":"わかりました。それはすべて区とは離れてこちらの４人の人件費、国から受けている４人の方たちとか、その辺の関係はどうなっているんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"ハローワークのものではありません。ハローワークのあの４人が対応しているのではなくて、区の職員が対応しているものです。","id":"exchange-015"},{"speaker":"井上副委員長","kind":"確認","question":"３番なんですけど、先ほど求人企業支援事業というところに、協定の中にそれを進めましょうということがあったので、そこからなのかなと思ったんですけど、これは区の事業として始めようというものではなくて、協定の中からこの事業を行っていくというものだったのか、そこの確認。","respondent":"福島ものづくり・経営支援課長","answer":"こちらの３番の事業につきましては、区として実施する事業です。区で実施する事業といっても、協定に結びつきまして、実際のところは区の事業としてやっているものです。","id":"exchange-016"},{"speaker":"井上副委員長","kind":"質問・要望","question":"コンサルタントとか、そういったものは既に決められたのか、７月からということなので、どういう選考でそういう人たちが選ばれているのか、その仕組みを教えていただきたい。","respondent":"福島ものづくり・経営支援課長","answer":"７月に入りましてから事業者を募集しまして、プロポーザル方式で事業者を選定し、７月から事業を開始したというものです。その２社を十分検討しまして、１社に絞り、そこと契約し、行っているものです。","id":"exchange-017"}]},{"id":"topic-02","title":"の平成２４年度、地域振興基金を活用した区民活動助成事業の決定","agenda":"の平成２４年度、地域振興基金を活用した区民活動助成事業の決定","exchanges":[{"speaker":"武内委員","kind":"意見","question":"ちょっと読んでいないのでダブったら申しわけないんですけど、同じ事業を２年続けてやるとかというのは、基本的にはなしにしているのかどうか。今まで４年になるんですけど、そういうデータがあったかどうかとの意見を述べました。","respondent":"今井協働・国際担当課長","answer":"概要のところの助成対象事業の要件の5)にありますが、団体の発展につながらないというふうな判断で、一次審査で却下になったということがあります。審査の対象にもなりますし、これまでも、団体として２度目の採択をされた団体もあります。","id":"exchange-018"},{"speaker":"武内委員","kind":"質問","question":"あえてそれはそれとして、２年度目以降は自分の団体で独自にやってくださいという考え方なのか、それとも何かそれに対しての助成がないのか。公益支援みたいなのが何かあったら教えてほしいのですが、それともそれは切り離してということなのかどうか、その考え方を説明してほしい。","respondent":"今井協働・国際担当課長","answer":"本助成事業のほうは、品川区の地域振興基金を活用した区民活動助成金交付要綱に基づいて実施しています。委員のご質問の中の事業についてですが、本事業は区民活動団体の自主事業が基本的には自分たちでまず事業を実施しているというのが原則です。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"助成３分の２でしたか、上限が５０万円、区としてどこでどう判断をしていくのか。基金ですけれども、公のお金が入っていくわけですから、その辺をお願いします。","respondent":"今井協働・国際担当課長","answer":"次に、投資対効果ですが、私どももこの事業者に対しまして、実施の効果、どういう地域課題が解決できるか。ですので、私たちもこの事業が実施される場合には職員なども一緒に見学するなどして、私たちの目でも確認してまいります。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"地域活動課の課長として、活動している団体の括弧欄には町会というのが入っているんですけれども、町会の申し込みなんかは全然ないじゃないですか。一番地域でもやっているのは町会ですから、こんな助成をどういうふうに活用していきたいと思っているか、それぞれご答弁をお願いします。","respondent":"今井協働・国際担当課長、久保田地域活動課長","answer":"平成２１年度のときには、町会からも申請はございました。その中で取り組んでいただいたというケースもありますので、こういうふうな制度を逆に利用していただくというのも一つ考え方としてはあります。今説明をさせていただいたように、こういったものも用意してあるということで、メニューとして考えていただければというふうに考えてあります。","id":"exchange-021"},{"speaker":"井上副委員長","kind":"質問","question":"だから、そんな立派なチラシじゃなくたって人は呼べるのにというようなところで、使い勝手としては課題があったと思うんです。何年もこういうふうに繰り返されて、その内容的に改善されたこととか、利用者の方からのご意見の反映とか、そういった工夫があれば説明を求めました。","respondent":"今井協働・国際担当課長","answer":"私たちも受付のときにその辺をよく説明しながら、こういうふうにやったらいいんじゃないですかというアドバイスを職員がするようにしております。","id":"exchange-022"},{"speaker":"井上副委員長","kind":"質問","question":"もう５年、６年経過していますから、あると思うんです。何かお考えがあるのか、行政で担えない部分をどう地域で担ったり、その辺はいかがか尋ねました。","respondent":"今井協働・国際担当課長","answer":"応募できる団体の資格要件の中に、やはり原則として活動実績があることというのを置いております。そこの団体がきちんと今までに実績があるという考え方が一つですので、この助成金を使っていただくというところで今のところは考えております。","id":"exchange-023"},{"speaker":"井上副委員長","kind":"提案","question":"これからはそれが必要な時代だということで検討をしていただきたいということは、いろいろな議論をしながら提案をしていきたいというふうに思います。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-03","title":"の日曜開庁の来庁者１０万人到達","agenda":"の日曜開庁の来庁者１０万人到達","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"委員長にちょっと質問なんですけど、日曜開庁についての質問だと、ほかの課にもかかっちゃうから、日曜開庁の戸籍住民課についてしか質問できないわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"今日は質問しても所管が違うのであれなんですけれども、せっかく２階も３階もいろんなところに立っていただいているじゃないですか、案内の方。ちょっとこの場で要望として、伺って経理課長に話すなり、その辺の要望だけで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"本多委員","kind":"質問","question":"すばらしいと思うんですけれども、例えば１０万人を超えた次の週がそうだったと思うんですけど、今までにどのくらいあったのか教えてください。字体というのは特に区単独のものなんですが、何か非常に見づらいという意見が出ているんで、説明を求めました。","respondent":"井浦戸籍住民課長","answer":"当日の対応ですが、それから徒歩の方が入り口のところで気がついていただけるように努めまして、可能な限り周知していきたいです。私どもとしては、他区の状況等も見まして、文字について改善できることはないか検討、研究してまいりたいと考えております。","id":"exchange-027"},{"speaker":"武内委員","kind":"質問・要望","question":"私も実はよく５階からたばこを吸って下を見ていると、また今度こっちの議会棟のほうまで来ているとか、そういう方が結構いる。やっていたはずなのにと、自分の勘違いなんだけど、その辺の工夫もしていただきたい。","respondent":"井浦戸籍住民課長","answer":"平成２０年１月に開始したときに、超勤対応ではなくて、人件費の持ち出しはなしでスタートしたという経緯があります。このような方についても、経理課とも連携しまして、わかりやすい案内板について工夫してまいります。","id":"exchange-028"},{"speaker":"武内委員","kind":"確認","question":"最初のほうの確認なんですけど、そうすると、その当時、始めた当初から今も日曜開庁のための特別な人件費が増えたということはないということですね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]},{"id":"topic-04","title":"の外国人住民制度に係る改正法の施行","agenda":"の外国人住民制度に係る改正法の施行","exchanges":[{"speaker":"山内委員","kind":"質問","question":"外国語のところで、５カ国語と言われたんですが、英語、中国語、韓国語は何となく想像できるんですけど、あと二つは何でしょうか。在留資格がないのが３３０人とありますけれども、在留資格がない者が日本にとどまるということは、どういうことなのか説明を求めました。","respondent":"井浦戸籍住民課長","answer":"５カ国語につきましては、英語、韓国語、中国語のほかに、ポルトガル語とスペイン語になります。これまでも何らかの事情で期限切れの後、更新していないですとか、このような形で数字としてあらわれているというふうに認識しております。","id":"exchange-030"},{"speaker":"山内委員","kind":"質問","question":"よくわからないんだけど、在留資格がない人たちをどうやってチェックしているんですか。法務省との連携を取り合って、そういうことをしているのか、その点、ちょっと詳しくもう一回説明を求めました。","respondent":"井浦戸籍住民課長","answer":"平成５年をピーク時に、３０万人弱の不法滞在者というものが認められたのが、現在は５万人から６万人に減少してきている。国の外国人在留制度等の改正の中で、不法在留というものについては、国が中心に取り組んでいるというふうに認識しています。","id":"exchange-031"},{"speaker":"山内委員","kind":"質問","question":"この３３０人を国に、簡単に言えば、要はこの３３０人は日本から退去してもらわなければ困るということなわけですよね。そういうこととは違うんか尋ねました。","respondent":"井浦戸籍住民課長","answer":"住民票に移行されないこの４１３人については、もしかしたら、既に出国されている方も多分に含んでいるというふうに考えてあります。したがいまして、実数として３３０人を行政機関とし把握しているというものではございません。","id":"exchange-032"},{"speaker":"山内委員","kind":"意見","question":"つまり、４１３人が品川区に登録しましたと。今把握しているのは４１３人だということであって、だけど、この中には不法滞在者もいるかもしれないよということなわけですよねとの意見を述べました。","respondent":"井浦戸籍住民課長","answer":"そして、そのうちの８３人は短期滞在の在留資格ですので、短期の期間に出国されることを予定していますので問題はない。あくまでも、かつて外国人登録法に基づいて登録をされていて、その後在留期間が切れた等により現在在留資格がなくなっている者の数です。","id":"exchange-033"},{"speaker":"山内委員","kind":"質問","question":"そこから、国、法務省なら法務省に通達をして、これだけいるけど、どうするんですかということを、たぶん品川にはできないと思う、そういった業務は。３３０人いるとしたら、この品川で暮らしていくことを黙認しちゃっていると僕は思うんだけど、その辺どうなんか尋ねました。","respondent":"井浦戸籍住民課長","answer":"この３３０人の方を含む旧外国人登録原票というものは、法務省にすべてお返ししています。外国人登録をしていた台帳、在留管理を適正化していく国において、今後これらの人に対応をしていくというふうに区としては考えてあります。","id":"exchange-034"},{"speaker":"山内委員","kind":"確認","question":"最後に、今確認をしたということで、国と連携を取り合いながら不法滞在者のチェックに区も協力をしていくということでいいんですね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"武内委員","kind":"確認","question":"その中で在留資格がない、この人は未確認を含めてということでしたけど、その方もいたと。その上で、当初から外国人登録者として、在留資格がない方が登録されているということは区としてはわかるわけですか、移行する前は。","respondent":"井浦戸籍住民課長","answer":"廃止された外国人登録法におきましては、外国人登録カードの更新のときに在留資格を確認しております。在留資格が確認できない方についても、適法に外国人登録法上、外国人登録のカード交付を行っていたという事実があります。","id":"exchange-036"},{"speaker":"武内委員","kind":"確認","question":"実際に、もしかしたら不法入国かもしれないけども、そこまでのことは区ではつかめなくても、未確認でも交付していた。その辺のところはしっかりと確認されるので、そこであとは国がしっかりそこをチェックするという流れになると、そういうことでよろしいか尋ねました。","respondent":"井浦戸籍住民課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"武内委員","kind":"質問","question":"今品川区にも大使館がありますし、各国いろんな、国ごとの団体があります。そういう大使館は当然だと思うんですけど、そういう団体の方々にある程度お知らせというんですかね、されていますか。","respondent":"井浦戸籍住民課長","answer":"法務省を中心に、国の根本的な制度の問題ですので、各種団体についての周知等についても国を中心に行っていたというふうに認識しています。区としては、特に行っておりません。","id":"exchange-038"},{"speaker":"武内委員","kind":"意見","question":"わかりました。その辺、どこまで可能かどうかわかならないんですけど、スムーズにいくような形でやっていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"武内委員","kind":"意見","question":"そういう問題意識で品川区を変えるということができるんじゃないかというところまで、ある程度あぶり出していければいいなと思いますとの意見を述べました。","respondent":"西本委員長","answer":"前回、公明党のほうから佐久市という話をいただきましたけれども、いろいろ検討したんですが、行程の関係によりこのようにさせていただきました。ほかにご意見ありますか。","id":"exchange-040"},{"speaker":"本多委員","kind":"質問・要望","question":"正副案でお任せしますが、所管事務調査が充実できるように進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"武内委員","kind":"質問","question":"これについて、生活安全担当課長のほうに警察から何か連絡なり対応策なり、お話が行っていますでしょうか。もし、来ていれば、その内容についてつかんでいらっしゃれば。","respondent":"川崎生活安全担当課長","answer":"現在のところ、事実は事実としてございましたが、背後関係とか今後の捜査の見通しなどについては捜査中という回答をいただいております。ただ、けが人等は発生しておりません。","id":"exchange-042"},{"speaker":"武内委員","kind":"意見","question":"新聞とかにも出ましたし、ニュースにちょっと流れて、近所の人が見ればどこということがわかっちゃいますので。どうして、何かその辺を今の段階ではどうするとも言えないと思うんですけど、何かその辺のことはありますかとの意見を述べました。","respondent":"川崎生活安全担当課長","answer":"今後の捜査状況を見ながら、教えてもらえる範囲の中、その中から皆さんにお伝えすべきことはお伝えしていきます。そしてまた、我々生活安全パトロール隊、こちらのほうで重点的なパトロールをして、住民の方々に不安感をあおらないように努めてまいります。","id":"exchange-043"},{"speaker":"武内委員","kind":"質問・要望","question":"情報をぜひリアルタイムに警察ととりながら、区のほうで何かできることがあるならば、その段階が来たらばしっかり対応していただきたい。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"武内委員","kind":"質問","question":"ほんとうはその先の商店街もと思うんですけれども、そこまでいくと広がりすぎるので、そういう角度でお伺いできればなと考えています。個人的には小規模商店街のところを突っ込んでお話が伺えればなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"藤原委員","kind":"意見","question":"山王銀座商店街、今どういう現状になっているか、助成をした結果どういう形になったのかというのを委員会として見に行ってお話を聞いてくる。具体的に一つの商店街になっちゃいますがとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118408?Template=document&Id=2642#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":35692,"voices":120}},{"id":"h24-20120717-7","meetingId":"h24-cm07","date":"2012年7月17日","dateIso":"2012-07-17","committee":"厚生委員会","time":"午後１時００分～午後２時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"今年度の所管事務調査の項目につきましては、６月２６日の委員会において、「生活保護の現状と自立支援」","agenda":"今年度の所管事務調査の項目につきましては、６月２６日の委員会において、「生活保護の現状と自立支援」","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"３ページの保護の手続のところで、今ある一連の仕事の中で、特にどこら辺が最も負担が大きいのかということを一つ教えてほしいと求めました。これは確認なんですけれども、２３年度が、資料に問題があるわけではないということでいいのかどうかを確認したいと思います。","respondent":"竹田生活福祉課長","answer":"家賃等や光熱費に充てることができないといった方もおりますので、そういった方にも、ケースワーカーは時間を取られるということがあると思います。若干の違いがあるんですが、ちょっとその違いをうまくグラフで表現できませんでした、大変申しわけございません。","id":"exchange-001"},{"speaker":"塚本委員","kind":"質問","question":"そうしたら、ちょっと話の角度が変わるんですけれども、医療扶助もそうなんですけれども、住宅扶助が結構な割合を占めているかと思うんです。どうしても生活保護となったときに、その辺のコストバランスというんですか、その辺はどのように見られているのか尋ねました。","respondent":"竹田生活福祉課長","answer":"その住居に引き続き住んだほうがメリットがあるのかということを比較考慮いたしまして、経済的に有利なほうを選択することになっております。","id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"なるほどとお伺いしたんですけれども、保護がどこまで続くかわからないと、明確には出ないわけですよね。そういう意味でのバランスというのは、どういうふうに見ていらっしゃるんか尋ねました。","respondent":"竹田生活福祉課長","answer":"ごくまれなケースですが、そういったケースもあります。所としての方針を決定いたしまして、売却したほうがいいのか、それとも引き続き住み続けることがいいのかということを所内の会議で決定しています。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"４分の３と４分の１はいいんですが、東京都はどのように絡んでいるのか、もしそれがあるならば。それから、財調算定でどういう形で組み入れているのかという、お金の関係のところだけを、もうちょっと細かく教えていただきたい。","respondent":"竹田生活福祉課長","answer":"例えば就労支援員とか、社会自立相談員といった相談員の費用、あるいは、その事業といったところを東京都より支出していただいております。財調のほうですが、こちらのほうは非常に厳しい認定になっておりますので、こちらのほうより上乗せした基準で運用しているです。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうして東京都が絡まないのかという話は、東京都で言う山谷対策みたいな費用は莫大だから、それは東京都で持ちますと。２３区の中で、あるとしたら、どういう形でやっているのかということをお聞きしたい。","respondent":"竹田生活福祉課長","answer":"２３区を五つの地域に分類しまして、それぞれにセンターを設けまして、いずれの地域にもセンターが常にあるという状態を保っております。東京都と特別区につきましては、今後も、部長会、課長会等を通しまして、今後のあり方について協議している最中です。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"どういう話があって、どういうことが事実としてあるのか、そこら辺を教えてください。ホームレス対策って、どれぐらいのくくりで金額を見ればいいのか、そこら辺を説明を求めました。","respondent":"竹田生活福祉課長","answer":"申しわけございません。ちょっと今、手持ちに資料がございませんので、調べてお答えさせていただきたいと思います。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"財調の中で、例えば３税が都税になっているわけでしょう、そういう意味では。と私は思っているんですけれども、そういう考え方の発想はおかしいですかね、そこら辺の見解を説明を求めました。","respondent":"早津健康福祉事業部長","answer":"的確な答えになるかどうかわかりませんが、その定まった自治体と国の分担と、こういう切り分けだったように思います。その切り分けを前提にしたうえで、自治体の持ち分がかなり苦しいので、国のほうでもっと持ってほしいというような動きを、今、しています。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それから、ケースワーカーが第１６条に触れちゃっているわけじゃないですか、触れちゃっているときは、どうなるんですか、現実は。全区って言っていいぐらいなっていると思うんですけれども、現実問題、こういうのはどういうふうになってしまうのかというのを教えてほしい。","respondent":"竹田生活福祉課長","answer":"今後も、そういうことが継続するようなことが考えられる方については、家主にはご迷惑をかけない形で制度を運用していけるように努めるところです。必ず８０世帯を一つでも超えたからといって、法律に触れるということではないとは認識しております。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"こうしていけばケースワーカーの仕事も減ってくるんじゃないですかっていうリストみたいなものがあって当然だと、そういうものを教えてくださいと。８０人に一人というと、これをオーバーして９０人以上が、何のあれもないわけか尋ねました。","respondent":"竹田生活福祉課長","answer":"非常に対応に時間を要する方と、温度差がありますので、単純に人数比では比較できないところがあるのも事実です。ですから、非常勤職員等も活用しまして、手間のかかる方、時間を要しない方、それぞれケースに応じまして、今後も対応していきたいと考えております。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"確認","question":"もいいんだけれども、８０対１という法律があって、そこにどう見合わせていくのかということがあるではないですか。どうしてこういうことを言うかというと、大分以前に質問したときには、相手もそれなりの準備をするじゃないか尋ねました。","respondent":"竹田生活福祉課長","answer":"あるいは、課税台帳の調査を通しまして不正受給の発見は、全力で努めてまいりたいと考えています。都や国の意向を踏まえまして、そちらとも十分に協議しまして、より効率的な仕事の進め方を考えていきたいと考えています。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"例えば住宅扶助を振り込むというのは、全部振り込む制度にするというのは、品川区単独ではできないんですか。どうも８０対１がわからないので、その２点だけ、最後に教えてほしいと思います。","respondent":"竹田生活福祉課長","answer":"家賃等を全件振り込みにできないかというお尋ねですが、原則は、直接本人に振り込むことが原則となっております。我々も、ぜひとも法の数字に従うように、今後、知恵を出し合って進めていきたいと考えています。","id":"exchange-011"},{"speaker":"向委員","kind":"質問・要望","question":"まとめて何点か確認させていただきたいと思うんですが、品川区としてどう思うかとかもお尋ねはしたいんですが、一つちょっと数字をお尋ねしたいのが。今から３年前ですか、平成２４年度に入って、どれぐらい保護から外れたのかどうか。","respondent":"竹田生活福祉課長","answer":"生活保護から脱却した人がどれぐらいいるのかですが、昨年、就労開始によりまして制度を廃止したというものが２７世帯、２８人おります。就労可能な若い方につきましては、阻害要因を何とか解消させて、１件でも多く就労に結びつけたいと考えております。","id":"exchange-012"},{"speaker":"向委員","kind":"意見","question":"なぜこういった数字を聞きたかったかというと、今回、この中にあればなということがあったんです。これは、今後もちょっと機会があればお尋ねしたいと思っているので、このあたり引き続き調査等をお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"中塚副委員長","kind":"質問","question":"先ほどのやりとりの中で、家賃の支払いについて、可能かどうか探るとの説明がありましたが、それはどういう意味なのか伺いたいと思います。どのようにお考えなのか、所管事務調査ので、区の考えを伺いたいと思います。","respondent":"竹田生活福祉課長","answer":"家賃の支払いがおくれることのないよう、ご本人の意向を十分に踏まえまして、代理納付等を考えていきたいと考えております。この精神にのっとって、法の適切な執行をすることによって、区民にご理解いただけるように努めてまいりたいと考えています。","id":"exchange-014"},{"speaker":"中塚副委員長","kind":"質問","question":"第４条の１の生活保護の要件とありますけれども、扶養が生活保護の要件かどうか、区の認識を伺いたいと思います。冒頭３ページ目にあります保護の手続について説明がありましたが、事前調査を行っているのか、そこを伺いたいと思います。","respondent":"竹田生活福祉課長","answer":"ほかの施設とも連携をとりながら、やはり経済的な自立が欠かせないものだと考えておりますので、多方面から支援していきたいと考えております。十分にお話し合いをして検討した結果、生活保護を申請された方につきましては、申請後に調査しています。","id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問","question":"生活保護利用者が２００万人を突破するという事態をつくった背景は、これこそ正すべきだと思いますし、私は思います。一体改革法案の中にもいろいろ記されておりますが、率直に区の評価を伺いたいと思いますが、いかがか尋ねました。","respondent":"竹田生活福祉課長","answer":"今、国のほうでさまざまな検討がされているのは、ご承知のとおりです。生活保護法というのは、制定されて以来、一切改正されておりませんので、国の動きを関心を持って注視していきたいと考えております。","id":"exchange-016"},{"speaker":"若林委員","kind":"提案","question":"委員会として提案できることがあれば、今日はこの論点で議論、それについては提案させてほしいと求めました。中身については、今日はこの提案だけで終わらせていただきますとの意見を述べました。","respondent":"渡辺委員長","answer":"若林委員からのご提案について、各委員からの資料請求等も踏まえて、正副委員長で検討させていただいて、また返答したいと思います。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問","question":"では、私は、今日は具体的な質問をしないことにしましたので、今後、委員長、副委員長のほうに、こういう資料を出してもらいたい、こういう質問をしたいというものを出しますので、また各委員からあれば、適宜対応していただくようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"意見","question":"この場で、今お考えがあるなら、それはこういう資料要求、またはこういうものでお願いしたいと。はそれを取り上げるかどうかというのは正副委員長一任でいいと思うけれども、その前に、私は委員会としてやらないほうがいいと思うとの意見を述べました。","respondent":"渡辺委員長","answer":"高齢者の在宅支援の件もありまして、１２月になるのか、そのあたりでまたこの生活保護について取り上げさせていただきたいと思っています。","id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"意見","question":"現状に関しては最初から資料も出ないうちから、そういう発言が出るのはどうかなという気がします。ただ、不正受給者を減らすということと全く矛盾しないことだと思うので、その辺のことをやっぱりきちっと議論する必要があるのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その分の足りない分をぽっと出しているとか、そういう人とか、内容も分けてほしいんですよね。区がやれるところ、そこの資料を、ぜひつくっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"向委員","kind":"質問・要望","question":"５０％ぐらいいっているけれども、それに対して区としてはどういう印象を持っているのかとか、区としての考え方をやっぱり知りたいんです。先ほどの質問の中でも、三年たってどうなりましたかという数字に関しては、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"塚本委員","kind":"意見","question":"どういう形で活躍をしていただくというか、課題というか、議論したいところだと思っています。１日をどういうふうに過ごされているのかとか、どういうところで苦労されて、お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"若林委員","kind":"質問","question":"公ですから、一人当たりの医療費とかは出せるのかどうか、客観的にということですので。なお、ちょっと違うかもしれませんが、いわゆる公営住宅に入居されている方の人数、世帯数等もあれば、あわせてお聞きしておきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"一人が受け持つ人数というんですか、全体像も見えるのかなと思いましたので、そこは資料をつくるときに工夫していただきたいというのが一つです。どういう事業を行っているのか、他区と、東京都とそれぞれ資料を出してほしいと求めました。","respondent":"山田副区長","answer":"就労支援の関係については、今、検討に入ってあります。今は現金がないという方々に対しての就労支援という形で図っていくという大きな流れの中で、この辺は私の所感としてお願いをしておきたいと思います。","id":"exchange-025"},{"speaker":"若林委員","kind":"質問","question":"今の就労支援とか受給の継続というのは、今の副区長のご答弁で、ご理解してくださいという意味ですか。それとも、その主意は、ご容赦くださいという意味ではなくて、補足のご答弁で、資料もしっかり出せるものは出しますという理解か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"それに類似している場所とか、先方がこうだとかいうことがあったら、どうぞそれは正副委員長にお任せします。しっかり示していただければ、それで結構ですので、それだけ一言つけ加えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"若林委員","kind":"提案","question":"これは、正副委員長のご努力ということで承知いたしました。２班体制と、私も提案をさせていただいたんですが、どういうふうに理解したらいいかなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"渡辺委員長","kind":"提案","question":"ご提案いただいておりました委員会でのグループ別、２班で、というご提案について、正副委員長で協議をさせていただきました。そのほか、当然立地のこともありますが、一番効率よく、取り上げるべきテーマが地域性も含めて、この提案に行き着いたというのが説明になりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚副委員長","kind":"意見","question":"それによって、また周知の方法もいろいろ工夫もできるのかなと思うんですが、わからなかったので。要するに周知が大切だと思ったので、ちょっとそこを補足していただけたらとの意見を述べました。","respondent":"伊津野品川区保健所保健予防課長","answer":"対象年齢は、従来どおり生後３カ月から７歳６カ月未満の小児です。周知方法としましては、８月下旬、対象者に接種票を送付したいと考えています。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594819?Template=document&Id=3330#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":32593,"voices":67}}]);
